        #region BACK

        #region BtnCancel_Click
        private void BtnCancel_Click(object sender, System.EventArgs e)
        {
            try
            {
                if (lblSearchMode.Text == Tabbed_Mode.Basic)
                {
                    if (TDSMAN.Classes.TDSMAN.T_pVersionType == T_VERSION_TYPE.PUBLICATION_HOUSE_VERSION)
                    {
                        cmnService.J_UserMessage("Not available in this version");
                        return;
                    }
                    else if (TDSMAN.Classes.TDSMAN.T_pVersionType == T_VERSION_TYPE.TRIAL_VERSION)
                    {
                        //if (txtQtr.Text != T_Qtr.Q1)
                        //{
                        //    TrnTrialMessageBox TrialMessageBox = new TrnTrialMessageBox();
                        //    TrialMessageBox.StartPosition = FormStartPosition.CenterScreen;
                        //    TrialMessageBox.lblMessage2.Text = "Correction Return can only be generated for the first quarter using the Trial Version.";
                        //    TrialMessageBox.Show();
                        //    return;
                        //}
                        //--####################
                        if (TdsMan.AllowTrialReturn(txtFAYear.Text, lngBatchId, true) == false)
                        {
                            TrnTrialMessageBox TrialMessageBox = new TrnTrialMessageBox();
                            TrialMessageBox.StartPosition = FormStartPosition.CenterScreen;
                            //TrialMessageBox.lblMessage2.Text = "Return cannot be generated as the trial version supports only " + TDSMAN.Classes.TDSMAN.T_pMaxDeducteeDetailsCount + " nos. of deductee records in total.";
                            TrialMessageBox.lblMessage2.Text = "Return cannot be generated as the trial version supports only 1 return in total";
                            TrialMessageBox.Show();
                            return;
                        }
                        //--####################
                    }
                    //
                    string strSQL1 = "SELECT MODE FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + lngBatchId;
                    if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL1)) != T_CorrectionMode.TANUpdation)
                    {
                        if (cmnService.J_ReturnInt64Value(txtCorrections.Text.Trim()) == 0)
                        {
                            cmnService.J_UserMessage("No Corrections made");
                            return;
                        }

                    }
                    //-- ANIK @ 2013/09/26 for FVU 4.0
                    strSQL = "SELECT COUNT(*) " +
                             "FROM  COR_TRN_CHALLAN " +
                             "LEFT JOIN (SELECT COUNT(*) AS COUNT_REC, TRN_CHALLAN_ID FROM COR_TRN_DEDUCTEE_DETAILS GROUP BY TRN_CHALLAN_ID) AS DED " +
                             "ON COR_TRN_CHALLAN.TRN_CHALLAN_ID       = DED.TRN_CHALLAN_ID " +
                             "WHERE COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId + " " +
                             "AND   " + cmnService.J_SQLDBFormat("DED.COUNT_REC", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + " = 0 " +
                             "AND   COR_TRN_CHALLAN.TOT_TAX        = 0 " +
                             "AND   COR_TRN_CHALLAN.HDR_CHALLAN_ID = 0";
                    if (Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL)) > 0)
                    {
                        cmnService.J_UserMessage("Nil challans/transfer vouchers need to mandatorily have Deductee records");
                        return;
                    }
                    //-- //-- SHOW WARNING MESSAGE DURING LATE PAYMENTS / SHORT DEDUCTIONS
                    #region WARNING MESSAGE
                    bool blnShortDeductions = false; bool blnLatePayments = false;
                    //--
                    #region SUMMARY SHORT DEDUCTIONS
                    //--
                    string strActualAmtCreation = @"IIF(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL' " +
                                           @"OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANAPPLIED' " +
                                           @"OR COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANINVALID', " +
                                           @"ROUND((COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE ) / 100,0), 
                                    IIF(MID(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'P' OR MID(COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN, 4, 1) = 'H', " +
                                           @"ROUND((COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE ) / 100,0), 
                                    ROUND((COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.COMPANY_RATE ) / 100,0)))";
                    strSQL = @"SELECT COUNT(*) " +
                             @"FROM   COR_TRN_DEDUCTEE_DETAILS,
                                      MST_NONSALARY_TAX_SLAB 
                              WHERE  COR_TRN_DEDUCTEE_DETAILS.SECTION_ID = MST_NONSALARY_TAX_SLAB.SECTION_ID  
                              AND    COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE BETWEEN MST_NONSALARY_TAX_SLAB.FROM_DATE AND MST_NONSALARY_TAX_SLAB.TO_DATE
                              AND    COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID = " + lngBatchId + " " +
                            @"AND    COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT < " + strActualAmtCreation + " " +
                            @"AND    COR_TRN_DEDUCTEE_DETAILS.REASON_ID IN (3,7,15,4,12,17,20)";
                    long lngShortDeductionsCount = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));
                    if (lngShortDeductionsCount > 0)
                    {
                        blnShortDeductions = true;
                    }
                    //
                    #endregion
                    //--
                    #region SUMMARY LATE PAYMENTS
                    string strLastDateCreation = "IIF(COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NULL, COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE, " +
                                          "IIF(MONTH(COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE) = 3, " +
                                                  "CDATE(" + "\"30\"" + "+" + "RIGHT(CDATE(DATEADD(" + "\"M\"" + ", 1, " +
                                                  cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ")), 8)), " +
                                                  "CDATE(" + "\"07\"" + "+" + "RIGHT(CDATE(DATEADD(" + "\"M\"" + ", 1, " +
                                                  cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + ")), 8)) " +
                                                "))";
                    strSQL = @"SELECT SUM(COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT * 0.015 * (1 + DATEDIFF('m'," + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "," + cmnService.J_SQLDBFormat("COR_TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "))) AS LATE_FEE " +
                             @"FROM   COR_TRN_CHALLAN, 
                                      COR_TRN_DEDUCTEE_DETAILS 
                               WHERE  COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID = COR_TRN_CHALLAN.TRN_CHALLAN_ID 
                               AND    COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID  = " + lngBatchId + " " +
                             @"AND    COR_TRN_CHALLAN.DEPOSIT_DATE   > " + strLastDateCreation + " " +
                              "AND    COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE IS NOT NULL";
                    double dblLatePaymentsAmt = cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));
                    //
                    strSQL = "SELECT SUM(INTEREST_ALLOCATED) FROM COR_TRN_CHALLAN WHERE BATCH_HEADER_ID = " + lngBatchId + " ";
                    double dblInterestPaymentAmt = cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));
                    if (dblLatePaymentsAmt > dblInterestPaymentAmt)
                    {
                        blnLatePayments = true;
                    }
                    //
                    #endregion
                    //--
                    if (blnShortDeductions == true || blnLatePayments == true)
                    {
                        if (cmnService.J_UserMessage("This return is having potential defaults.\n\nClick on 'Yes' to predict defaults for this return, else click on 'No' to continue with return generation.", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button1) == DialogResult.Yes)
                        {
                            btnPredictDefaults_Click(sender, e);
                            return;
                        }
                    }
                    #endregion
                    //--                                                   
                    btnGenerateReturns_Click(sender, e);
                }
                else
                {
                    lblMode.Text = J_Mode.View;
                    lblMode.ForeColor = Color.Yellow;

                    lblSearchMode.Text = Tabbed_Mode.Basic;

                    //
                    blnOpenTabPage = true;
                    tbcCompany.SelectTab(tbpBasicInformation);

                    //cmbMain_SelectedIndexChanged(sender, e);
                    ////---------------------------------------------
                    BtnSave.Enabled = false;
                    BtnSave.BackColor = Color.LightGray;
                    //--
                    btnChallanDeducteeEntry.Enabled = true;
                    btnChallanDeducteeEntry.BackColor = Color.Lavender;
                    //--
                    btnChallanDeducteeEntry.Text = "Proceed to Corrections";
                    BtnCancel.Text = "Generate Returns";
                    //--
                    BtnEdit.Enabled = false;
                    BtnEdit.BackColor = Color.LightGray;
                    //--
                    BtnDelete.Text = T_DeleteRestoreText.Delete;
                    BtnDelete.Enabled = false;
                    BtnDelete.BackColor = Color.LightGray;
                    ////--
                    btnSalaryDetail.Visible = false;
                    ////--
                    BtnSearch.Enabled = false;
                    BtnSearch.BackColor = Color.LightGray;
                    ////--
                    BtnSort.Enabled = false;
                    BtnSort.BackColor = Color.LightGray;
                    ////--
                    BtnRefresh.Enabled = false;
                    BtnRefresh.BackColor = Color.LightGray;
                    //--
                    //BtnSort_Click(sender, e);
                    //
                    grpSearch.Visible = false;
                    grpSearchDeductee.Visible = false;
                    lblMsgDisplay.Visible = false;
                    //grpMain.Enabled = true;           
                    //
                    ShowCorrectionSummary(lngBatchId);

                    //Added by Shrey Kejriwal on 03/11/2011
                    btnExcelActivate.Visible = false;

                    //Blocked for this version
                    btnExcelActivate.Visible = true; //Modified on 26/10/2012
                    btnExcelActivate.Text = "Advanced Party Search";


                    //
                    //if (txtFormNo.Text.Trim() == T_FormNo.F24Q && txtQtr.Text.Trim() == T_Qtr.Q4)
                    //    btnSalaryDetail.Visible = true;
                    //else
                    //    btnSalaryDetail.Visible = false;
                    //---------------------------------------------
                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
