        #region btnGenerateReturns_Click
        private void btnGenerateReturns_Click(object sender, EventArgs e)
        {
            //if (cmnService.J_ReturnInt32Value(txtTotalChallanRecords.Text) <= 0)
            //{
            //    cmnService.J_UserMessage("At least one Challan needed for File Generation");
            //    btnChallanDeducteeEntry.Select();
            //    return;
            //}
            //
            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT D_CATEGORY_ID FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + lngBatchId)) == "0")
            {
                cmnService.J_UserMessage("Deductor Type needed");
                btnChallanDeducteeEntry.Select();
                return;
            }
            //
            //
            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT BATCH_HEADER_ID FROM COR_HDR_BATCH WHERE BATCH_HEADER_ID = " + lngBatchId + " AND ORIGINAL_RRR_NO <>''")) == "")
            {
                cmnService.J_UserMessage("Original Provisional Receipt Number needed");
                btnChallanDeducteeEntry.Select();
                return;
            }
            //
            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT BATCH_HEADER_ID FROM COR_HDR_BATCH WHERE BATCH_HEADER_ID = " + lngBatchId + " AND PREVIOUS_RRR_NO <>''")) == "")
            {
                cmnService.J_UserMessage("Previous Provisional Receipt Number needed");
                btnChallanDeducteeEntry.Select();
                return;
            }
            //--
            if (TdsMan.IsUacEnabled() == true)
                cmnService.J_UserMessage("UAC (User Account Control) is enabled in your machine, which may restrict text file generation and FVU file creation.\n" +
                    "Please disable the UAC settings or call our Customer Care for technical assistance.", MessageBoxIcon.Exclamation);
            //--
            grpGenerateReturns.Visible = true;
            //
            //grpMain.Enabled = false;
            //grpNILReturn.Enabled = false;
            //grpAddressChange.Enabled = false;
            //
            btnChallanDeducteeEntry.Enabled = false;
            btnChallanDeducteeEntry.BackColor = Color.LightGray;
            //
            btnExcelActivate.Enabled = false;
            btnExcelActivate.BackColor = Color.LightGray;
            //
            BtnCancel.Enabled = false;
            BtnCancel.BackColor = Color.LightGray;
            //
            btnSalaryDetail.Visible = false;
            // CANCEL
            //BtnSort.Enabled = true;
            //BtnSort.BackColor = Color.Lavender;
            //
            btnOpenOutputFolder.Enabled = false;
            btnOpenOutputFolder.BackColor = Color.LightGray;

            //Added by Shrey Kejriwal on 01/04/2014
            //Disable button for FVU generated Form 27A for returns not validated.
            btnFVU27A.Enabled = false;
            btnFVU27A.BackColor = Color.LightGray;

            if (txtFormNo.Text == T_FormNo.F27EQ)
            {
                btnFVU27A.Text = "27B (FVU)";
            }
            else
            {
                btnFVU27A.Text = "27A (FVU)";
            }


            //
            lblGenerateTDSMessage.Visible = true;
            lblGenerateTDSMessage.Text = "TDS filing involves following steps :";
            lblGenerateTDSMessage1.Text = " 1. Generation of text file. \n 2. Creation of FVU file using the text file. \n 3. Printing of Form 27A.";

            //lblAutomaticCSIFileDownloadMessage.Text = "To verify Challan data with Income Tax Dept. records (Internet Connection required)";

            //txtAssessmentYear.Text = TdsMan.T_ReturnAssessmentYear(cmbFinancialYear.Text);

            txtInputFileName.Text = "";

            txtOutputFolder.Text = Path.Combine(Application.StartupPath, "FVU Files\\" + txtTAN.Text + "\\" +
                                                                                         txtFAYear.Text + "\\" +
                                                                                         txtFormNo.Text + "\\" +
                                                                                         txtQtr.Text);
            EnabilityLastGenerationStatus(lngBatchId, false);
            //
            if (txtFormNo.Text.Trim() == T_FormNo.F27EQ)
                btnPrint27A.Text = "Print 27B";
            else
                btnPrint27A.Text = "Print 27A";
            //
            //chkCSIFileDownload.Enabled = true;

            //Checking if CSI file should be downloaded
            //i.e checking if any non challans is used in this return

            strSQL = "SELECT COUNT(*) " +
                     "FROM COR_TRN_CHALLAN " +
                     "WHERE TOT_TAX > 0 " +
                     "AND   BOOK_ENTRY = 0 " +
                     "AND   (CHALLAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " " +
                     "       OR MODE = '" + T_CorrectionMode.C9 + "') " +
                     "AND   BATCH_HEADER_ID = " + lngBatchId;

            int intCount = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL));

            if (intCount == 0) //No Challan found
            {
                chkCSIFileDownload.Checked = false;
                chkCSIFileDownload.Enabled = false;
            }
            else
            {
                chkCSIFileDownload.Enabled = true;
                chkCSIFileDownload.Checked = true;

                //Now checking if the Internet Connection is present 
                //and accordingly selecting the Automatic CSI file download option

                //if (TdsMan.T_CheckInternetConnectivty() == true)
                //    chkCSIFileDownload.Checked = true;
                //else
                //    chkCSIFileDownload.Checked = false;
            }

            btnGenerateTextFile.Select();

        }
        #endregion

        #region SEARCH BATCH

        #region btnSearchBatchOk_Click
        private void btnSearchBatchOk_Click(object sender, EventArgs e)
        {
            strCheckFields = "";
            //----------------------------------------------------------------------
            //-- FA YEAR
            //----------------------------------------------------------------------
            if (cmbFAYearSearchBatch.SelectedIndex > 0)
                strCheckFields = strCheckFields + "AND MST_ASSESSMENT.FA_YEAR ='" + cmbFAYearSearchBatch.Text + "' ";
            //----------------------------------------------------------------------
            //-- FORM
            //----------------------------------------------------------------------
            if (cmbFormSearchBatch.SelectedIndex > 0)
                strCheckFields = strCheckFields + "AND COR_HDR_BATCH.FORM_NO ='" + cmbFormSearchBatch.Text + "' ";
            //----------------------------------------------------------------------
            //-- QTR
            //----------------------------------------------------------------------
            if (cmbQtrSearchBatch.SelectedIndex > 0)
                strCheckFields = strCheckFields + "AND COR_HDR_BATCH.QTR ='" + cmbQtrSearchBatch.Text + "' ";
            //----------------------------------------------------------------------
            //-- COMPANY NAME
            //----------------------------------------------------------------------
            if (txtCompanySearchBatch.Text.Trim() != "")
                strCheckFields = strCheckFields + "AND COR_TRN_COMPANY.COMPANY_NAME like '%" + cmnService.J_ReplaceQuote(txtCompanySearchBatch.Text.Trim().ToUpper()) + "%' ";
            //----------------------------------------------------------------------
            //-- TAN
            //----------------------------------------------------------------------
            if (txtTANSearchBatch.Text.Trim() != "")
                strCheckFields = strCheckFields + "AND COR_TRN_COMPANY.TAN_NO like '" + cmnService.J_ReplaceQuote(txtTANSearchBatch.Text.Trim().ToUpper()) + "%' ";
            //-----------------------------------------------------------
            strSQL = strQuery + strCheckFields + " ORDER BY " + strOrderBy;
            //-----------------------------------------------------------
            if (dsetBatchGridClone != null) dsetBatchGridClone.Clear();
            dsetBatchGridClone = dmlService.J_ShowDataInGrid(ref  dgcViewBatch, strSQL, strMatrixBatchGrid);       //Show Data into the Grid
            //
            lblMode.Text = J_Mode.Add;
            //----------------------------------------------------------------------
            grpSearchBatch.Visible = false;
        }
