        #region BtnSearch_Click
        private void BtnSearch_Click(object sender, System.EventArgs e)
        {
            try
            {
                //Added by Indrajit on 04-03-2013
                strCheckFields = "";
                //-------------------------------------------
                //lblSearchMode.Text = J_Mode.Searching;
                lblMode.Text = J_Mode.Searching;
                //-------------------------------------------
                if (ValidateFields() == false) return;
                //-------------------------------------------
                grpSort.Visible = false;
                //-------------------------------------------
                //if (dgcViewChallan.Visible == true)
                if (lblSearchMode.Text == Tabbed_Mode.Batch)
                {
                    grpSearchBatch.Visible = true;
                    grpSearchBatch.Location = new Point(677, 307);
                    //-----------
                    //-- FINANCIAL YEAR
                    //-----------
                    strSQL = " SELECT ASST_ID," +
                        "             FA_YEAR " +
                        "      FROM   MST_ASSESSMENT " +
                        "      WHERE  VISIBILITY_FLAG = 0 " +
                        "      ORDER BY ASST_ID DESC";
                    if (dmlService.J_PopulateComboBox(strSQL, ref cmbFAYearSearchBatch) == false) return;
                    //-----------
                    //-- FORM
                    //-----------
                    string[] strForm ={ T_FormNo.F24Q, T_FormNo.F26Q, T_FormNo.F27Q, T_FormNo.F27EQ };
                    dmlService.J_PopulateComboBox(strForm, ref cmbFormSearchBatch);
                    //-----------
                    //-- QUARTER
                    //-----------
                    string[] strQtr ={ T_Qtr.Q1, T_Qtr.Q2, T_Qtr.Q3, T_Qtr.Q4 };
                    dmlService.J_PopulateComboBox(strQtr, ref cmbQtrSearchBatch);
                    //
                    txtCompanySearchBatch.Text = "";
                    txtTANSearchBatch.Text = "";
                    //
                    cmbFAYearSearchBatch.Select();
                }
                else if (lblSearchMode.Text == Tabbed_Mode.Challan)
                {
                    grpSearch.Visible = true;
                    grpSearch.Location = new Point(677, 307);
                    //-------------------------------------------
                    // SEARCH MODE

                    txtSlNoSearch.Text = "";
                    //-----------
                    //-- SECTION
                    //-----------
                    //----------------------------------------------------------------------
                    //-- SECTION NO.
                    //----------------------------------------------------------------------
                    if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2013_14ID)
                    {
                        label109.Visible = false;
                        cmbSectionNoSearch.Visible = false;
                    }
                    else
                    {
                        label109.Visible = true;
                        cmbSectionNoSearch.Visible = true;
                        strSQL = " SELECT SECTION_ID," +
                            "             SECTION_NO " +
                            "      FROM   MST_SECTION " +
                            "      WHERE  FORM_NAME = '" + txtFormNo.Text.Trim() + "' " +
                            "      AND    ASST_ID <= " + Convert.ToInt32(txtFAYearID.Text) + " " +
                            "      ORDER BY SECTION_ID";
                        if (dmlService.J_PopulateComboBox(strSQL, ref cmbSectionNoSearch) == false) return;
                    }
                    //-----------                
                    mskDepositDateSearch.Text = "";
                    txtChallanNoSearch.Text = "";
                    txtTransferVoucherNoSearch.Text = "";

                    txtSlNoSearch.Select();
                }
                //else if(dgcViewChallanDetails.Visible == true)
                else if (lblSearchMode.Text == Tabbed_Mode.Deductee)
                {
                    grpSearchDeductee.Visible = true;
                    grpSearchDeductee.Location = new Point(677, 307);
                    //-------------------------------------------
                    // SEARCH MODE

                    txtSlNoDSearch.Text = "";
                    txtPANSearch.Text = "";
                    txtDeducteeNameSearch.Text = "";
                    mskDateSearch.Text = "";

                    txtSlNoDSearch.Select();
                    //
                }
                //-------------------------------------------
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region BtnSearchOK_Click
        private void BtnSearchOK_Click(object sender, System.EventArgs e)
        {
            try
            {
                //----------------------------------------------------------------------
                //-- In case the user enters a blank user name -------------------------
                //----------------------------------------------------------------------
                if (ValidateFields() == false) return;
                //----------------------------------------------------------------------
                strCheckFields = "";
                //if (dgcViewChallan.Visible == true)
                if (lblSearchMode.Text == Tabbed_Mode.Challan)
                {
                    //----------------------------------------------------------------------
                    //-- SL. NO.
                    //----------------------------------------------------------------------
                    if (txtSlNoSearch.Text.Trim() != "")
                        strCheckFields = strCheckFields + "AND COR_TRN_CHALLAN.SL_NO = " + cmnService.J_ReturnDoubleValue(txtSlNoSearch.Text) + " ";
                    //----------------------------------------------------------------------
                    //-- SECTION NO.
                    //----------------------------------------------------------------------
                    if (cmbSectionNoSearch.SelectedIndex > 0)
                    //----------------------------------------------------------------------
                    strCheckFields = strCheckFields + "AND MST_SECTION.SECTION_ID = " + Convert.ToInt32(Support.GetItemData(cmbSectionNoSearch, cmbSectionNoSearch.SelectedIndex)) + " ";
                    //----------------------------------------------------------------------
                    //-- CHALLAN NO
                    //----------------------------------------------------------------------
                    if (txtChallanNoSearch.Text.Trim() != "")
                        strCheckFields = strCheckFields + "AND COR_TRN_CHALLAN.CHALLAN_NO like '%" + cmnService.J_ReplaceQuote(txtChallanNoSearch.Text.Trim().ToUpper()) + "%' ";
                    //----------------------------------------------------------------------
                    //-- TRANSFER VOUCHER NO
                    //----------------------------------------------------------------------
                    if (txtTransferVoucherNoSearch.Text.Trim() != "")
                        strCheckFields = strCheckFields + "AND COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO like '%" + cmnService.J_ReplaceQuote(txtTransferVoucherNoSearch.Text.Trim().ToUpper()) + "%' ";
                    //----------------------------------------------------------------------
                    //-- DEPOSIT DATE
                    //----------------------------------------------------------------------
                    if (dtService.J_IsBlankDateCheck(ref mskDepositDateSearch, J_ShowMessage.NO) == false)
                        strCheckFields = strCheckFields + "AND COR_TRN_CHALLAN.DEPOSIT_DATE =  " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskDepositDateSearch) + cmnService.J_DateOperator() + " ";
                    //----------------------------------------------------------------------
                    strSQL = strQuery + strCheckFields + strGroupBy + "ORDER BY " + strOrderBy;
                    //----------------------------------------------------------------------

                    if (dsetGridClone != null) dsetGridClone.Clear();
                    dsetGridClone = dmlService.J_ShowDataInGrid(dmlService.J_pCommand, ref dgvViewChallan, strSQL, strMatrix);       //Show Data into the Grid
                    if (dsetGridClone == null) return;


                    //----------------------------------------------------------------------
                    //if (dmlService.J_setGridPosition(ref dgvViewChallan, dsetGridClone, lngTempChallanId) == false)
                    //{
                    //    txtSlNoSearch.Select();
                    //    return;
                    //}
                    //----------------------------------------------------------------------
                    if (dgvViewChallan.CurrentRow != null)
                    {
                        if (lblMode.Text == J_Mode.Add)
                        {
                            btnChallanDeducteeEntry.Enabled = true;
                            btnChallanDeducteeEntry.BackColor = Color.Lavender;
                            //
                            BtnEdit.Enabled = true;
                            BtnEdit.BackColor = Color.Lavender;
                        }
                    }
                    else
                    {
                        btnChallanDeducteeEntry.Enabled = false;
                        btnChallanDeducteeEntry.BackColor = Color.LightGray;

                        BtnDelete.Enabled = false;
                        BtnDelete.BackColor = Color.LightGray;

                        BtnEdit.Enabled = false;
                        BtnEdit.BackColor = Color.LightGray;

                    }
                    //----------------------------------------------------------------------
                    //lblSearchMode.Text = J_Mode.General;
                    lblMode.Text = J_Mode.Add;
                    //----------------------------------------------------------------------
                    grpSearch.Visible = false;
                    //----------------------------------------------------------------------
                }
                //else if (dgcViewChallanDetails.Visible == true)
                else if (lblSearchMode.Text == Tabbed_Mode.Deductee)
                {
                    //----------------------------------------------------------------------
                    //-- SL. NO.
                    //----------------------------------------------------------------------
                    if (txtSlNoDSearch.Text.Trim() != "")
                        strCheckFields = strCheckFields + "AND COR_TRN_DEDUCTEE_DETAILS.SL_NO = " + cmnService.J_ReturnDoubleValue(txtSlNoDSearch.Text) + " ";
                    //----------------------------------------------------------------------
                    //-- DEDUCTEE PAN
                    //----------------------------------------------------------------------
                    if (txtPANSearch.Text.Trim() != "")
                        strCheckFields = strCheckFields + "AND COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN ='" + cmnService.J_ReplaceQuote(txtPANSearch.Text.Trim().ToUpper()) + "' ";
                    //----------------------------------------------------------------------
                    //-- DEDUCTEE NAME
                    //----------------------------------------------------------------------
                    if (txtDeducteeNameSearch.Text.Trim() != "")
                        strCheckFields = strCheckFields + "AND COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME like '" + cmnService.J_ReplaceQuote(txtDeducteeNameSearch.Text.Trim().ToUpper()) + "%' ";
                    //----------------------------------------------------------------------
                    //-- DEPOSIT DATE
                    //----------------------------------------------------------------------
                    if (dtService.J_IsBlankDateCheck(ref mskDateSearch, J_ShowMessage.NO) == false)
                        strCheckFields = strCheckFields + "AND COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE =  " + cmnService.J_DateOperator() + dtService.J_ConvertMMddyyyy(mskDateSearch) + cmnService.J_DateOperator() + " ";
                    //----------------------------------------------------------------------
                    strSQL = strQuery + strCheckFields + "ORDER BY " + strOrderBy;
                    //----------------------------------------------------------------------

                    if (dsetGridClone != null) dsetGridClone.Clear();
                    dsetGridClone = dmlService.J_ShowDataInGrid(dmlService.J_pCommand, ref dgvDeductee, strSQL, strMatrix);       //Show Data into the Grid
                    if (dsetGridClone == null) return;
                    //----------------------------------------------------------------------

                    dgvDeductee_Click(sender, e);

                    if (dgvDeductee.CurrentRow == null)
                    {
                        BtnEdit.Enabled = false;
                        BtnEdit.BackColor = Color.LightGray;

                        BtnDelete.Enabled = false;
                        BtnDelete.BackColor = Color.LightGray;

                    }
                    else
                    {
                        BtnEdit.Enabled = true;
                        BtnEdit.BackColor = Color.Lavender;

                        BtnDelete.Enabled = true;
                        BtnDelete.BackColor = Color.Lavender;

                    }

                    //----------------------------------------------------------------------
                    //lblSearchMode.Text = J_Mode.General;
                    lblMode.Text = J_Mode.Add;
                    //----------------------------------------------------------------------
                    grpSearchDeductee.Visible = false;
                    //----------------------------------------------------------------------
                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

