                    txtChallanSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("COR_TRN_CHALLAN", "SL_NO", "BATCH_HEADER_ID = " + lngBatchId + "") + 1);
                }
                else if (lblSearchMode.Text == Tabbed_Mode.Deductee)
                {
                    //REFRESH EVENT FOR DEDUCTEE DETAIL PAGE

                    BackgroundColorChangeDeductee(lblMode.Text);

                    //Added by Shrey Kejriwal on 23/02/2012
                    Return_Next_Deductee_Record_no();
                    //--
                    BtnSearch.Enabled = true;
                    BtnSearch.BackColor = Color.Lavender;
                    //--
                    BtnRefresh.Enabled = true;
                    BtnRefresh.BackColor = Color.Lavender;
                    //@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
                    grpSearchDeductee.Visible = false;

                    strCheckFields = "";
                    strSQL = strQuery + "ORDER BY " + strOrderBy;
                    lngTempDeducteeId = lngDeducteeID;
                    //-----------------------------------------------------------
                    if (dsetGridClone != null) dsetGridClone.Clear();
                    dsetGridClone = dmlService.J_ShowDataInGrid(ref dgvDeductee, strSQL, strMatrix);       //Show Data into the Grid
                    if (dsetGridClone == null) return;
                    //-----------------------------------------------------------
                    dmlService.J_setGridPosition(ref dgvDeductee, dsetGridClone, lngTempDeducteeId);
                }
                //-----------------------------------------------------------
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
