        #region BtnDelete_Click
        private void BtnDelete_Click(object sender, EventArgs e)
        {
            if (lblMode.Text == J_Mode.Edit)
                return;

            lblMode.Text = J_Mode.Delete;

            grpSearch.Visible = false;
            grpSearchDeductee.Visible = false;

            if (lblSearchMode.Text == Tabbed_Mode.Batch)
            {
                if (dgcViewBatch.RowCount <= 0)
                {
                    cmnService.J_UserMessage("No data to Delete !!");
                    return;
                }
                //--
                if (cmnService.J_UserMessage("It will Delete all the data of the selected batch.\nProceed?", MessageBoxButtons.YesNo, MessageBoxIcon.Error, MessageBoxDefaultButton.Button2) == DialogResult.No)
                    return;
                //--                            
                dmlService.J_BeginTransaction();
                //
                //if (txtFormNo.Text == T_FormNo.F24Q && txtQtr.Text == T_Qtr.Q4)
                //{ Modified by Shrey Kejriwal on 08/08/2011
                // SALARY_DETAILS
                strSQL = "DELETE FROM COR_TRN_SALARY_DETAILS WHERE BATCH_HEADER_ID =  " + lngBatchId + "";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    lblMode.Text = J_Mode.View;
                    //cmbSection.Select();
                    return;
                }
                strSQL = "DELETE FROM COR_HDR_SALARY_DETAILS WHERE BATCH_HEADER_ID =  " + lngBatchId + "";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    lblMode.Text = J_Mode.View;
                    //cmbSection.Select();
                    return;
                }
                //}
                // DEDUCTEE_DETAILS
                strSQL = "DELETE FROM COR_TRN_DEDUCTEE_DETAILS WHERE BATCH_HEADER_ID =  " + lngBatchId + "";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    lblMode.Text = J_Mode.View;
                    //cmbSection.Select();
                    return;
                }
                strSQL = "DELETE FROM COR_HDR_DEDUCTEE_DETAILS WHERE BATCH_HEADER_ID =  " + lngBatchId + "";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    lblMode.Text = J_Mode.View;
                    //cmbSection.Select();
                    return;
                }
                // CHALLAN
                strSQL = "DELETE FROM COR_TRN_CHALLAN WHERE BATCH_HEADER_ID =  " + lngBatchId + "";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    lblMode.Text = J_Mode.View;
                    //cmbSection.Select();
                    return;
                }
                strSQL = "DELETE FROM COR_HDR_CHALLAN WHERE BATCH_HEADER_ID =  " + lngBatchId + "";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    lblMode.Text = J_Mode.View;
                    //cmbSection.Select();
                    return;
                }
                // COMPANY
                strSQL = "DELETE FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID =  " + lngBatchId + "";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    lblMode.Text = J_Mode.View;
                    //cmbSection.Select();
                    return;
                }
                strSQL = "DELETE FROM COR_HDR_COMPANY WHERE BATCH_HEADER_ID =  " + lngBatchId + "";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    lblMode.Text = J_Mode.View;
                    //cmbSection.Select();
                    return;
                }
                // COR_HDR_BATCH
                strSQL = "DELETE FROM COR_HDR_BATCH WHERE BATCH_HEADER_ID =  " + lngBatchId + "";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    lblMode.Text = J_Mode.View;
                    //cmbSection.Select();
                    return;
                }
                //
                dmlService.J_Commit();
                //
                UpdateTotalCorrection();
                LoadBatch();
                //
                dgcViewBatch_Click(sender, e);
                if (lngBatchId == 0)
                {
                    btnChallanDeducteeEntry.Enabled = false;
                    btnChallanDeducteeEntry.BackColor = Color.LightGray;
                    //
                    BtnDelete.Enabled = false;
                    BtnDelete.BackColor = Color.LightGray;
                    //
                    BtnSearch.Enabled = false;
                    BtnSearch.BackColor = Color.LightGray;
                    //--
                    BtnRefresh.Enabled = false;
                    BtnRefresh.BackColor = Color.LightGray;
                    //
                    return;
                }
                else
                {
                    btnChallanDeducteeEntry.Enabled = true;
                    btnChallanDeducteeEntry.BackColor = Color.Lavender;
                    //
                    BtnDelete.Enabled = true;
                    BtnDelete.BackColor = Color.Lavender;
                    //
                    BtnSearch.Enabled = true;
                    BtnSearch.BackColor = Color.Lavender;
                    //--
                    BtnRefresh.Enabled = true;
                    BtnRefresh.BackColor = Color.Lavender;
                    //
                }
                //                
                lblMode.Text = J_Mode.View;
                return;
            }
            else if (lblSearchMode.Text == Tabbed_Mode.Challan)
            {
                Insert_Update_Delete_Data();
            }
            else if (lblSearchMode.Text == Tabbed_Mode.Deductee)
            {
                if (BtnDelete.Text == T_DeleteRestoreText.Delete)
                {
                    //DELETING THE DATA
                    Insert_Update_Delete_Data();
                    dgvDeductee_Click(sender, e);

                }
                else
                {
                    if (cmnService.J_UserMessage("Are you sure you want to restore this deleted data", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button1) == DialogResult.No)
                        return;

                    //RESTORING THE DELETED DATA
                    strSQL = "SELECT MODE FROM COR_TRN_DEDUCTEE_DETAILS WHERE TRN_DEDUCTEE_DETAIL_ID = " + lngDeducteeID + " ";
                    if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) != T_CorrectionMode.Delete)
                    {
                        cmnService.J_UserMessage("Only Deleted data can be Restored");
                        return;
                    }

                    // -- CHECK DIFFERENCE WITH TDS
                    strSQL = "SELECT TAX_DEPOSITED_AMOUNT FROM COR_TRN_DEDUCTEE_DETAILS WHERE TRN_DEDUCTEE_DETAIL_ID = " + lngDeducteeID + " ";
                    if (cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))) > cmnService.J_ReturnDoubleValue(txtViewChallanDetailsDifference.Text.Trim()))
                    {
                        lblMode.Text = J_Mode.Add;
                        cmnService.J_UserMessage("You can't restore as Tax deposited exceeds the Difference amount");
                        return;
                    }
                    //
                    strSQL = "UPDATE COR_TRN_DEDUCTEE_DETAILS " +
                        "     SET    MODE = '' " +
                        "     WHERE  TRN_DEDUCTEE_DETAIL_ID = " + lngDeducteeID;
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        return;
                    }
                    // UPDATE TDS
                    double dblSumValues = cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT TAX_AMOUNT FROM COR_TRN_DEDUCTEE_DETAILS WHERE TRN_DEDUCTEE_DETAIL_ID =  " + lngDeducteeID)));
                    strSQL = "UPDATE COR_TRN_CHALLAN SET " +
                        "            CTRL_TDS = CTRL_TDS + " + dblSumValues + " " +
                        "     WHERE  TRN_CHALLAN_ID   = " + lngChallanID;

                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        txtDeducteeName.Select();
                        return;
                    }

                    // UPDATE SURCHARGE
                    dblSumValues = cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SURCHARGE_AMOUNT FROM COR_TRN_DEDUCTEE_DETAILS WHERE TRN_DEDUCTEE_DETAIL_ID =  " + lngDeducteeID)));
                    strSQL = "UPDATE COR_TRN_CHALLAN SET " +
                        "            CTRL_SURCHARGE = CTRL_SURCHARGE + " + dblSumValues + " " +
                        "     WHERE  TRN_CHALLAN_ID   = " + lngChallanID;

                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        txtDeducteeName.Select();
                        return;
                    }

                    // UPDATE CESS
                    dblSumValues = cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT CESS_AMOUNT FROM COR_TRN_DEDUCTEE_DETAILS WHERE TRN_DEDUCTEE_DETAIL_ID =  " + lngDeducteeID)));
                    strSQL = "UPDATE COR_TRN_CHALLAN SET " +
                        "            CTRL_EDU_CESS = CTRL_EDU_CESS + " + dblSumValues + " " +
                        "     WHERE  TRN_CHALLAN_ID   = " + lngChallanID;

                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        txtDeducteeName.Select();
                        return;
                    }

                    // UPDATE TOTAL
                    dblSumValues = cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT TOTAL_AMOUNT FROM COR_TRN_DEDUCTEE_DETAILS WHERE TRN_DEDUCTEE_DETAIL_ID =  " + lngDeducteeID)));
                    strSQL = "UPDATE COR_TRN_CHALLAN SET " +
                        "            CTRL_TOT = CTRL_TOT + " + dblSumValues + " " +
                        "     WHERE  TRN_CHALLAN_ID   = " + lngChallanID;

                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        txtDeducteeName.Select();
                        return;
                    }

                    // UPDATE CHALLAN TOTAL
                    dblSumValues = cmnService.J_ReturnDoubleValue(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT TAX_DEPOSITED_AMOUNT FROM COR_TRN_DEDUCTEE_DETAILS WHERE TRN_DEDUCTEE_DETAIL_ID =  " + lngDeducteeID)));
                    strSQL = "UPDATE COR_TRN_CHALLAN SET " +
                        "            CTRL_TOT_TAX = CTRL_TOT_TAX + " + dblSumValues + " " +
                        "     WHERE  TRN_CHALLAN_ID = " + lngChallanID;

                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        txtDeducteeName.Select();
                        return;
                    }
                    txtViewDeducteeTotalTaxDeposited.Text = "0.00";
                    txtViewDeducteeTotalTaxDeposited.Text = string.Format("{0:0.00}", Convert.ToDouble(dmlService.J_ExecSqlReturnScalar("SELECT SUM(CTRL_TOT_TAX) AS CTRL_TOT_TAX FROM COR_TRN_CHALLAN WHERE TRN_CHALLAN_ID = " + lngChallanID)));
                    //
                    strSQL = "SELECT TRN_DEDUCTEE_DETAIL_ID " +
                        "     FROM   COR_TRN_DEDUCTEE_DETAILS " +
                        "     WHERE  TRN_CHALLAN_ID         =  " + lngChallanID + " " +
                        "     AND    MODE                   <> '' " +
                        "     AND    TRN_DEDUCTEE_DETAIL_ID <> " + lngDeducteeID + " " +
                        "     AND    IMPORT_FLAG            = 1";
                    if (cmnService.J_ReturnInt64Value(dmlService.J_ExecSqlReturnScalar(strSQL)) == 0)
                    {
                        strSQL = "UPDATE COR_TRN_CHALLAN SET " +
                            "            MODE                       = '" + T_CorrectionMode.C2 + "' " +
                            "     WHERE  TRN_CHALLAN_ID             = " + lngChallanID + " " +
                            "     AND    CHALLAN_UPDATION_INDICATOR = 1";
                        if (dmlService.J_ExecSql(strSQL) == false)
                        {
                            return;
                        }
                        //
                        strSQL = "UPDATE COR_TRN_CHALLAN SET " +
                             "           MODE                       = '' " +
                             "    WHERE  TRN_CHALLAN_ID             = " + lngChallanID + " " +
                             "    AND    CHALLAN_UPDATION_INDICATOR = 0 " +
                             "    AND    MODE                       <> '" + T_CorrectionMode.C9 + "'";
                        if (dmlService.J_ExecSql(strSQL) == false)
                        {
                            return;
                        }
                    }
                    //--

                    lngTempDeducteeId = lngDeducteeID;

                    LoadDeducteeGrid(lngChallanID);
                    //--
                    dmlService.J_setGridPosition(ref dgvDeductee, dsetGridClone, lngTempDeducteeId);
                    //--               
                    lblMode.Text = J_Mode.Add;
                    cmnService.J_UserMessage("Data Restored");

                    dgvDeductee_Click(sender, e);
                }
            }
        }

        #endregion

        #region btnChallanDeducteeEntry_Click
        private void btnChallanDeducteeEntry_Click(object sender, EventArgs e)
        {
            grpSearch.Visible = false;
            grpSearchDeductee.Visible = false;
            //
            #region BATCH > BASIC
            if (lblSearchMode.Text == Tabbed_Mode.Batch)
            {
                blnOpenTabPage = true;
                tbcCompany.SelectTab(tbpBasicInformation);


                grpSearchBatch.Visible = false;

                //Added by Shrey Kejriwal on 03/11/2011

                // Blocked for this version
                btnExcelActivate.Visible = true; //Modified on 26/10/2012
                btnExcelActivate.Text = "Advanced Party Search";

                //btnExcelActivate.Visible = false;

                //
                //dgcViewBatch_DoubleClick(sender, e);
                //--------------------------------------------------
                ClearControls();
                //
                //A particular ID wise retriving the data from database
                if (ShowBatchRecord(lngBatchId) == false)
                {
                    if (dsetGridClone == null) return;
                    dmlService.J_setGridPosition(ref dgcViewBatch, dsetGridClone, lngBatchId);
                }
                //
                ShowCorrectionSummary(lngBatchId);
                //
                ControlSummaryBasicInfo(lngBatchId);
                //
                btnChallanDeducteeEntry.Text = "Proceed to Corrections";
                //
                BtnDelete.Enabled = false;
                BtnDelete.BackColor = Color.LightGray;
                //
                BtnCancel.Visible = true;
                //
                lblMode.Text = J_Mode.View;
                lblMode.ForeColor = Color.Yellow;
                lblSearchMode.Text = Tabbed_Mode.Basic;
                //
                BtnCancel.Visible = true;
                BtnCancel.Enabled = true;
                BtnCancel.BackColor = Color.Lavender;
                BtnCancel.Text = "Generate Returns";
                //
                BtnSearch.Enabled = false;
                BtnSearch.BackColor = Color.LightGray;
                //--
                BtnRefresh.Enabled = false;
                BtnRefresh.BackColor = Color.LightGray;
                //
                grpGenerateReturns.Visible = false;

                #region CHECKING IF FAULTY RETURN WAS SUBMITTED

                if (intInvalidReturnValue == 1)
                {
                    // ******************************************************************
                    // ***** CHECK FOR FAULTY RETURN SUBMISSION
                    // ***** WHERE PAN WAS SUBMITTED FOR NAME
                    // ******************************************************************

                    strSQL = "SELECT COUNT(*) " +
                             "FROM COR_HDR_DEDUCTEE_DETAILS " +
                             "WHERE DEDUCTEE_NAME = DEDUCTEE_PAN " +
                             "AND   NON_DEDUCTION_FLAG <> 'C' " +
                             "AND   BATCH_HEADER_ID = " + lngBatchId;

                    int intCount = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL));

                    //strSQL = "SELECT COUNT(*) " +
                    //         "FROM COR_HDR_DEDUCTEE_DETAILS " +
                    //         "WHERE BATCH_HEADER_ID = " + lngBatchId;

                    //int intTotalCount = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL));


                    if (intCount > 0)
                    {
                        // FAULTY RETURN WAS SUBMITTED

                        if (cmnService.J_UserMessage("There was some inconsistency in the Deductee Names in the original return .\n" +
                                                      "Do you want the software to rectify the identified problems?", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button1) == DialogResult.No)
                            return;

                        //NOW CHECKING IF THE ORIGINAL RETURN EXISTS FOR THIS RETURN

                        this.Cursor = Cursors.WaitCursor;

                        strSQL = "SELECT  COUNT(*) " +
                                 "FROM TRN_BASIC_INFO, " +
                                 "     MST_COMPANY " +
                                 "WHERE TRN_BASIC_INFO.COMPANY_ID = MST_COMPANY.COMPANY_ID " +
                                 "AND TRN_BASIC_INFO.ASST_ID = " + txtFAYearID.Text + " " +
                                 "AND TRN_BASIC_INFO.FORM_NO = '" + txtFormNo.Text + "' " +
                                 "AND TRN_BASIC_INFO.QTR     = '" + txtQtr.Text + "' " +
                                 "AND MST_COMPANY.TAN_NO      = '" + txtTAN.Text + "'";

                        intCount = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL));

                        if (intCount > 0)
                        {
                            //ORIGINAL RETURN FOR THIS FILE EXISTS

                            //NOW UPDATING ALL THE DEDUCTEE'S NAMES 
                            //AS PER NAMES USED IN THE ORIGINAL RETURN

                            strSQL = "UPDATE COR_TRN_DEDUCTEE_DETAILS " +
                                     "INNER JOIN  " +
                                     "(SELECT CORRECTION_RETURN.TRN_DEDUCTEE_DETAIL_ID AS TRN_DEDUCTEE_DETAIL_ID, " +
                                     "        ORIGINAL_RETURN.DEDUCTEE_NAME            AS DEDUCTEE_NAME " +
                                     " FROM (SELECT  TRN_CHALLAN.SL_NO                         AS CHALLAN_SL_NO, " +
                                     "               TRN_DEDUCTEE_DETAILS.SL_NO                AS DEDUCTEE_SL_NO, " +
                                     "               MST_DEDUCTEE.DEDUCTEE_NAME                AS DEDUCTEE_NAME, " +
                                     "               MST_DEDUCTEE.DEDUCTEE_PAN                 AS DEDUCTEE_PAN, " +
                                     "               TRN_DEDUCTEE_DETAILS.PAYMENT_DATE         AS PAYMENT_DATE, " +
                                     "               TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT       AS PAYMENT_AMOUNT, " +
                                     "               TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT AS TAX_DEPOSITED_AMOUNT " +
                                     "       FROM   TRN_BASIC_INFO, " +
                                     "              MST_COMPANY, " +
                                     "              TRN_CHALLAN, " +
                                     "              TRN_DEDUCTEE_DETAILS, " +
                                     "              MST_DEDUCTEE " +
                                     "       WHERE TRN_BASIC_INFO.COMPANY_ID     = MST_COMPANY.COMPANY_ID " +
                                     "       AND   TRN_BASIC_INFO.BASIC_INFO_ID  = TRN_CHALLAN.BASIC_INFO_ID " +
                                     "       AND   TRN_CHALLAN.CHALLAN_ID        = TRN_DEDUCTEE_DETAILS.CHALLAN_ID " +
                                     "       AND   TRN_DEDUCTEE_DETAILS.PARTY_ID = MST_DEDUCTEE.DEDUCTEE_ID " +
                                     "       AND   TRN_BASIC_INFO.ASST_ID        =  " + txtFAYearID.Text + " " +
                                     "       AND   TRN_BASIC_INFO.FORM_NO        = '" + txtFormNo.Text + "' " +
                                     "       AND   TRN_BASIC_INFO.QTR            = '" + txtQtr.Text + "' " +
                                     "       AND   MST_COMPANY.TAN_NO            = '" + txtTAN.Text + "' ) AS ORIGINAL_RETURN, " +
                                     "      (SELECT    COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID AS TRN_DEDUCTEE_DETAIL_ID, " +
                                     "                 COR_TRN_CHALLAN.SL_NO                           AS CHALLAN_SL_NO, " +
                                     "                 COR_TRN_DEDUCTEE_DETAILS.SL_NO                  AS DEDUCTEE_SL_NO, " +
                                     "                 COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME          AS DEDUCTEE_NAME, " +
                                     "                 COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN           AS DEDUCTEE_PAN, " +
                                     "                 COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE           AS PAYMENT_DATE, " +
                                     "                 COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT         AS PAYMENT_AMOUNT, " +
                                     "                 COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT   AS TAX_DEPOSITED_AMOUNT " +
                                     "       FROM COR_TRN_CHALLAN, " +
                                     "            COR_TRN_DEDUCTEE_DETAILS, " +
                                     "            COR_HDR_DEDUCTEE_DETAILS " +
                                     "       WHERE COR_TRN_CHALLAN.TRN_CHALLAN_ID                  = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID " +
                                     "       AND   COR_TRN_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID = COR_HDR_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID " +
                                     "       AND   COR_TRN_CHALLAN.BATCH_HEADER_ID                 = " + lngBatchId + " " +
                                     "       AND   COR_HDR_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG     <> 'C'" +
                                     "       AND   COR_TRN_DEDUCTEE_DETAILS.IMPORT_FLAG            = 1 ) AS CORRECTION_RETURN " +
                                     " WHERE ORIGINAL_RETURN.CHALLAN_SL_NO                = CORRECTION_RETURN.CHALLAN_SL_NO " +
                                     " AND   ORIGINAL_RETURN.DEDUCTEE_SL_NO               = CORRECTION_RETURN.DEDUCTEE_SL_NO) AS UPDATE_TABLE " +
                                     "   ON COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID = UPDATE_TABLE.TRN_DEDUCTEE_DETAIL_ID " +
                                     "SET COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME         = UPDATE_TABLE.DEDUCTEE_NAME, " +
                                     "    COR_TRN_DEDUCTEE_DETAILS.MODE = '" + T_CorrectionMode.Modify + "' ";

                            dmlService.J_ExecSql(strSQL);

                            //UPDATING CHALLAN MODE
                            strSQL = "UPDATE COR_TRN_CHALLAN " +
                                     "INNER JOIN (SELECT TRN_CHALLAN_ID " +
                                     "            FROM COR_TRN_DEDUCTEE_DETAILS " +
                                     "            WHERE MODE = 'U') AS DEDUCTEE_DATA " +
                                     "ON COR_TRN_CHALLAN.TRN_CHALLAN_ID = DEDUCTEE_DATA.TRN_CHALLAN_ID " +
                                     "SET MODE = '" + T_CorrectionMode.C3 + "' " +
                                     "WHERE COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId;

                            dmlService.J_ExecSql(strSQL);

                        }
                        else
                        {
                            //IF THE RETURN IS NOT FOUND IN THE REGULAR RETURNS PART

                            //THEN CHECKING IF THE PANS EXIST IN THE DEDUCTEE MASTER AND UPDATING IT
                            strSQL = "UPDATE COR_TRN_DEDUCTEE_DETAILS " +
                                     "INNER JOIN MST_DEDUCTEE " +
                                     "       ON  COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = MST_DEDUCTEE.DEDUCTEE_PAN " +
                                     "SET    COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME = MST_DEDUCTEE.DEDUCTEE_NAME " +
                                     "WHERE  COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN <> 'PANNOTAVBL'" +
                                     "AND    COR_TRN_DEDUCTEE_DETAILS.BATCH_HEADER_ID = " + lngBatchId;

                            dmlService.J_ExecSql(strSQL);

                            //UPDATING CHALLAN MODE
                            strSQL = "UPDATE COR_TRN_CHALLAN " +
                                     "INNER JOIN (SELECT TRN_CHALLAN_ID " +
                                     "            FROM COR_TRN_DEDUCTEE_DETAILS " +
                                     "            WHERE MODE = 'U') AS DEDUCTEE_DATA " +
                                     "ON COR_TRN_CHALLAN.TRN_CHALLAN_ID = DEDUCTEE_DATA.TRN_CHALLAN_ID " +
                                     "SET MODE = '" + T_CorrectionMode.C3 + "' " +
                                     "WHERE COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId;

                            dmlService.J_ExecSql(strSQL);

                        }
                    }

                    //FINALLY UPDAING THE INVALID RETURN MODE TO STOP FURTHER CHECKING
                    strSQL = "UPDATE COR_HDR_BATCH SET INVALID_RETURN = 0 WHERE BATCH_HEADER_ID = " + lngBatchId;
                    dmlService.J_ExecSql(strSQL);

                    ShowCorrectionSummary(lngBatchId);
                    //
                    ControlSummaryBasicInfo(lngBatchId);

                    this.Cursor = Cursors.Default;


                }

                #endregion

                //
            }
            #endregion
            //--
            #region BASIC > COMPANY
            else if (lblSearchMode.Text == Tabbed_Mode.Basic)
            {

                lblSearchMode.Text = Tabbed_Mode.Company;
                ClearControls();
                if (ShowCompanyDetails(cmnService.J_ReturnInt32Value(txtCompanyID.Text)) == false)
                {
                    lblSearchMode.Text = Tabbed_Mode.Basic;
                    return;
                }

                //Added by Shrey Kejriwal on 03/11/2011
                btnExcelActivate.Visible = false;

                //
                if (ShowHDRCompanyDetails(cmnService.J_ReturnInt32Value(txtCompanyID.Text)) == false)
                {
                    lblSearchMode.Text = Tabbed_Mode.Basic;
                    return;
                }
                //
                lblMode.Text = J_Mode.Edit;
                //lblMode.ForeColor = Color.Yellow;
                //
                blnOpenTabPage = true;
                tbcCompany.SelectTab(tbpCompanyDetails);
                btnChallanDeducteeEntry.Text = "Challan && Deductee Details";
                //
                BtnSave.Enabled = true;
                BtnSave.BackColor = Color.Lavender;
                //
                BtnCancel.Visible = true;
                BtnCancel.Enabled = true;
                BtnCancel.BackColor = Color.Lavender;
                BtnCancel.Text = "Back to Basic Screen";
                //
                if (txtFormNo.Text.Trim() == T_FormNo.F24Q && txtQtr.Text.Trim() == T_Qtr.Q4)
                    btnSalaryDetail.Visible = true;
                else
                    btnSalaryDetail.Visible = false;
                //
            }
            #endregion
            //--
            #region COMPANY > CHALLAN
            else if (lblSearchMode.Text == Tabbed_Mode.Company)
            {
                //
                if (Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT D_CATEGORY_ID FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + lngBatchId)) == "0")
                {
                    cmnService.J_UserMessage("Select Deductor Type and press <Save> Button");
                    cmbDeductorType.Select();
                    return;
                }
                blnOpenTabPage = true;
                tbcCompany.SelectTab(tbpChallanDetails);

                //Added by Shrey Kejriwal on 03/11/2011
                btnExcelActivate.Text = "Add Deductees using Excel";
                btnExcelActivate.Visible = true;

                //-----------------------------------------------------------
                lblMode.Text = J_Mode.Add;
                lblMode.ForeColor = Color.GreenYellow;
                lblSearchMode.Text = Tabbed_Mode.Challan;
                //--
                BackgroundColorChangeChallan(lblMode.Text);
                //
                LoadForm(txtFormNo.Text, lblSearchMode.Text);
                //
                LoadFormComponents();
                //---------------------------------------------
                btnChallanDeducteeEntry.Text = "Deductee Details";
                //--
                BtnSave.Enabled = true;
                BtnSave.BackColor = Color.Lavender;
                //--
                BtnCancel.Enabled = true;
                BtnCancel.BackColor = Color.Lavender;
                BtnCancel.Text = "Back to Basic Screen";
                //--
                BtnSort.Enabled = true;
                BtnSort.BackColor = Color.Lavender;
                //--
                BtnSearch.Enabled = true;
                BtnSearch.BackColor = Color.Lavender;
                //--
                BtnRefresh.Enabled = true;
                BtnRefresh.BackColor = Color.Lavender;
                //--
                btnSalaryDetail.Visible = false;
                //--
                if (TDSMAN.Classes.TDSMAN.T_ShowAllocatedFileds == false)
                {
                    lblInterestAllocated.Visible = false;
                    txtInterestAllocated.Visible = false;
                    lblOthersAllocated.Visible = false;
                    txtOthersAllocated.Visible = false;
                }
                lblRemarks.Location = new Point(14, 339);
                txtRemarks.Location = new Point(74, 339);
                //--
                btnChallanDeducteeEntry.Visible = true;
                btnChallanDeducteeEntry.Enabled = false;
                btnChallanDeducteeEntry.BackColor = Color.LightGray;
                //---------------------------------------------
                //grpMain.Enabled = false;
                //--
                ClearControls();
                //-----------
                //-- SECTION
                //-----------
                strSQL = " SELECT SECTION_ID," +
                    "             SECTION_NO " +
                    "      FROM   MST_SECTION " +
                    "      WHERE  FORM_NAME = '" + txtFormNo.Text.Trim() + "' " +
                    "      AND    ASST_ID <= " + Convert.ToInt32(txtFAYearID.Text) + " " +
                    "      ORDER BY SECTION_ID";
                if (dmlService.J_PopulateComboBox(strSQL, ref cmbSection) == false) return;
                //-----------
                mskDateOfPayment.Text = System.DateTime.Now.ToString();
                txtBSRCode.Text = "";
                txtChequeNo.Text = "";
                //-----------------------------------------------------------
                //-- Generate Challan Srl No.
                txtChallanSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("COR_TRN_CHALLAN", "SL_NO", "BATCH_HEADER_ID = " + lngBatchId + "") + 1);
                //--
                if (cmbDeductorType.Text.Trim().Length > 0)
                {
                    if (cmbDeductorType.Text.Substring(0, 1) == "A" || cmbDeductorType.Text.Substring(0, 1) == "S")
                    {
                        //txtTransferVoucherNo.Enabled = true;
                        //txtTransferVoucherNo.BackColor = Color.White;
                        //
                        chkBookEntry.Visible = true;
                        lblSrlNo.Location = new Point(59, 10);
                        txtChallanSrlNo.Location = new Point(107, 7);
                    }
                    else
                    {
                        //txtTransferVoucherNo.Enabled = false;
                        //txtTransferVoucherNo.BackColor = Color.LightGray;
                        //
                        chkBookEntry.Visible = false;
                        lblSrlNo.Location = new Point(85, 10);
                        txtChallanSrlNo.Location = new Point(170, 7);
                    }
                }
                //--
                LoadChallanGrid();
                //--
                //Added by Indrajit on 05-03-2013
                if (dgvViewChallan.CurrentCell == null)
                {
                    BtnEdit.Enabled = false;
                    BtnEdit.BackColor = Color.LightGray;

                    BtnDelete.Enabled = false;
                    BtnDelete.BackColor = Color.LightGray;
                }
                //===============================

                cmbSection.Select();

                ControlSummaryVisible(false, false, false, false, false, false, false);
            }
            #endregion
            //--
            #region CHALLAN > DEDUCTEE
            else if (lblSearchMode.Text == Tabbed_Mode.Challan)
            {
                if (cmnService.J_ReturnInt32Value(txtFAYearID.Text) < T_FinancialYearID.F2013_14ID)
                {
                    //--
                    strSQL = "SELECT COUNT(*) " +
                            " FROM   COR_TRN_CHALLAN " +
                            " WHERE  SECTION_ID     = 0 " +
                            " AND    TRN_CHALLAN_ID = " + lngChallanID + " ";
                    if (dmlService.J_ReturnNoOfRows(strSQL, J_QueryType.DirectQuery) > 0)
                    {
                        cmnService.J_UserMessage("Save the Section Code for this Challan to open its underlying deductee details");
                        return;
                    }
                }
                else
                {

                }
