        #region btnBulkPANVerification_Click
        private void btnBulkPANVerification_Click(object sender, EventArgs e)
        {
            if (dmlService.J_IsRecordExist("COR_TRN_DEDUCTEE_DETAILS", " BATCH_HEADER_ID = " + lngBatchId) == true)
            {
                //--
                TDSMAN.Classes.TDSMAN.T_pBatchId = lngBatchId;
                TDSMAN.Classes.TDSMAN.T_pTabFormCaption = txtFormNo.Text;
                TDSMAN.Classes.TDSMAN.T_pQuarter = txtQtr.Text;
                TDSMAN.Classes.TDSMAN.T_FromModule = T_OTHERMODULENAME.MAKE_CORRECTION;
                //--
                if (chkNewDeductees.Checked == true)
                {
                    bool blnNewDeductee = true;
                    //-- check for new deductees / new PANs
                    strSQL = @"SELECT  COUNT(*) 
                               FROM    COR_TRN_DEDUCTEE_DETAILS 
                               WHERE   BATCH_HEADER_ID        = " + lngBatchId + " " +
                              "AND    (PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " " +
                                      "OR MODE                IN ('A','O'))";
                    if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))) == 0)
                    {
                        //cmnService.J_UserMessage("No new deductee(s) or new PAN(s) found !!");
                        //return;
                        blnNewDeductee = false;
                    }
                    //
                    if (txtFormNo.Text == T_FormNo.F24Q && txtQtr.Text == T_Qtr.Q4 && blnNewDeductee == false)
                    {
                        strSQL = @"SELECT COUNT(*) 
                                   FROM   COR_TRN_SALARY_DETAILS 
                                   WHERE  BATCH_HEADER_ID        = " + lngBatchId + " " +
                                  "AND   (PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " " +
                                       "OR MODE                  IN ('A','O'))";
                        if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))) == 0)
                            blnNewDeductee = false;
                        else
                            blnNewDeductee = true;
                    }
                    //--
                    if (blnNewDeductee == false)
                    {
                        cmnService.J_UserMessage("No new PAN(s) found !!");
                        return;
                    }
                    //--
                    TDSMAN.Classes.TDSMAN.T_pVerifyPANNewDeductee = true;
                }
                else
                    TDSMAN.Classes.TDSMAN.T_pVerifyPANNewDeductee = false;
                //--
                this.Cursor = Cursors.WaitCursor;
                //--
                TrnBulkPANVerification TrnBulkPANVerification = new TrnBulkPANVerification();
                TrnBulkPANVerification.ShowDialog();
                //
                this.Cursor = Cursors.Default;
                //--
                this.Refresh();
                //
                TDSMAN.Classes.TDSMAN.T_FromModule = "";
            }
            else
                cmnService.J_UserMessage("No records available");

        }
        #endregion

