        #region dgvViewChallan_CellFormatting
        private void dgvViewChallan_CellFormatting(object sender, DataGridViewCellFormattingEventArgs e)
        {
            if (dgvViewChallan.Columns[e.ColumnIndex].DataPropertyName == "CHALLAN_STATUS")
            {
                if (e.Value.ToString().ToUpper() == "UNMATCHED" || e.Value.ToString().ToUpper() == "OVERBOOKED")
                {
                    //CHALLAN IS UNMATCHED 

                    //NOW CHECKING IF THE CHALLAN HAS BEEN UPDATED
                    if (dgvViewChallan.Rows[e.RowIndex].Cells["MODE"].Value.ToString() != "Upd")
                    {
                        //highlighting the cell
                        e.CellStyle.BackColor = Color.Red;
                        e.CellStyle.ForeColor = Color.White;

                        dgvViewChallan.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "Unmatched Challan";
                    }
                }
            }
            //--
            if (dgvViewChallan.Columns[e.ColumnIndex].DataPropertyName == "MODE")
            {
                if (e.Value.ToString() == "Upd")
                {
                    //FOR UPDATION MODE HIGHLIGHTING THE MODE AND THE VALUES UPDATED

                    e.CellStyle.BackColor = Color.Yellow;
                    dgvViewChallan.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "Record Updated";

                    string strPreviousValue = "";
                    string strNewValue = "";

                    // -- FOR HIGHLIGHTING SECTION

                    strPreviousValue = Convert.ToString(dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.HDR_SECTION_NO].Value);
                    strNewValue = Convert.ToString(dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.SECTION_NO].Value);

                    if (strPreviousValue != strNewValue)
                    {
                        dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.SECTION_NO].Style.BackColor = Color.Yellow;
                        dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.SECTION_NO].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                             "\nNew Value\t: " + strNewValue;
                    }

                    // -- FOR HIGHLIGHTING CHALLAN NO

                    strPreviousValue = Convert.ToString(dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.HDR_CHALLAN_TRF_NO].Value);
                    strNewValue = Convert.ToString(dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.CHALLAN_TRF_NO].Value);

                    if (strPreviousValue != strNewValue)
                    {
                        dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.CHALLAN_TRF_NO].Style.BackColor = Color.Yellow;
                        dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.CHALLAN_TRF_NO].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                                "\nNew Value\t: " + strNewValue;
                    }

                    // -- FOR HIGHLIGHTING DEPOSIT DATE

                    strPreviousValue = string.Format("{0:dd/MM/yyyy}", Convert.ToDateTime(dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.HDR_DEPOSIT_DATE].Value));
                    strNewValue = string.Format("{0:dd/MM/yyyy}", Convert.ToDateTime(dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.DEPOSIT_DATE].Value));

                    if (strPreviousValue != strNewValue)
                    {
                        dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.DEPOSIT_DATE].Style.BackColor = Color.Yellow;
                        dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.DEPOSIT_DATE].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                                "\nNew Value\t: " + strNewValue;
                    }

                    // -- FOR HIGHLIGHTING TOTAL TAX

                    strPreviousValue = string.Format("{0:0.00}", Convert.ToDouble(dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.HDR_TOT_TAX].Value));
                    strNewValue = string.Format("{0:0.00}", Convert.ToDouble(dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.TOT_TAX].Value));

                    if (strPreviousValue != strNewValue)
                    {
                        dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.TOT_TAX].Style.BackColor = Color.Yellow;
                        dgvViewChallan.Rows[e.RowIndex].Cells[T_ChallanGridValues.TOT_TAX].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                                "\nNew Value\t: " + strNewValue;
                    }

                }
                else if (e.Value.ToString() == "Add")
                {
                    e.CellStyle.BackColor = Color.LightGreen;
                    dgvViewChallan.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "New Record Added";
                }
            }
        }
        #endregion


        #region chkBookEntry_CheckedChanged
        private void chkBookEntry_CheckedChanged(object sender, EventArgs e)
        {
            if (chkBookEntry.Checked == true)
            {
                //BSR Code/24G Rcpt # [410]
                lblBSRCode.Text = "24G Receipt No. [410]";
                lblTrVchNo.Text = "Tr Vch(DDO Sl.) [412]";

                txtChallanNo.Visible = false;
                txtChallanNo.Text = "";

                txtTransferVoucherNo.Visible = true;
                if (lblMode.Text == J_Mode.Edit)
                    txtTransferVoucherNo.BackColor = Color.Honeydew;
                else
                    txtTransferVoucherNo.BackColor = Color.White;

                txtChequeNo.Enabled = false;
                txtChequeNo.BackColor = Color.LightGray;
                txtChequeNo.Text = "";

                //ADDED BY DHRUB ON 04/01/2014 TO HIDE BOOK ENTRY WISE MINOR HEAD 
                if (Convert.ToInt32(txtFAYearID.Text.Trim()) >= T_FinancialYearID.F2013_14ID)
                {
                    lblMinor.Visible = false;
                    cmbMinorHead.Visible = false;
                    cmbMinorHead.SelectedIndex = 0;
                }

            }
            else if (chkBookEntry.Checked == false)
            {
                lblBSRCode.Text = "BSR Code [410]";
                lblTrVchNo.Text = "Challan No. [412]";

                txtTransferVoucherNo.Visible = false;
                txtTransferVoucherNo.Text = "";

                txtChallanNo.Visible = true;
                if (lblMode.Text == J_Mode.Edit)
                    txtChallanNo.BackColor = Color.Honeydew;
                else
                    txtChallanNo.BackColor = Color.White;

                txtChequeNo.Enabled = true;
                if (lblMode.Text == J_Mode.Edit)
                    txtChequeNo.BackColor = Color.Honeydew;
                else
                    txtChequeNo.BackColor = Color.White;

                //ADDED BY DHRUB ON 04/01/2014 TO HIDE BOOK ENTRY WISE MINOR HEAD 
                if (Convert.ToInt32(txtFAYearID.Text.Trim()) >= T_FinancialYearID.F2013_14ID)
                {
                    lblMinor.Visible = true;
                    cmbMinorHead.Visible = true;
                }
            }
        }
