        #region DeducteeDetails

        #region dgvDeductee_Click
        private void dgvDeductee_Click(object sender, EventArgs e)
        {
            if (dgvDeductee.CurrentRow == null)
            {
                BtnDelete.Text = T_DeleteRestoreText.Delete;
                BtnDelete.Enabled = false;
                BtnDelete.BackColor = Color.LightGray;

                BtnEdit.Enabled = false;
                BtnEdit.BackColor = Color.LightGray;

                return;
            }

            if (dgvDeductee.CurrentRow.Index < 0)
            {
                txtDeducteeName.Focus();
                return;
            }

            if (lblMode.Text != J_Mode.Edit)
                lngDeducteeID = Convert.ToInt64(dgvDeductee.Rows[dgvDeductee.CurrentRow.Index].Cells[0].Value);

            if (lngDeducteeID > 0)
            {

                if (lblMode.Text == J_Mode.Edit)
                {
                    BtnEdit.Enabled = true;
                    BtnEdit.BackColor = Color.Lavender;

                    BtnDelete.Enabled = false;
                    BtnDelete.BackColor = Color.LightGray;
                    return;
                }

                string strDeducteeMode = "";

                strSQL = "SELECT MODE FROM COR_TRN_DEDUCTEE_DETAILS " +
                         "WHERE  TRN_DEDUCTEE_DETAIL_ID = " + lngDeducteeID;


                strDeducteeMode = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));

                if (strDeducteeMode == T_CorrectionMode.Delete)
                {
                    //BtnDelete.Enabled = false;
                    //BtnDelete.BackColor = Color.LightGray;

                    //BtnRefresh.Enabled = true;
                    //BtnRefresh.BackColor = Color.Lavender;

                    BtnDelete.Enabled = true;
                    BtnDelete.Text = T_DeleteRestoreText.Restore;
                    BtnDelete.BackColor = Color.Lavender;

                    //DELETED DATA CANNOT BE UPDATED
                    BtnEdit.Enabled = false;
                    BtnEdit.BackColor = Color.LightGray;
                }
                else
                {
                    //BtnDelete.Enabled = true;
                    //BtnDelete.BackColor = Color.Lavender;

                    //BtnRefresh.Enabled = false;
                    //BtnRefresh.BackColor = Color.LightGray;

                    BtnDelete.Enabled = true;
                    BtnDelete.Text = T_DeleteRestoreText.Delete;
                    BtnDelete.BackColor = Color.Lavender;

                    BtnEdit.Enabled = true;
                    BtnEdit.BackColor = Color.Lavender;

                }
            }
        }
        #endregion

        #region dgvDeductee_DoubleClick
        private void dgvDeductee_DoubleClick(object sender, EventArgs e)
        {
            try
            {

                if (dgvDeductee.CurrentRow == null)
                    return;


                if (dgvDeductee.CurrentRow.Index >= 0)
                {
                    //--------------------------------------------------
                    ClearControls();
                    //--------------------------------------------------

                    //ADDED BY SHREY KEJRIWAL ON 28/03/2012

                    //--------------------------------------------------
                    //CHECKING IF THE RECORD IS ALREADY DELETED
                    //--------------------------------------------------
                    string strDeducteeMode = "";

                    strSQL = "SELECT MODE FROM COR_TRN_DEDUCTEE_DETAILS " +
                             "WHERE  TRN_DEDUCTEE_DETAIL_ID = " + lngDeducteeID;

                    strDeducteeMode = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));

                    if (strDeducteeMode == T_CorrectionMode.Delete)
                    {
                        cmnService.J_UserMessage("Deleted record cannot be modified.");
                        return;
                    }
                    //--------------------------------------------------
                    //A particular ID wise retriving the data from database
                    if (ShowDeducteeRecord() == false)
                    {
                        if (dsetGridClone == null) return;

                        dmlService.J_setGridPosition(ref dgvDeductee, dsetGridClone, lngDeducteeID);
                        //TdsMan.T_setGridPosition(ref dgvDeductee, dsetGridClone, lngDeducteeID);
                    }
                    if (ShowHDRDeducteeRecord() == false)
                    {
                        if (dsetGridClone == null) return;

                        dmlService.J_setGridPosition(ref dgvDeductee, dsetGridClone, lngDeducteeID);
                    }
                    //--
                    txtViewDeducteeTotalTaxDeposited_TextChanged(sender, e);
                    //--------------------------------------------------
                    lblMode.Text = J_Mode.Edit;
                    cmnService.J_StatusButton(this, lblMode.Text);

                    BackgroundColorChangeDeductee(lblMode.Text);
                    //--
                    BtnSort.Enabled = true;
                    BtnSort.BackColor = Color.Lavender;

                    //---------------------------------------------------
                    //ENABLE DEDUCTED DATE FOR EDIT MODE

                    lblDeductedDate.Visible = true;
                    lblDeductedDateFormat.Visible = true;
                    mskDeductedDate.Visible = true;

                    //--
                    //BtnSearch.Enabled = true;
                    //BtnSearch.BackColor = Color.Lavender;
                    ////--
                    //BtnRefresh.Enabled = true;
                    //BtnRefresh.BackColor = Color.Lavender;
                    //--
                    BtnExit.Enabled = true;
                    BtnExit.BackColor = Color.Lavender;
                    //lblSearchMode.Text = J_Mode.General;
                    //--------------------------------------------------
                    strCheckFields = "";
                    //--------------------------------------------------
                }
                else
                {
                    cmnService.J_UserMessage(J_Msg.DataNotFound);
                    if (dsetGridClone == null) return;
                    dmlService.J_setGridPosition(ref dgvDeductee, dsetGridClone, lngDeducteeID);
                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region dgvDeductee_KeyDown
        private void dgvDeductee_KeyDown(object sender, KeyEventArgs e)
        {
            if (dgvDeductee.CurrentRow == null)
                return;

            if (dgvDeductee.CurrentRow.Index < 0) return;
            lngDeducteeID = Convert.ToInt64(dgvDeductee.Rows[dgvDeductee.CurrentRow.Index].Cells[0].Value);

            if (e.KeyCode == Keys.Enter) dgvDeductee_DoubleClick(sender, e);

            if (e.KeyCode == Keys.Delete) BtnDelete_Click(sender, e);

        }
        #endregion

        #region dgvDeductee_CurrentCellChanged
        private void dgvDeductee_CurrentCellChanged(object sender, EventArgs e)
        {
            dgvDeductee_Click(sender, e);
        }
