        #region dgvDeductee_CellFormatting
        private void dgvDeductee_CellFormatting(object sender, DataGridViewCellFormattingEventArgs e)
        {
            #region CellFormatting(DEDUCTEE_PAN)

            if (dgvDeductee.Columns[e.ColumnIndex].DataPropertyName == "DEDUCTEE_PAN")
            {
                //CHECKING THE INVALID PAN FLAG FOR THIS PAN
                if (dgvDeductee.Rows[e.RowIndex].Cells["INVALID_PAN"].Value.ToString() == "1")
                {
                    //PAN IS INVALID

                    //NOW CHECKING IF THE PAN HAS BEEN MODIFIED OR THE RECORD HAS BEEN DELETED

                    if (dgvDeductee.Rows[e.RowIndex].Cells["PAN_UPDATION_INDICATOR"].Value.ToString() != "1" &&
                        dgvDeductee.Rows[e.RowIndex].Cells["MODE"].Value.ToString() != "Del")
                    {
                        //PAN HAS NOT BEEN MODIFIED AND HAS NOT BEEN DELETED

                        //NOW HIGHLIGHLING THE CELL 
                        //highlighting the cell
                        //e.CellStyle.BackColor = Color.FromArgb(231, 206, 248); //PURPLE COLOR
                        e.CellStyle.BackColor = Color.Red;
                        e.CellStyle.ForeColor = Color.White;

                        if (e.Value.ToString() == "PANNOTAVBL")
                            dgvDeductee.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "Enter the Valid PAN if now available";
                        else if (e.Value.ToString() == "PANINVALID")
                            dgvDeductee.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "Enter the Valid PAN if now available";
                        else if (e.Value.ToString() == "PANAPPLIED")
                            dgvDeductee.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "Enter the Valid PAN if now available";
                        else
                            dgvDeductee.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "This PAN (" + e.Value.ToString() + ") has been marked \nInvalid by the Income Tax Department";
                    }
                }
            }
            #endregion

            #region CellFormatting(MODE)
            if (dgvDeductee.Columns[e.ColumnIndex].DataPropertyName == "MODE")
            {
                if (e.Value.ToString() == "Upd")
                {
                    #region Highlighting cell for Update record

                    // ----------------------------------------------
                    // -- HIGHLIGHTING THE UPDATE MODE CELL
                    // ----------------------------------------------

                    e.CellStyle.BackColor = Color.Yellow;
                    dgvDeductee.Rows[e.RowIndex].Cells[e.ColumnIndex].ToolTipText = "This record is updated";

                    string strPreviousValue = "";
                    string strNewValue = "";

                    // -- FOR HIGHLIGHTING DEDUCTEE PAN
                    //CHECKING IF THE PAN IS UPDATED

                    strPreviousValue = Convert.ToString(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.HDR_DEDUCTEE_PAN].Value);
                    strNewValue = Convert.ToString(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.DEDUCTEE_PAN].Value);

                    if (strPreviousValue != strNewValue)
                    {
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.DEDUCTEE_PAN].Style.BackColor = Color.Yellow;
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.DEDUCTEE_PAN].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                            "\nNew Value\t: " + strNewValue;
                    }
                    //-- NAME
                    strPreviousValue = Convert.ToString(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.HDR_DEDUCTEE_NAME].Value);
                    strNewValue = Convert.ToString(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.DEDUCTEE_NAME].Value);

                    if (strPreviousValue != strNewValue)
                    {
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.DEDUCTEE_NAME].Style.BackColor = Color.Yellow;
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.DEDUCTEE_NAME].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                            "\nNew Value\t: " + strNewValue;
                    }


                    if (cmnService.J_ReturnInt32Value(txtFAYearID.Text) >= T_FinancialYearID.F2013_14ID)
                    {
                        // -- FOR HIGHLIGHTING SECTION
                        strPreviousValue = Convert.ToString(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.HDR_SECTION_NO].Value);
                        strNewValue = Convert.ToString(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.SECTION_NO].Value);

                        if (strPreviousValue != strNewValue)
                        {
                            dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.SECTION_NO].Style.BackColor = Color.Yellow;
                            dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.SECTION_NO].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                                "\nNew Value\t: " + strNewValue;
                        }
                    }

                    // -- FOR HIGHLIGHTING PAYMENT_AMOUNT
                    strPreviousValue = string.Format("{0:0.00}", Convert.ToDouble(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.HDR_PAYMENT_AMOUNT].Value));
                    strNewValue = string.Format("{0:0.00}", Convert.ToDouble(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.PAYMENT_AMOUNT].Value));

                    if (strPreviousValue != strNewValue)
                    {
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.PAYMENT_AMOUNT].Style.BackColor = Color.Yellow;
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.PAYMENT_AMOUNT].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                            "\nNew Value\t: " + strNewValue;
                    }

                    // -- FOR HIGHLIGHTING PAYMENT_DATE
                    strPreviousValue = string.Format("{0:dd/MM/yyyy}", Convert.ToDateTime(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.HDR_PAYMENT_DATE].Value));
                    strNewValue = string.Format("{0:dd/MM/yyyy}", Convert.ToDateTime(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.PAYMENT_DATE].Value));

                    if (strPreviousValue != strNewValue)
                    {
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.PAYMENT_DATE].Style.BackColor = Color.Yellow;
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.PAYMENT_DATE].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                            "\nNew Value\t: " + strNewValue;
                    }

                    // -- FOR HIGHLIGHTING TOTAL DEDUCTED
                    strPreviousValue = string.Format("{0:0.00}", Convert.ToDouble(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.HDR_TOTAL_AMOUNT].Value));
                    strNewValue = string.Format("{0:0.00}", Convert.ToDouble(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.TOTAL_AMOUNT].Value));

                    if (strPreviousValue != strNewValue)
                    {
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.TOTAL_AMOUNT].Style.BackColor = Color.Yellow;
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.TOTAL_AMOUNT].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                            "\nNew Value\t: " + strNewValue;
                    }

                    // -- FOR HIGHLIGHTING TOTAL DEPOSITED
                    strPreviousValue = string.Format("{0:0.00}", Convert.ToDouble(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.HDR_TAX_DEPOSITED_AMOUNT].Value));
                    strNewValue = string.Format("{0:0.00}", Convert.ToDouble(dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.TAX_DEPOSITED_AMOUNT].Value));

                    if (strPreviousValue != strNewValue)
                    {
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.TAX_DEPOSITED_AMOUNT].Style.BackColor = Color.Yellow;
                        dgvDeductee.Rows[e.RowIndex].Cells[T_DeducteeGridValues.TAX_DEPOSITED_AMOUNT].ToolTipText = "Old Value\t: " + strPreviousValue +
                                                                                                            "\nNew Value\t: " + strNewValue;
                    }

                    #endregion
                }

                else if (e.Value.ToString() == "Add" || e.Value.ToString() == "New")
                {
                    e.CellStyle.BackColor = Color.LightGreen;
                    dgvDeductee.Rows[e.RowIndex].Cells["MODE"].ToolTipText = "New Record Added";
                }

                else if (e.Value.ToString() == "Del")
                {
                    e.CellStyle.BackColor = Color.FromArgb(231, 206, 248);
                    dgvDeductee.Rows[e.RowIndex].Cells["MODE"].ToolTipText = "This record is marked for deletion.\n";
                }
            }
            #endregion

        }
        #endregion

