        #region txtDeducteeName_TextChanged
        private void txtDeducteeName_TextChanged(object sender, EventArgs e)
        {
            IDataReader drdShowDeducteeHelp = null;
            //--
            try
            {
                if (txtDeducteeName.Text.Trim() == "")
                {
                    lstDeducteeHelp.Visible = false;
                    return;
                }
                //
                if (blnShowHelp == false)
                    return;
                //-----------------------
                lstDeducteeHelp.BackColor = Color.MistyRose; 
                //--
                if (txtFormNo.Text == T_FormNo.F24Q)
                {
                    strSQLShowHelpDeductee = @"SELECT  TOP 10 DEDUCTEE_NAME,
                                                              DEDUCTEE_PAN, 
                                                              ''   AS DEDUCTEE_CODE
                                                FROM (
                                                SELECT DEDUCTEE_NAME  AS DEDUCTEE_NAME, 
                                                       DEDUCTEE_PAN   AS DEDUCTEE_PAN, 
                                                       ''             AS DEDUCTEE_CODE
                                                FROM   COR_TRN_DEDUCTEE_DETAILS 
                                                WHERE  DEDUCTEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + "%' " +
                                               @"AND BATCH_HEADER_ID = " + lngBatchId + " " +
                                               @"GROUP  BY DEDUCTEE_NAME, 
                                                          DEDUCTEE_PAN
                                                UNION
                                                SELECT  EMPLOYEE_NAME  AS DEDUCTEE_NAME, 
                                                        EMPLOYEE_PAN   AS DEDUCTEE_PAN, 
                                                        ''             AS DEDUCTEE_CODE
                                                FROM    COR_TRN_SALARY_DETAILS 
                                                WHERE   EMPLOYEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + "%' " +
                                               @"AND BATCH_HEADER_ID = " + lngBatchId + " " +
                                               @"GROUP  BY EMPLOYEE_PAN, 
                                                          EMPLOYEE_NAME)
                                                ORDER  BY DEDUCTEE_NAME";
                }
                else
                {
                    if (TDSMAN.Classes.TDSMAN.T_ShowRegularDeducteeCorrection == true)
                    {
                        lstDeducteeHelp.BackColor = Color.LightSkyBlue;
                        //
                        strSQLShowHelpDeductee = @"SELECT DEDUCTEE_NAME,
                                                        DEDUCTEE_PAN,
                                                        DEDUCTEE_CODE 
                                                   FROM(
                                                   SELECT DEDUCTEE_NAME,
                                                          DEDUCTEE_PAN,
                                                          DEDUCTEE_CODE 
                                                   FROM   MST_DEDUCTEE
                                                   WHERE  DEDUCTEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + "%' " +
                                                 @"UNION
                                                   SELECT DEDUCTEE_NAME,
                                                        DEDUCTEE_PAN,
                                                        DEDUCTEE_CODE 
                                                   FROM   COR_TRN_DEDUCTEE_DETAILS 
                                                   WHERE  DEDUCTEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + "%' " +
                                                 @"AND    BATCH_HEADER_ID    = " + lngBatchId + " " +
                                                 @"GROUP BY DEDUCTEE_NAME, DEDUCTEE_PAN, DEDUCTEE_CODE)
                                                   ORDER BY DEDUCTEE_NAME";
                    }
                    else
                    {
                        strSQLShowHelpDeductee = "SELECT DEDUCTEE_NAME," +
                            "                            DEDUCTEE_PAN," +
                            "                            DEDUCTEE_CODE " +
                            "                     FROM   COR_TRN_DEDUCTEE_DETAILS " +
                            "                     WHERE  DEDUCTEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtDeducteeName.Text) + "%' " +
                            "                     AND    BATCH_HEADER_ID    = " + lngBatchId + " " +
                            "                     GROUP BY DEDUCTEE_NAME, DEDUCTEE_PAN, DEDUCTEE_CODE " +
                            "                     ORDER BY DEDUCTEE_NAME";
                    }   
                }
                
                drdShowDeducteeHelp = dmlService.J_ExecSqlReturnReader(strSQLShowHelpDeductee);
                //--
                if (drdShowDeducteeHelp == null)
                {
                    lstDeducteeHelp.Visible = false;
                    return;
                }
                else
                {
                    lstDeducteeHelp.Items.Clear();
                    lstDeducteeHelp.Height = 19;
                    lstDeducteeHelp.Visible = true;
                    while (drdShowDeducteeHelp.Read())
                    {
                        lstDeducteeHelp.Items.Add(new ListBoxItem(drdShowDeducteeHelp["DEDUCTEE_NAME"].ToString().PadRight(58) + drdShowDeducteeHelp["DEDUCTEE_PAN"].ToString().PadRight(13) + drdShowDeducteeHelp["DEDUCTEE_CODE"]));
                        //--
                        if (lstDeducteeHelp.Height <= 300)
                            lstDeducteeHelp.Height = lstDeducteeHelp.Height + 19;
                    }
                    //--
                    if (lstDeducteeHelp.Items.Count <= 0)
                        lstDeducteeHelp.Visible = false;
                }
                //-----------------------------------------------------------
                drdShowDeducteeHelp.Close();
                drdShowDeducteeHelp.Dispose();
                //-----------------------------------------------------------
            }
            catch (Exception err_handler)
            {
                drdShowDeducteeHelp.Close();
                drdShowDeducteeHelp.Dispose();
                cmnService.J_UserMessage(err_handler.Message);
            }
            //-----------------------
        }
        #endregion

