        #region btnGenerateTextFile_Click
        private void btnGenerateTextFile_Click(object sender, EventArgs e)
        {
            this.Cursor = Cursors.WaitCursor;
            // Generate Text File
            txtTextFilePath.Text = CreateOutputFile_Folder(txtTAN.Text, txtFormNo.Text.Trim(), txtFAYear.Text, txtQtr.Text, txtCompany.Text, lngBatchId);

            //ADDED BY SHREY KEJRIWAL ON 11/04/2012
            if (File.Exists(txtTextFilePath.Text))
                File.Delete(txtTextFilePath.Text);

            //
            if (txtTextFilePath.Text == "")
            {
                this.Cursor = Cursors.Default;
                cmnService.J_UserMessage("Creation of Text File failed");
                btnGenerateTextFile.Select();
                return;
            }
            if (GenerateTextFile(txtTextFilePath.Text) == false)
            {
                this.Cursor = Cursors.Default;
                cmnService.J_UserMessage("Generation of Text File failed", MessageBoxIcon.Exclamation);
                btnGenerateTextFile.Select();
                return;
            }
            //
            txtInputFileName.Text = txtTextFilePath.Text;
            //
            if (TdsMan.T_InsertFileGenerationData(lngBatchId, txtTextFilePath.Text, Convert.ToString(DateTime.Now),
                                                 Convert.ToInt32(txtTotalChallanRecords.Text), Convert.ToInt32(txtTotalDeductions.Text),
                                                 Convert.ToDouble(txtTotalChallanAmount.Text),
                                                 Convert.ToDouble(txtTDSDeducted.Text), 1) == false)
                return;

            cmnService.J_UserMessage("Text File is successfully generated");
            btnValidateTextFile.Select();
            //
            this.Cursor = Cursors.Default;
        }
        #endregion

