        #region btnCreateBlankExcelFile_Click
        private void btnCreateBlankExcelFile_Click(object sender, EventArgs e)
        {
            try
            {
                string ExcelFileName;
                int intIncrement = 0;
                string strExcelFolder;
                string strExcelFilePath;

                string strDefaultExcelFile = "";
                if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2013_14ID)
                    strDefaultExcelFile = "CorrectionExcel_13-14";
                else
                    strDefaultExcelFile = "CorrectionExcel";

                //Browse Destination folder    
                strExcelFolder = cmnService.J_OpenFolderDialog("Select Destination Folder");

                if (strExcelFolder != "")
                {
                    //Creating a different filename if file with same name exists in the selected folder
                    do
                    {
                        ExcelFileName = strDefaultExcelFile; //Default Filename
                        if (cmnService.J_IsFileExist(Path.Combine(strExcelFolder, ExcelFileName + ".xls")) == true)
                        {
                            intIncrement++;
                            ExcelFileName = ExcelFileName + " (" + intIncrement + ") ";
                        }

                    } while (cmnService.J_IsFileExist(Path.Combine(strExcelFolder, ExcelFileName + ".xls")) == true);


                    strExcelFilePath = Path.Combine(strExcelFolder, ExcelFileName);

                    //Checking if the file template exists in the blank excel file folder
                    if (cmnService.J_IsFileExist(Path.Combine(Application.StartupPath, "Blank Excel File Format\\" + strDefaultExcelFile + ".xls")) == false)
                    {
                        Excel.Application xlApp;
                        Excel.Workbook xlWorkBook;
                        //Excel.Worksheet xlWorkSheet;
                        object misValue = System.Reflection.Missing.Value;
                        //--
                        //string strExcelFileName = cmbFileType.Text.ToUpper() + "_BLANK" + cmbFormNo.Text.ToUpper() + "." + cmbFileType.Text;
                        //--

                        xlApp = new Excel.ApplicationClass();
                        xlWorkBook = xlApp.Workbooks.Add(misValue);

                        //xlWorkSheet = (Excel.Worksheet)xlWorkBook.Worksheets.get_Item(1);
                        //xlWorkSheet.Cells[1, 1] = "http://csharp.net-informations.com";
                        //--
                        //------------------------------------
                        xlWorkBook.SaveAs(strExcelFilePath, Excel.XlFileFormat.xlWorkbookNormal, misValue, misValue, misValue, misValue, Excel.XlSaveAsAccessMode.xlExclusive, misValue, misValue, misValue, misValue, misValue);

                        //------------------------------------
                        xlWorkBook.Close(true, misValue, misValue);
                        xlApp.Quit();

                        //ReleaseObject(xlWorkSheet);
                        ReleaseObject(xlWorkBook);
                        ReleaseObject(xlApp);

                        if (CREATE_NEW_WORKSHEET(strExcelFilePath, T_Sheet_Name.DEDUCTEE_DETAILS) == false) return;

                        if (WRITE_COLUMN_HEADER_WORKSHEET(strExcelFilePath, T_Sheet_Name.DEDUCTEE_DETAILS) == false) return;

                        if (DELETE_WORKSHEET(strExcelFilePath, "Sheet1") == false) return;
                        if (DELETE_WORKSHEET(strExcelFilePath, "Sheet2") == false) return;
                        if (DELETE_WORKSHEET(strExcelFilePath, "Sheet3") == false) return;

                        if (KILL_EXCEL() == false)
                            return;
                        //
                        //--
                        this.Cursor = Cursors.Default;

                        //Added by Shrey Kejriwal on 15/11/2011
                        cmnService.J_CreateDirectory(Path.Combine(Application.StartupPath, "Blank Excel File Format"));


                        File.Copy(strExcelFilePath + ".xls", Path.Combine(Application.StartupPath, "Blank Excel File Format\\" + strDefaultExcelFile + ".xls"), true);

                    }
                    else
                    {
                        File.Copy(Path.Combine(Application.StartupPath, "Blank Excel File Format\\" + strDefaultExcelFile + ".xls"), strExcelFilePath + ".xls");
                    }

                    //Deleting Temporary files
                    Delete_TMP_Files(strExcelFilePath + ".xls");

                    cmnService.J_UserMessage("Excel file created at " + strExcelFilePath + " ");
                }
                else
                {

                    cmnService.J_UserMessage("Destination Folder not selected");
                    return;
                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage("Excel file creation failed");
                return;
            }

        }
        #endregion

