        #region btnValidate_Click
        private void btnValidate_Click(object sender, EventArgs e)
        {
            //--
            prgBar.Value = 0;
            if (ValidateFields() == false) return;
            //--
            string strPath = txtExcelPath.Text.ToString();
            if (TdsMan.T_isFileOpenOrReadOnly(ref strPath) == true)
            {
                cmnService.J_UserMessage("Selected Excel file is open");
                btnSelectExcelPath.Select();
                return;
            }
            //--
            if (cmnService.J_UserMessage("Proceed with excel sheet validation??", MessageBoxButtons.YesNo) == DialogResult.No)
                return;
            //--
            this.Cursor = Cursors.WaitCursor;
            //--
            if (CheckExcelStructure(txtExcelPath.Text) == false)
            {
                this.Cursor = Cursors.Default;
                cmnService.J_UserMessage("Selected Excel file is invalid");
                prgBar.Value = 0;
                btnSelectExcelPath.Select();
                return;
            }
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            //
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Process Started";

            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            // CREATE TEMP TABLES        
            if (CREATE_TEMP_TABLES() == false)
            {
                cmnService.J_UserMessage("Temporary Tables Not created");
                this.Cursor = Cursors.Default;
                prgBar.Value = 0;
                return;
            }
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();

            // GET DATA FROM EXCEL ACCESS       
            //
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Transferring Data";
            //
            if (GET_DATA_FROM_EXCEL_ACCESS() == false)
            {
                cmnService.J_UserMessage("Data transfer failed. Please try again.");
                this.Cursor = Cursors.Default;
                prgBar.Value = 0;
                return;
            }
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            //
            // VALIDATE DATA     
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Validation Started";
            //
            if (VALIDATE_DATA() == false)
            {
                cmnService.J_UserMessage("Data Validation failed");
                this.Cursor = Cursors.Default;
                prgBar.Value = 0;
                return;
            }
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            //    //--
            if (DELETE_WORKSHEET(txtExcelPath.Text, strErrorWorksheetName) == false)
            {
                cmnService.J_UserMessage("Error Sheet Deletion failed");
                this.Cursor = Cursors.Default;
                prgBar.Value = 0;
                return;
            }
            //--

            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            //
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Creating New Worksheet";

            //--
            if (CREATE_NEW_WORKSHEET(txtExcelPath.Text) == false)
            {
                cmnService.J_UserMessage("Error Sheet Creation failed");
                this.Cursor = Cursors.Default;
                prgBar.Value = 0;
                return;
            }
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            //--
            //
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Error sheet writing started";
            //
            if (WRITE_ERROR_WORKSHEET(txtExcelPath.Text) == false)
            {
                cmnService.J_UserMessage("Writing Error Sheet failed");
                this.Cursor = Cursors.Default;
                prgBar.Value = 0;
                return;
            }
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();

            //if (DELETE_DEDUCTEE_WORKSHEET(txtExcelPath.Text) == false)
            //{
            //    cmnService.J_UserMessage("Error Sheet Deletion failed");
            //    this.Cursor = Cursors.Default;
            //    prgBar.Value = 0;
            //    return;
            //}
            //prgBar.Value = prgBar.Value + 5;
            //this.Refresh();
            //    //--                
            if (chkColorCodingExcelsheet.Checked == true)
            {
                //
                lblProgressDisplayMessage.Visible = true;
                lblProgressDisplayMessage.Text = "EXCEL file coloring";
                //
                if (COLOR_ERROR_CELLS(txtExcelPath.Text) == false)
                {
                    cmnService.J_UserMessage("Coloring Error Cells failed");
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }
            }
            //--------
            //--------
            for (int i = prgBar.Minimum; i <= prgBar.Maximum; i++)
            {
                prgBar.PerformStep();
            }
            this.Cursor = Cursors.Default;
            //-- DELETE ALL .tmp FILES
            //
            //foreach (string sFile in System.IO.Directory.GetFiles(Path.GetDirectoryName(txtExcelPath.Text)))
            //{
            //    if(cmnService.J_IsProcessOpen(Path.Combine(Path.GetDirectoryName(txtExcelPath.Text) , Convert.ToString(sFile))) == false)
            //        if (sFile.ToUpper().EndsWith(".TMP"))
            //            System.IO.File.Delete(sFile);
            //}
            Delete_TMP_Files(txtExcelPath.Text);
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Temporary files deleted";
            //
            //--
            lblProgressDisplayMessage.Visible = false;
            //
            if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM TEMP_ERR_VALIDATION"))) == 0)
            {
                if (DELETE_WORKSHEET(txtExcelPath.Text, strErrorWorksheetName) == false) this.Cursor = Cursors.Default;
                //
                cmnService.J_UserMessage("Excel File Validation is completed \n     Proceed to Import ", MessageBoxIcon.Information);
            }
            else
            {
                //cmnService.J_UserMessage("Excel File Validation failed \n Check the <Validation Error> Sheet of the Excel file ", MessageBoxIcon.Exclamation);
                if (cmnService.J_UserMessage("Excel File Validation failed \n Do you want to open the Excel file ?", MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) == DialogResult.Yes)
                {
                    if (File.Exists(txtExcelPath.Text) == true)
                    {
                        System.Diagnostics.Process.Start(txtExcelPath.Text);
                    }
                }
                prgBar.Value = 0;
                return;
            }
            //    //--
            if (LOAD_IMPORT_INTERFACE() == false)
            {
                cmnService.J_UserMessage("Loading Import Interface failed");
                this.Cursor = Cursors.Default;
                prgBar.Value = 0;
                return;
            }
            //LoadChallanGrid();
            //--
            lblTitle.Text = "Excel Import";

            prgBar.Value = 0;
            txtExcelPath.Text = "";

            //Added by Shrey Kejriwal on 24/10/2011

            //--
            //--
            strSQL = "SELECT CHALLAN_SERIAL_NO " +
                     "FROM   TEMP_CORR_CHALLAN " +
                     "WHERE  CHALLAN_TAX - EXISTING_CTRL_TOT_TAX - NEW_CTRL_TOT_TAX < 0 ";

            if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))) > 0)
            {
                btnImport.Text = "Import Data";
                btnImport.Enabled = false;
                btnImport.BackColor = Color.LightGray;
            }
            else
            {
                btnImport.Enabled = true;
                btnImport.Text = "Import Data";
                btnImport.BackColor = Color.Lavender;
            }
        }
        #endregion

        #region btnImport_Click
        private void btnImport_Click(object sender, EventArgs e)
        {
            if (btnImport.Text == "Import Data")
            {
                strSQL = "SELECT CHALLAN_SERIAL_NO " +
                         "FROM   TEMP_CORR_CHALLAN " +
                         "WHERE  CHALLAN_TAX - EXISTING_CTRL_TOT_TAX - NEW_CTRL_TOT_TAX < 0 ";

                if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))) > 0)
                {
                    cmnService.J_UserMessage("Import not possible");
                    return;
                }
                //--
                if (cmnService.J_UserMessage("All the Deductee data will be added to corresponding Challan. \n Proceed??", MessageBoxButtons.YesNo) == DialogResult.No)
                    return;

                prgImportBar.Value = 0;
                //--
                this.Cursor = Cursors.WaitCursor;
                //--                
                prgImportBar.Value = prgImportBar.Value + 20;
                this.Refresh();
                //--
                if (INSERT_DEDUCTEE_DATA() == false)
                {
                    cmnService.J_UserMessage("Import failed");
                    this.Cursor = Cursors.Default;
                    return;
                }
                this.Refresh();

                prgImportBar.Value = prgImportBar.Value + 20;
                this.Refresh();

                //
                //--
                if (DROP_TEMP_TABLES() == false)
                {
                    cmnService.J_UserMessage("Import failed");
                    this.Cursor = Cursors.Default;
                    return;
                }
                this.Refresh();

                prgImportBar.Value = prgImportBar.Value + 20;
                this.Refresh();

                //
                for (int i = prgImportBar.Minimum; i <= prgImportBar.Maximum; i++)
                {
                    prgImportBar.PerformStep();
                }
                //
                btnImport.Enabled = false;
                btnImport.BackColor = Color.LightGray;
                //
                this.Cursor = Cursors.Default;
                //--
                //BtnExit.Text = "E&xit";
                //--
                cmnService.J_UserMessage("Import from Excel File completed", MessageBoxIcon.Information);
                prgImportBar.Value = 0;
                //prgSDBar.Value = 0;

                prgImportBar.Value = 0;

                blnOpenTabPage = true;
                tbcCompany.SelectTab(tbpChallanDetails);

                //Added by Shrey Kejriwal on 03/11/2011
                btnExcelActivate.Text = "Add Deductees using Excel";
                btnExcelActivate.Visible = true;

                //-----------------------------------------------------------
                lblMode.Text = J_Mode.Add;
                lblMode.ForeColor = Color.GreenYellow;
                lblSearchMode.Text = Tabbed_Mode.Challan;
                //--
                BackgroundColorChangeChallan(lblMode.Text);
                //
                LoadForm(txtFormNo.Text, lblSearchMode.Text);
                //---------------------------------------------
                btnChallanDeducteeEntry.Text = "Deductee Details";
                //--
                BtnSave.Enabled = true;
                BtnSave.BackColor = Color.Lavender;
                //--
                BtnCancel.Enabled = true;
                BtnCancel.BackColor = Color.Lavender;
                BtnCancel.Text = "Back to Basic Screen";
                //--
                BtnSort.Enabled = true;
                BtnSort.BackColor = Color.Lavender;
                //--
                BtnSearch.Enabled = true;
                BtnSearch.BackColor = Color.Lavender;
                //--
                BtnRefresh.Enabled = true;
                BtnRefresh.BackColor = Color.Lavender;
                //--
                btnSalaryDetail.Visible = false;
                //--
                if (TDSMAN.Classes.TDSMAN.T_ShowAllocatedFileds == false)
                {
                    lblInterestAllocated.Visible = false;
                    txtInterestAllocated.Visible = false;
                    lblOthersAllocated.Visible = false;
                    txtOthersAllocated.Visible = false;
                }
                lblRemarks.Location = new Point(14, 334);
                txtRemarks.Location = new Point(74, 331);
                //--
                btnChallanDeducteeEntry.Visible = true;
                btnChallanDeducteeEntry.Enabled = false;
                btnChallanDeducteeEntry.BackColor = Color.LightGray;
                //---------------------------------------------
                //grpMain.Enabled = false;
                //--
                ClearControls();
                //-----------
                //-- SECTION
                //-----------
                strSQL = " SELECT SECTION_ID," +
                    "             SECTION_NO " +
                    "      FROM   MST_SECTION " +
                    "      WHERE  FORM_NAME = '" + txtFormNo.Text.Trim() + "' " +
                    "      AND    ASST_ID <= " + Convert.ToInt32(txtFAYearID.Text) + " " +
                    "      ORDER BY SECTION_ID";
                if (dmlService.J_PopulateComboBox(strSQL, ref cmbSection) == false) return;
                //-----------
                mskDateOfPayment.Text = System.DateTime.Now.ToString();
                txtBSRCode.Text = "";
                txtChequeNo.Text = "";
                //-----------------------------------------------------------
                //-- Generate Challan Srl No.
                txtChallanSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("COR_TRN_CHALLAN", "SL_NO", "BATCH_HEADER_ID = " + lngBatchId + "") + 1);
                //--
                if (cmbDeductorType.Text.Trim().Length > 0)
                {
                    if (cmbDeductorType.Text.Substring(0, 1) == "A" || cmbDeductorType.Text.Substring(0, 1) == "S")
                    {
                        //txtTransferVoucherNo.Enabled = true;
                        //txtTransferVoucherNo.BackColor = Color.White;
                        //
                        chkBookEntry.Visible = true;
                        lblSrlNo.Location = new Point(59, 10);
                        txtChallanSrlNo.Location = new Point(107, 7);
                    }
                    else
                    {
                        //txtTransferVoucherNo.Enabled = false;
                        //txtTransferVoucherNo.BackColor = Color.LightGray;
                        //
                        chkBookEntry.Visible = false;
                        lblSrlNo.Location = new Point(85, 10);
                        txtChallanSrlNo.Location = new Point(170, 7);
                    }
                }
                //--
                LoadChallanGrid();
                //--
                cmbSection.Select();

                ControlSummaryVisible(false, false, false, false, false, false, false);

            }
            else
            {
                if (LOAD_IMPORT_INTERFACE() == false)
                {
                    cmnService.J_UserMessage("Loading Import Interface failed");
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }
                //LoadChallanGrid();
                //--
                lblTitle.Text = "Excel Import";

                lblDoubleClickonChallan.Visible = true;

                prgBar.Value = 0;
                txtExcelPath.Text = "";

                //Added by Shrey Kejriwal on 24/10/2011

                //--
                //--
                strSQL = "SELECT CHALLAN_SERIAL_NO " +
                         "FROM   TEMP_CORR_CHALLAN " +
                         "WHERE  CHALLAN_TAX - EXISTING_CTRL_TOT_TAX - NEW_CTRL_TOT_TAX < 0 ";

                if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))) > 0)
                {
                    btnImport.Text = "Import Data";
                    btnImport.Enabled = false;
                    btnImport.BackColor = Color.LightGray;
                }
                else
                {
                    btnImport.Enabled = true;
                    btnImport.Text = "Import Data";
                    btnImport.BackColor = Color.Lavender;
                }
            }
        }
