        #region dgcViewChallanExcel_KeyDown
        private void dgcViewChallanExcel_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Enter) dgcViewChallanExcel_DoubleClick(sender, e);
        }
        #endregion

        #region dgcViewChallanExcel_MouseClick
        private void dgcViewChallanExcel_MouseClick(object sender, MouseEventArgs e)
        {
            if (dgcViewChallanExcel.Visible == false) return;
            //
            dgcViewChallanExcel.Select(dgcViewChallanExcel.CurrentRowIndex);
            dgcViewChallanExcel.Select();
            dgcViewChallanExcel.Focus();
        }
        #endregion

        #region dgcViewChallanExcel_DoubleClick
        private void dgcViewChallanExcel_DoubleClick(object sender, EventArgs e)
        {
            //Added By Shrey Kejriwal on 21/10/2011
            if (dgcViewChallanExcel.CurrentRowIndex >= 0)
            {
                dgcViewChallanExcel.Visible = false;

                //--
                dgcViewDeducteeExcel.Visible = true;
                btnImport.Text = "Back";
                btnImport.BackColor = Color.Lavender;
                btnImport.Enabled = true;

                lblDoubleClickonChallan.Visible = false;
                //--------------------------------------------------
                //A particular ID wise retriving the data from database
                if (LoadDeducteeDetailsGrid(Convert.ToInt64(Convert.ToString(dgcViewChallanExcel[dgcViewChallanExcel.CurrentRowIndex, 0]))) == false)
                {
                    return;
                }
            }
        }


        #endregion

        #region dgcViewChallanExcel_MouseUp
        private void dgcViewChallanExcel_MouseUp(object sender, MouseEventArgs e)
        {
            dgcViewChallanExcel_Click(sender, e);
        }
        #endregion

        #region dgcViewChallanExcel_Click
        private void dgcViewChallanExcel_Click(object sender, EventArgs e)
        {
            if (Convert.ToInt64(Convert.ToString(dgcViewChallanExcel.CurrentRowIndex)) < 0)
            {
                btnImport.Focus();
                return;
            }
            lngSearchId = Convert.ToInt64(Convert.ToString(dgcViewChallanExcel[dgcViewChallanExcel.CurrentRowIndex, 0]));

            dgcViewChallanExcel.Select(dgcViewChallanExcel.CurrentRowIndex);
            dgcViewChallanExcel.Select();
            dgcViewChallanExcel.Focus();
        }
        #endregion

