            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            //-----------------------------------------------------------
            try
            {
                //if (BasicInfoId == 0)
                //    strCompanyTableName = "MST_COMPANY";
                //else
                //    strCompanyTableName = "TRN_COMPANY_INFO";
                //
                strSQL = "SELECT  COR_TRN_COMPANY.HDR_COMPANY_ID        AS HDR_COMPANY_ID," +
