        #region ShowChallanRecord
        private bool ShowChallanRecord()
        {
            IDataReader drdShowChallanRecord = null;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            try
            {
                strSQL = "SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID      AS TRN_CHALLAN_ID," +
                    "            COR_TRN_CHALLAN.SL_NO               AS SL_NO," +
                    "            COR_TRN_CHALLAN.SECTION_ID          AS SECTION_ID," +
                    "            MST_SECTION.SECTION_NO              AS SECTION_NO," +
                    "            MST_SECTION.SECTION_DESCRIPTION     AS SECTION_DESCRIPTION," +
                    "            " + cmnService.J_SQLDBFormat("COR_TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " AS DEPOSIT_DATE," +
                    "            COR_TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                    "            COR_TRN_CHALLAN.CHALLAN_NO          AS CHALLAN_NO," +
                    "            COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO AS TRANSFER_VOUCHER_NO," +
                    "            COR_TRN_CHALLAN.CHEQUE_NO           AS CHEQUE_NO," +
                    "            COR_TRN_CHALLAN.TDS                 AS TDS," +
                    "            COR_TRN_CHALLAN.SURCHARGE           AS SURCHARGE," +
                    "            COR_TRN_CHALLAN.EDUCATION_CESS      AS EDUCATION_CESS," +
                    "            COR_TRN_CHALLAN.INTEREST            AS INTEREST," +
                    "            COR_TRN_CHALLAN.OTHERS              AS OTHERS," +
                    "            COR_TRN_CHALLAN.TOT_TAX             AS TOT_TAX," +
                    "            COR_TRN_CHALLAN.INTEREST_ALLOCATED  AS INTEREST_ALLOCATED," +
                    "            COR_TRN_CHALLAN.OTHERS_ALLOCATED    AS OTHERS_ALLOCATED," +
                    "            COR_TRN_CHALLAN.REMARKS             AS REMARKS," +
                    "            COR_TRN_CHALLAN.BOOK_ENTRY          AS BOOK_ENTRY, " +
                    "            COR_TRN_CHALLAN.CHALLAN_STATUS      AS CHALLAN_STATUS," +
                    "            COR_TRN_CHALLAN.LATE_FEE            AS LATE_FEE," +
                    "            MST_MINOR_HEAD.MINOR_HEAD_CODE + '-' + MST_MINOR_HEAD.MINOR_HEAD_DESC AS MINOR_HEAD " +
                    //"     FROM   COR_TRN_CHALLAN," +
                    //"            MST_SECTION " +
                    //"     WHERE  COR_TRN_CHALLAN.SECTION_ID     = MST_SECTION.SECTION_ID " +
                    "FROM   ((COR_TRN_CHALLAN " +
                    "LEFT JOIN       MST_SECTION " +
                    "        ON COR_TRN_CHALLAN.SECTION_ID     = MST_SECTION.SECTION_ID) " +
                    "LEFT JOIN MST_MINOR_HEAD " +
                    "        ON  COR_TRN_CHALLAN.MINOR_HEAD_ID = MST_MINOR_HEAD.MINOR_HEAD_ID)" +
                    "WHERE   COR_TRN_CHALLAN.TRN_CHALLAN_ID = " + lngChallanID + " ";

                drdShowChallanRecord = dmlService.J_ExecSqlReturnReader(strSQL);
                if (drdShowChallanRecord == null)
                    return false;
                //--
                while (drdShowChallanRecord.Read())
                {
                    txtChallanSrlNo.Text = Convert.ToString(drdShowChallanRecord["SL_NO"]);

                    if (cmnService.J_ReturnInt32Value(txtFAYearID.Text) < T_FinancialYearID.F2013_14ID)
                    {
                        blnSectionDisplay = false;
                        cmbSection.Text = Convert.ToString(drdShowChallanRecord["SECTION_NO"]);
                        lblSectionDisplay.Visible = true;
                        lblSectionDisplay.Text = Convert.ToString(drdShowChallanRecord["SECTION_DESCRIPTION"]);
                        blnSectionDisplay = true;
                    }

                    mskDateOfPayment.Text = Convert.ToString(drdShowChallanRecord["DEPOSIT_DATE"]);
                    txtBSRCode.Text = Convert.ToString(drdShowChallanRecord["BSR_CODE"]);
                    txtChallanNo.Text = Convert.ToString(drdShowChallanRecord["CHALLAN_NO"]);
                    txtTransferVoucherNo.Text = Convert.ToString(drdShowChallanRecord["TRANSFER_VOUCHER_NO"]);
                    txtChequeNo.Text = Convert.ToString(drdShowChallanRecord["CHEQUE_NO"]);
                    txtTDS.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["TDS"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["TDS"])));
                    txtSurcharge.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["SURCHARGE"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["SURCHARGE"])));
                    txtEducationCess.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["EDUCATION_CESS"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["EDUCATION_CESS"])));
                    txtInterests.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["INTEREST"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["INTEREST"])));
                    txtOthers.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["OTHERS"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["OTHERS"])));
                    txtTotalTax.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["TOT_TAX"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["TOT_TAX"])));
                    txtInterestAllocated.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["INTEREST_ALLOCATED"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["INTEREST_ALLOCATED"])));
                    txtOthersAllocated.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["OTHERS_ALLOCATED"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["OTHERS_ALLOCATED"])));
                    txtRemarks.Text = Convert.ToString(drdShowChallanRecord["REMARKS"]);
                    //
                    txtFee.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["LATE_FEE"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["LATE_FEE"])));
                    cmbMinorHead.Text = Convert.ToString(drdShowChallanRecord["MINOR_HEAD"]);
                    //
                    if (Convert.ToString(drdShowChallanRecord["BOOK_ENTRY"]) == "1")
                    {
                        chkBookEntry.Checked = true;
                        txtBookEntryM.Text = "1";
                    }
                    else if (Convert.ToString(drdShowChallanRecord["BOOK_ENTRY"]) == "0")
                    {
                        chkBookEntry.Checked = false;
                        txtBookEntryM.Text = "0";
                    }

                    //Added by Shrey Kejriwal on 09/08/2011
                    txtChallanStatus.Text = Convert.ToString(drdShowChallanRecord["CHALLAN_STATUS"]);

                    if (txtChallanStatus.Text == "M")
                    {
                        lblChallanStatusText.Visible = true;
                        lblChallanStatusText.Text = "Matched challan.";
                        lblChallanStatusText.ForeColor = Color.Green;
                    }
                    else if (txtChallanStatus.Text == "U")
                    {
                        lblChallanStatusText.Visible = true;
                        lblChallanStatusText.ForeColor = Color.Red;
                        lblChallanStatusText.Text = "Unmatched Challan";
                    }
                    else if (txtChallanStatus.Text == "P")
                    {
                        lblChallanStatusText.Visible = true;
                        lblChallanStatusText.ForeColor = Color.Green;
                        lblChallanStatusText.Text = "Provisionally matched challan";
                    }
                    else if (txtChallanStatus.Text == "O")
                    {
                        lblChallanStatusText.Visible = true;
                        lblChallanStatusText.ForeColor = Color.Red;
                        lblChallanStatusText.Text = "Overbooked Challan";
                    }
                    else
                    {
                        lblChallanStatusText.Visible = false;
                        lblChallanStatusText.Text = "";
                    }
                    //
                    txtDateOfPaymentM.Text = Convert.ToString(drdShowChallanRecord["DEPOSIT_DATE"]);
                    txtTransferVoucherNoM.Text = Convert.ToString(drdShowChallanRecord["TRANSFER_VOUCHER_NO"]);
                    txtChallanNoM.Text = Convert.ToString(drdShowChallanRecord["CHALLAN_NO"]);
                    txtSectionM.Text = Convert.ToString(drdShowChallanRecord["SECTION_NO"]);
                    txtBSRCodeM.Text = Convert.ToString(drdShowChallanRecord["BSR_CODE"]);
                    txtChequeNoM.Text = Convert.ToString(drdShowChallanRecord["CHEQUE_NO"]);
                    txtTDSM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["TDS"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["TDS"])));
                    txtSurchargeM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["SURCHARGE"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["SURCHARGE"])));
                    txtEducationCessM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["EDUCATION_CESS"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["EDUCATION_CESS"])));
                    txtInterestsM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["INTEREST"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["INTEREST"])));
                    txtOthersM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["OTHERS"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["OTHERS"])));
                    txtTotalTaxM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["TOT_TAX"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["TOT_TAX"])));
                    txtInterestAllocatedM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["INTEREST_ALLOCATED"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["INTEREST_ALLOCATED"])));
                    txtOthersAllocatedM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowChallanRecord["OTHERS_ALLOCATED"]) == "" ? "0" : Convert.ToString(drdShowChallanRecord["OTHERS_ALLOCATED"])));
                    txtRemarksM.Text = Convert.ToString(drdShowChallanRecord["REMARKS"]);
                    //




                    drdShowChallanRecord.Close();
                    drdShowChallanRecord.Dispose();

                    cmbSection.Select();
                    //ControlSummaryChallan(lngChallanID);                
                    return true;
                }
                //-----------------------------------------------------------
                drdShowChallanRecord.Close();
                drdShowChallanRecord.Dispose();

                //ControlSummaryChallan(lngChallanID);
                //-----------------------------------------------------------
                cmnService.J_UserMessage(J_Msg.RecNotExist);
                //-----------------------------------------------------------
                lngChallanID = 0;
                //-----------------------------------------------------------
                if (strCheckFields == "")
                    strSQL = strQuery + "order by " + strOrderBy;
                else
                    strSQL = strQuery + strCheckFields + "order by " + strOrderBy;
                //-----------------------------------------------------------
                if (dsetChallanGridClone != null) dsetChallanGridClone.Clear();
                dsetChallanGridClone = dmlService.J_ShowDataInGrid(ref dgvViewChallan, strSQL, strMatrix);       //Show Data into the Grid
                return false;
            }
            catch (Exception err_handler)
            {
                drdShowChallanRecord.Close();
                drdShowChallanRecord.Dispose();
                cmnService.J_UserMessage(err_handler.Message);
                return false;
            }
        }
        #endregion

