        #region ShowChallanDetailsRecord
        private bool ShowChallanDetailsRecord()
        {
            IDataReader drdShowChallanDetailsRecord = null;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            try
            {
                string[,] strShowChallanDetailsRecordMatrix = {{"COR_TRN_CHALLAN.BOOK_ENTRY = 1 ", "F", "COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                {"COR_TRN_CHALLAN.BOOK_ENTRY = 0 ", "F", "COR_TRN_CHALLAN.CHALLAN_NO", "F"}};

                //Added by Shrey Kejriwal on 12/02/2014
                //Condition to show Total Tax based on Book entry value
                string[,] strLoadChallanTotTaxMatrix = {{"COR_TRN_CHALLAN.BOOK_ENTRY =  1", "F", "COR_TRN_CHALLAN.TOT_TAX - COR_TRN_CHALLAN.INTEREST_ALLOCATED - COR_TRN_CHALLAN.OTHERS_ALLOCATED", "F"},
                                                    {"COR_TRN_CHALLAN.BOOK_ENTRY <> 1", "F", "COR_TRN_CHALLAN.TOT_TAX - COR_TRN_CHALLAN.INTEREST_ALLOCATED - COR_TRN_CHALLAN.OTHERS_ALLOCATED - COR_TRN_CHALLAN.LATE_FEE", "F"}};


                strSQL = "SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID      AS TRN_CHALLAN_ID," +
                    "            COR_TRN_CHALLAN.SL_NO               AS SL_NO," +
