        #region ShowDeducteeRecord
        private bool ShowDeducteeRecord()
        {
            IDataReader drdShowDeducteeRecord = null;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            try
            {
                string[,] strGrossingUpIndicatorMatrix = {{"COR_TRN_DEDUCTEE_DETAILS.GROSSING_UP_INDICATOR = 'Y' ", "F", "Yes", "T"},
                                                {"COR_TRN_DEDUCTEE_DETAILS.GROSSING_UP_INDICATOR = 'N'", "F", "No", "T"},
                                                {"COR_TRN_DEDUCTEE_DETAILS.GROSSING_UP_INDICATOR = ''", "F", "", "T"}};

                string[,] strShowDeducteeCodeMatrix = {{"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_CODE ='01'" , "F", T_DeducteeCodeDesc.Company, "T"},
                                                {"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_CODE = '02'", "F", T_DeducteeCodeDesc.NonCompany, "T"}};

                strSQL = "SELECT COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID AS TRN_DEDUCTEE_DETAIL_ID," +
                    "            COR_TRN_DEDUCTEE_DETAILS.SL_NO                  AS SL_NO," +
                    "            COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME          AS DEDUCTEE_NAME," +
                    "            COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN           AS DEDUCTEE_PAN," +
                    "            " + cmnService.J_SQLDBFormat(strShowDeducteeCodeMatrix, J_SQLColFormat.Case_End) + " AS DEDUCTEE_CODE," +
                    "            " + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " AS PAYMENT_DATE," +
                    "            " + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " AS DEDUCTED_DATE," +
                    "            COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT         AS PAYMENT_AMOUNT," +
                    "            COR_TRN_DEDUCTEE_DETAILS.RATE                   AS RATE," +
                    "            COR_TRN_DEDUCTEE_DETAILS.TAX_AMOUNT             AS TAX_AMOUNT," +
                    "            COR_TRN_DEDUCTEE_DETAILS.SURCHARGE_AMOUNT       AS SURCHARGE_AMOUNT," +
                    "            COR_TRN_DEDUCTEE_DETAILS.CESS_AMOUNT            AS CESS_AMOUNT," +
                    "            COR_TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT           AS TOTAL_AMOUNT," +
                    "            COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT   AS TAX_DEPOSITED_AMOUNT," +
                    //"            COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG     AS NON_DEDUCTION_FLAG," +
                    "            " + cmnService.J_SQLDBFormat(strGrossingUpIndicatorMatrix, J_SQLColFormat.Case_End) + " AS GROSSING_UP_INDICATOR," +
                    "            COR_TRN_DEDUCTEE_DETAILS.TOT_VALUE_PURCHASE     AS TOT_VALUE_PURCHASE," +
                    "            COR_TRN_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY        AS CASH_BOOK_ENTRY," +
                    "            REASON + ' ' + MST_REASON.DESCRIPTION           AS REASON_DESCRIPTION," +
                    "            MST_SECTION.SECTION_NO                          AS SECTION_NO," +
                    "            MST_SECTION.SECTION_DESCRIPTION                 AS SECTION_DESCRIPTION," +
                    "            COR_TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO         AS CERTIFICATE_NO," +
                    "            REMITTANCE_CODE + ' ' + REMITTANCE_DESC         AS REMITTANCE_DESC," +
                    "            TDS_APPLICABILITY_CODE + ' ' + TDS_APPLICABILITY_DESC AS TDS_APPLICABILITY_DESC," +
                    "            COUNTRY_CODE + ' ' + COUNTRY_DESC               AS COUNTRY_DESC," +
                    "            COR_TRN_DEDUCTEE_DETAILS.UNIQUE_ACKN            AS UNIQUE_ACKN " +
                    "     FROM (((((COR_TRN_DEDUCTEE_DETAILS INNER JOIN MST_REASON " +
                    "            ON COR_TRN_DEDUCTEE_DETAILS.REASON_ID = MST_REASON.REASON_ID) " +
                    "            INNER JOIN MST_SECTION " +
                    "            ON COR_TRN_DEDUCTEE_DETAILS.SECTION_ID = MST_SECTION.SECTION_ID) " +
                    "            LEFT JOIN MST_REMITTANCE " +
                    "            ON COR_TRN_DEDUCTEE_DETAILS.REMITTANCE_ID = MST_REMITTANCE.REMITTANCE_ID) " +
                    "            LEFT JOIN MST_TDS_APPLICABILITY " +
                    "            ON COR_TRN_DEDUCTEE_DETAILS.TDS_APPLICABILITY_ID = MST_TDS_APPLICABILITY.TDS_APPLICABILITY_ID) " +
                    "            LEFT JOIN MST_COUNTRY " +
                    "            ON COR_TRN_DEDUCTEE_DETAILS.COUNTRY_ID = MST_COUNTRY.COUNTRY_ID) " +
                    //"     FROM   COR_TRN_DEDUCTEE_DETAILS," +
                    //"            MST_REASON," +
                    //"            MST_SECTION " +
                    //"     WHERE  COR_TRN_DEDUCTEE_DETAILS.REASON_ID              = MST_REASON.REASON_ID " +
                    //"     AND    COR_TRN_DEDUCTEE_DETAILS.SECTION_ID             = MST_SECTION.SECTION_ID " +
                    "     WHERE    COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID = " + lngDeducteeID + " ";

                drdShowDeducteeRecord = dmlService.J_ExecSqlReturnReader(strSQL);

                if (drdShowDeducteeRecord == null)
                    return false;
                //--
                while (drdShowDeducteeRecord.Read())
                {
                    blnShowHelp = false;
                    blnShowPANHelp = false;

                    txtDeducteeSrlNo.Text = Convert.ToString(drdShowDeducteeRecord["SL_NO"]);

                    txtDeducteeName.Text = Convert.ToString(drdShowDeducteeRecord["DEDUCTEE_NAME"]);
                    txtDeducteeName.SelectionStart = 0;

                    txtDeducteePAN.Text = Convert.ToString(drdShowDeducteeRecord["DEDUCTEE_PAN"]);
                    //
                    //if (Convert.ToString(drdShowDeducteeRecord["DEDUCTEE_CODE"]) == "1")
                    //{
                    //    cmbDeducteeCode.Text = "01";
                    //    //txtDeducteeCodeM.Text = "01";
                    //}
                    //else
                    //{
                    //    cmbDeducteeCode.Text = "02";
                    //    //txtDeducteeCodeM.Text = "02";
                    //}
                    cmbDeducteeCode.Text = Convert.ToString(drdShowDeducteeRecord["DEDUCTEE_CODE"]);
                    //
                    mskDeducteeDate.Text = Convert.ToString(drdShowDeducteeRecord["PAYMENT_DATE"]);
                    txtDeducteeAmountOfPayment.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["PAYMENT_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["PAYMENT_AMOUNT"])));
                    txtDeducteeRate.Text = string.Format("{0:0.0000}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["RATE"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["RATE"])));
                    txtDeducteeIncometax.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["TAX_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["TAX_AMOUNT"])));
                    txtDeducteeSurcharge.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["SURCHARGE_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["SURCHARGE_AMOUNT"])));
                    txtDeducteeCess.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["CESS_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["CESS_AMOUNT"])));
                    txtDeducteeTotal.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["TOTAL_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["TOTAL_AMOUNT"])));
                    txtDeducteeTaxDeposited.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["TAX_DEPOSITED_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["TAX_DEPOSITED_AMOUNT"])));
                    txtDeducteeTaxDepositedM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["TAX_DEPOSITED_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["TAX_DEPOSITED_AMOUNT"])));

                    //if (Convert.ToString(drdShowDeducteeRecord["NON_DEDUCTION_FLAG"]) == "")
                    //    rbnNormal.Checked = true;
                    //else if (Convert.ToString(drdShowDeducteeRecord["NON_DEDUCTION_FLAG"]) == "A")
                    //    rbnLowerNoDeduction.Checked = true;
                    //else if (Convert.ToString(drdShowDeducteeRecord["NON_DEDUCTION_FLAG"]) == "T")
                    //    rbnTransporter.Checked = true;
                    //else if (Convert.ToString(drdShowDeducteeRecord["NON_DEDUCTION_FLAG"]) == "B")
                    //    rbnNoDeduction.Checked = true;
                    //else if (Convert.ToString(drdShowDeducteeRecord["NON_DEDUCTION_FLAG"]) == "C")
                    //    rbnHigherRate.Checked = true;
                    //else if (Convert.ToString(drdShowDeducteeRecord["NON_DEDUCTION_FLAG"]) == "Y")
                    //    rbnThresholdLimit.Checked = true;
                    //else if (Convert.ToString(drdShowDeducteeRecord["NON_DEDUCTION_FLAG"]) == "S")
                    //    rbnSoftware.Checked = true;
                    cmbRemarks.Text = Convert.ToString(drdShowDeducteeRecord["REASON_DESCRIPTION"]);

                    cmbGrossingUpIndicator.Text = Convert.ToString(drdShowDeducteeRecord["GROSSING_UP_INDICATOR"]);
                    txtTotValuePurchase.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["TOT_VALUE_PURCHASE"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["TOT_VALUE_PURCHASE"])));

                    // ANIK 2011-08-04
                    if (Convert.ToString(drdShowDeducteeRecord["CASH_BOOK_ENTRY"]) == "1")
                        chkCashBookEntry.Checked = true;
                    else
                        chkCashBookEntry.Checked = false;

                    mskDeductedDate.Text = Convert.ToString(drdShowDeducteeRecord["DEDUCTED_DATE"]);
                    //
                    if (cmnService.J_ReturnInt32Value(txtFAYearID.Text) >= T_FinancialYearID.F2013_14ID)
                    {
                        blnSectionDDDisplay = false;
                        cmbDDSection.Text = Convert.ToString(drdShowDeducteeRecord["SECTION_NO"]);
                        lblDDSectionDisplay.Visible = true;
                        lblDDSectionDisplay.Text = Convert.ToString(drdShowDeducteeRecord["SECTION_DESCRIPTION"]);
                        blnSectionDDDisplay = true;
                    }
                    //
                    txtCertificateNo.Text = Convert.ToString(drdShowDeducteeRecord["CERTIFICATE_NO"]);
                    //
                    cmbRemittance.Text = Convert.ToString(drdShowDeducteeRecord["REMITTANCE_DESC"]);
                    cmbTDSRate.Text = Convert.ToString(drdShowDeducteeRecord["TDS_APPLICABILITY_DESC"]);
                    cmbCountry.Text = Convert.ToString(drdShowDeducteeRecord["COUNTRY_DESC"]);
                    txtUniqueAckn.Text = Convert.ToString(drdShowDeducteeRecord["UNIQUE_ACKN"]);
                    //
                    blnShowHelp = true;
                    blnShowPANHelp = true;

                    drdShowDeducteeRecord.Close();
                    drdShowDeducteeRecord.Dispose();

                    txtDeducteeName.Select();
                    return true;
                }
                //-----------------------------------------------------------
                drdShowDeducteeRecord.Close();
                drdShowDeducteeRecord.Dispose();
                //-----------------------------------------------------------
                cmnService.J_UserMessage(J_Msg.RecNotExist);
                //-----------------------------------------------------------
                lngChallanID = 0;
                //-----------------------------------------------------------
                if (strCheckFields == "")
                    strSQL = strQuery + "order by " + strOrderBy;
                else
                    strSQL = strQuery + strCheckFields + "order by " + strOrderBy;
                //-----------------------------------------------------------
                if (dsetChallanGridClone != null) dsetChallanGridClone.Clear();
                dsetChallanGridClone = dmlService.J_ShowDataInGrid(dmlService.J_pCommand, ref dgvDeductee, strSQL, strMatrix);       //Show Data into the Grid
                return false;
            }
            catch (Exception err_handler)
            {
                drdShowDeducteeRecord.Close();
                drdShowDeducteeRecord.Dispose();
                cmnService.J_UserMessage(err_handler.Message);
                return false;
            }
        }
