                    "            COR_HDR_DEDUCTEE_DETAILS.UNIQUE_ACKN            AS UNIQUE_ACKN " +
                    "     FROM ((((((COR_HDR_DEDUCTEE_DETAILS INNER JOIN COR_TRN_DEDUCTEE_DETAILS " +
                    "            ON COR_HDR_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID = COR_TRN_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID) " +
                    "            INNER JOIN MST_REASON " +
                    "            ON COR_HDR_DEDUCTEE_DETAILS.REASON_ID = MST_REASON.REASON_ID) " +
                    "            INNER JOIN MST_SECTION " +
                    "            ON COR_HDR_DEDUCTEE_DETAILS.SECTION_ID = MST_SECTION.SECTION_ID) " +
                    "            LEFT JOIN MST_REMITTANCE " +
                    "            ON COR_HDR_DEDUCTEE_DETAILS.REMITTANCE_ID = MST_REMITTANCE.REMITTANCE_ID) " +
                    "            LEFT JOIN MST_TDS_APPLICABILITY " +
                    "            ON COR_HDR_DEDUCTEE_DETAILS.TDS_APPLICABILITY_ID = MST_TDS_APPLICABILITY.TDS_APPLICABILITY_ID) " +
                    "            LEFT JOIN MST_COUNTRY " +
                    "            ON COR_HDR_DEDUCTEE_DETAILS.COUNTRY_ID = MST_COUNTRY.COUNTRY_ID) " +
                    //"     FROM   COR_HDR_DEDUCTEE_DETAILS," +
                    //"            COR_TRN_DEDUCTEE_DETAILS," +
                    //"            MST_REASON," +
                    //"            MST_SECTION " +
                    //"     WHERE  COR_HDR_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID = COR_TRN_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID " +
                    //"     AND    COR_HDR_DEDUCTEE_DETAILS.REASON_ID              = MST_REASON.REASON_ID " +
                    //"     AND    COR_HDR_DEDUCTEE_DETAILS.SECTION_ID             = MST_SECTION.SECTION_ID " +
                    "     WHERE  COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID = " + lngDeducteeID + " " +
                    "     AND    COR_TRN_DEDUCTEE_DETAILS.IMPORT_FLAG            = 1";

                drdShowDeducteeRecord = dmlService.J_ExecSqlReturnReader(strSQL);
                if (drdShowDeducteeRecord == null)
                    return false;
                //
                while (drdShowDeducteeRecord.Read())
                {

                    //
                    //if (Convert.ToString(drdShowDeducteeRecord["DEDUCTEE_CODE"]) == "1")
                    //    txtDeducteeCodeM.Text = "01";
                    //else
                    //    txtDeducteeCodeM.Text = "02";
                    //txtDeducteeCodeM.Text = ;
                    ////

                    if (Convert.ToString(drdShowDeducteeRecord["DEDUCTEE_CODE"]) != "")
                        txtDeducteeCodeM.Text = string.Format("{0:00}", Convert.ToInt16(drdShowDeducteeRecord["DEDUCTEE_CODE"]));
                    else
                        txtDeducteeCodeM.Text = "";

                    txtDeducteeNameM.Text = Convert.ToString(drdShowDeducteeRecord["DEDUCTEE_NAME"]);
                    txtDeducteePANM.Text = Convert.ToString(drdShowDeducteeRecord["DEDUCTEE_PAN"]);
                    txtDeducteeDateM.Text = Convert.ToString(drdShowDeducteeRecord["PAYMENT_DATE"]);
                    txtDeducteeAmountOfPaymentM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["PAYMENT_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["PAYMENT_AMOUNT"])));
                    txtDeducteeRateM.Text = string.Format("{0:0.0000}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["RATE"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["RATE"])));
                    txtDeducteeIncometaxM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["TAX_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["TAX_AMOUNT"])));
                    txtDeducteeTotalM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["TOTAL_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["TOTAL_AMOUNT"])));
                    txtDeducteeSurchargeM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["SURCHARGE_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["SURCHARGE_AMOUNT"])));
                    txtDeducteeCessM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["CESS_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["CESS_AMOUNT"])));
                    //-- ANIK 2011-09-10
                    txtDeducteeTaxDepositedM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["TAX_DEPOSITED_AMOUNT"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["TAX_DEPOSITED_AMOUNT"])));
                    //txtDeducteeRemarksM.Text = Convert.ToString(drdShowDeducteeRecord["NON_DEDUCTION_FLAG"]);

                    if (txtFormNo.Text.Trim() == T_FormNo.F27Q)
                        txtToggleTextM.Text = Convert.ToString(drdShowDeducteeRecord["GROSSING_UP_INDICATOR"]);
                    else if (txtFormNo.Text.Trim() == T_FormNo.F27EQ)
                        txtToggleTextM.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdShowDeducteeRecord["TOT_VALUE_PURCHASE"]) == "" ? "0" : Convert.ToString(drdShowDeducteeRecord["TOT_VALUE_PURCHASE"])));

                    // ANIK 2011-08-04
                    if (Convert.ToString(drdShowDeducteeRecord["CASH_BOOK_ENTRY"]) == "1")
                        txtCashBookEntryM.Text = "1";
                    else
                        txtCashBookEntryM.Text = "0";

                    txtDeductedDateM.Text = Convert.ToString(drdShowDeducteeRecord["DEDUCTED_DATE"]);
                    //
                    txtDeducteeRemarksM.Text = Convert.ToString(drdShowDeducteeRecord["REASON_DESCRIPTION"]);
                    txtCertificateNoM.Text = Convert.ToString(drdShowDeducteeRecord["CERTIFICATE_NO"]);
                    txtDDSectionM.Text = Convert.ToString(drdShowDeducteeRecord["HDR_SECTION_NO"]);
                    //
                    txtRemittanceM.Text = Convert.ToString(drdShowDeducteeRecord["REMITTANCE_DESC"]);
                    txtTDSRateM.Text = Convert.ToString(drdShowDeducteeRecord["TDS_APPLICABILITY_DESC"]);
                    txtCountryM.Text = Convert.ToString(drdShowDeducteeRecord["COUNTRY_DESC"]);
                    txtUniqueAcknM.Text = Convert.ToString(drdShowDeducteeRecord["UNIQUE_ACKN"]);
                    //
                    blnShowHelp = true;
                    blnShowPANHelp = true;

                    drdShowDeducteeRecord.Close();
                    drdShowDeducteeRecord.Dispose();

                    return true;
                }
                //-----------------------------------------------------------
                drdShowDeducteeRecord.Close();
                drdShowDeducteeRecord.Dispose();
                //-----------------------------------------------------------
                //cmnService.J_UserMessage(J_Msg.RecNotExist);
                //-----------------------------------------------------------
                //lngChallanID = 0;
                ////-----------------------------------------------------------
                //if (strCheckFields == "")
                //    strSQL = strQuery + "order by " + strOrderBy;
                //else
                //    strSQL = strQuery + strCheckFields + "order by " + strOrderBy;
                ////-----------------------------------------------------------
                //if (dsetChallanGridClone != null) dsetChallanGridClone.Clear();
                //dsetChallanGridClone = dmlService.J_ShowDataInGrid(ref dgcViewDeductee, strSQL, strMatrix);       //Show Data into the Grid
                return true;
            }
            catch (Exception err_handler)
            {
                drdShowDeducteeRecord.Close();
                drdShowDeducteeRecord.Dispose();
                cmnService.J_UserMessage(err_handler.Message);
                return false;
            }
        }
        #endregion

