        #region ValidateFields
        private bool ValidateFields()
        {
            try
            {
                #region Sorting
                if (lblSearchMode.Text == J_Mode.Sorting)
                {
                    //if (Convert.ToInt64(Convert.ToString(ViewGrid.CurrentRowIndex)) < 0)
                    //{
                    //    cmnService.J_UserMessage(J_Msg.DataNotFound);
                    //    if (dsetGridClone == null) return false;
                    //    dmlService.J_setGridPosition(ref ViewGrid, dsetGridClone, "COMPANY_ID", lngSearchId);
                    //    return false;
                    //}
                    return true;
                }
                #endregion
                //
                #region Searching
                else if (lblMode.Text == J_Mode.Searching)
                {
                    // CHALLAN ENTRY
                    //if (dgcViewChallan.Visible == true)
                    if (lblSearchMode.Text == Tabbed_Mode.Challan)
                    {
                        if (grpSearch.Visible == false)
                        {
                            //if (Convert.ToInt64(Convert.ToString(dgvViewChallan.CurrentRow.Index)) < 0)
                            //{
                            //    //cmnService.J_UserMessage(J_Msg.DataNotFound);
                            //    //if (dsetGridClone == null) return false;
                            //    //dmlService.J_setGridPosition(ref ViewGrid, dsetGridClone, "MEMBER_LOAN_ID", lngSearchId);
                            //    return false;
                            //}
                        }
                        else if (grpSearch.Visible == true)
                        {
                            if (dtService.J_IsBlankDateCheck(ref mskDepositDateSearch, J_ShowMessage.NO) == true &&
                                txtSlNoSearch.Text.Trim() == "" &&
                                cmbSectionNoSearch.SelectedIndex <= 0 &&
                                txtChallanNoSearch.Text.Trim() == "" &&
                                txtTransferVoucherNoSearch.Text.Trim() == "")
                            {
                                cmnService.J_UserMessage(J_Msg.SearchingValues);
                                txtSlNoSearch.Select();
                                return false;
                            }
                            if (dtService.J_IsBlankDateCheck(ref mskDepositDateSearch, J_ShowMessage.NO) == false)
                            {
                                if (dtService.J_IsDateValid(mskDepositDateSearch) == false)
                                {
                                    cmnService.J_UserMessage("Enter valid Deposit Date to Search");
                                    mskDepositDateSearch.Select();
                                    return false;
                                }
                            }
                        }
                        return true;
                    }
                    // DEDUCTEE DETAILS
                    //else if (dgcViewChallanDetails.Visible == true)
                    else if (lblSearchMode.Text == Tabbed_Mode.Deductee)
                    {
                        if (grpSearchDeductee.Visible == false)
                        {
                            //if (Convert.ToInt64(Convert.ToString(dgvDeductee.CurrentRow.Index)) < 0)
                            //{
                            //    //cmnService.J_UserMessage(J_Msg.DataNotFound);
                            //    //if (dsetGridClone == null) return false;
                            //    //dmlService.J_setGridPosition(ref ViewGrid, dsetGridClone, "MEMBER_LOAN_ID", lngSearchId);
                            //    return false;
                            //}
                        }
                        else if (grpSearchDeductee.Visible == true)
                        {
                            if (dtService.J_IsBlankDateCheck(ref mskDateSearch, J_ShowMessage.NO) == true &&
                                txtSlNoDSearch.Text.Trim() == "" &&
                                txtPANSearch.Text.Trim() == "" &&
                                txtDeducteeNameSearch.Text.Trim() == "")
                            {
                                cmnService.J_UserMessage(J_Msg.SearchingValues);
                                txtSlNoDSearch.Select();
                                return false;
                            }
                            if (dtService.J_IsBlankDateCheck(ref mskDateSearch, J_ShowMessage.NO) == false)
                            {
                                if (dtService.J_IsDateValid(mskDateSearch) == false)
                                {
                                    cmnService.J_UserMessage("Incorrect Format of the Date to Search");
                                    mskDateSearch.Select();
                                    return false;
                                }
                            }
                        }
                        return true;
                    }
                    return true;
                }
                #endregion
                //
                #region Basic
                else if (lblSearchMode.Text == Tabbed_Mode.Basic)
                {

                    if (cmnService.J_ReturnInt64Value(txtFAYearID.Text.Trim()) < T_FinancialYearID.F2013_14ID)
                    {
                        strSQL = "SELECT COUNT(*) FROM COR_TRN_CHALLAN WHERE SECTION_ID = 0 AND MODE != '' AND BATCH_HEADER_ID = " + lngBatchId + " ";
                        if (dmlService.J_ReturnNoOfRows(strSQL, J_QueryType.DirectQuery) > 0)
                        {
                            cmnService.J_UserMessage("Section Code is missing for some of the challans used for corrections.\nPlease update the same before generating text file.");
                            return false;
                        }
                        //--
                        strSQL = "SELECT COUNT(*) " +
                                 "FROM   COR_TRN_CHALLAN," +
                                 "       COR_TRN_DEDUCTEE_DETAILS " +
                                 "WHERE  COR_TRN_CHALLAN.TRN_CHALLAN_ID                  = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID " +
                                 "AND    COR_TRN_CHALLAN.SECTION_ID = 0 " +
                                 "AND    COR_TRN_DEDUCTEE_DETAILS.PAN_UPDATION_INDICATOR > 0 " +
                                 "AND    COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId + " ";
                        if (dmlService.J_ReturnNoOfRows(strSQL, J_QueryType.DirectQuery) > 0)
                        {
                            cmnService.J_UserMessage("Section Code is missing for some of the challans used for corrections.\nPlease update the same before generating text file.");
                            return false;
                        }
                    }
                    //--
                    return true;
                }
                #endregion
                //
                #region Company
                else if (lblSearchMode.Text == Tabbed_Mode.Company)
                {
                    //-----------------------------------------------------------------------
                    //-- DEDUCTOR/ EMPLOYER/ COLLECTOR NAME
                    //-----------------------------------------------------------------------
                    if (txtCompanyName.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("Company Name - Cannot be Blank");
                        txtCompanyName.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- TAN
                    //-----------------------------------------------------------------------
                    if (txtTANNo.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("TAN No. - Cannot be Blank");
                        txtTANNo.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- TAN FORMAT
                    //-----------------------------------------------------------------------
                    if (txtTANNo.Text.Trim().Length != 10)
                    {
                        cmnService.J_UserMessage("TAN No. should be of 10 characters");
                        txtTANNo.Select();
                        return false;
                    }
                    //---------------------------
                    if (cmnService.J_CheckAlphabetsNumeric(cmnService.J_Left(txtTANNo.Text, 4), J_DataType.Character) == false)
                    {
                        cmnService.J_UserMessage("Incorrect Format of the TAN No.");
                        txtTANNo.Select();
                        return false;
                    }
                    //---------------------------
                    if (cmnService.J_CheckAlphabetsNumeric(cmnService.J_Mid(txtTANNo.Text, 4, 5), J_DataType.Numeric) == false)
                    {
                        cmnService.J_UserMessage("Incorrect Format of the TAN No.");
                        txtTANNo.Select();
                        return false;
                    }
                    //---------------------------
                    if (cmnService.J_CheckAlphabetsNumeric(cmnService.J_Right(txtTANNo.Text, 1), J_DataType.Character) == false)
                    {
                        cmnService.J_UserMessage("Incorrect Format of the TAN No.");
                        txtTANNo.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- TAN
                    //-----------------------------------------------------------------------
                    //strSQL = "SELECT COMPANY_ID " +
                    //    "     FROM   MST_COMPANY " +
                    //    "     WHERE  TAN_NO  ='" + cmnService.J_ReplaceQuote(txtTANNo.Text) + "'";
                    //if (lblMode.Text == J_Mode.Edit)
                    //    strSQL = strSQL + "AND COMPANY_ID <> " + lngSearchId;
                    ////--
                    //if (cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(strSQL)) > 0)
                    //{
                    //    cmnService.J_UserMessage("Company with same [TAN] exists");
                    //    txtTANNo.Select();
                    //    return false;
                    //}

                    //-----------------------------------------------------------------------
                    //-- PAN
                    //-----------------------------------------------------------------------
                    if (txtPANNo.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("PAN No. - Cannot be Blank");
                        txtPANNo.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- PAN FORMAT
                    //-----------------------------------------------------------------------
                    if (txtPANNo.Text.Trim().Length != 10)
                    {
                        cmnService.J_UserMessage("PAN No. should be of 10 characters");
                        txtPANNo.Select();
                        return false;
                    }
                    if (txtPANNo.Text != "PANNOTREQD")
                    {
                        //---------------------------
                        if (cmnService.J_CheckAlphabetsNumeric(cmnService.J_Left(txtPANNo.Text, 5), J_DataType.Character) == false)
                        {
                            cmnService.J_UserMessage("Incorrect Format of the PAN No.!!");
                            txtPANNo.Select();
                            return false;
                        }
                        //---------------------------
                        if (cmnService.J_CheckAlphabetsNumeric(cmnService.J_Mid(txtPANNo.Text, 5, 4), J_DataType.Numeric) == false)
                        {
                            cmnService.J_UserMessage("Incorrect Format of the PAN No.!!");
                            txtPANNo.Select();
                            return false;
                        }
                        //---------------------------
                        if (cmnService.J_CheckAlphabetsNumeric(cmnService.J_Right(txtPANNo.Text, 1), J_DataType.Character) == false)
                        {
                            cmnService.J_UserMessage("Incorrect Format of the PAN No.!!");
                            txtPANNo.Select();
                            return false;
                        }
                    }
                    //-----------------------------------------------------------------------
                    //-- DEDUCTOR TYPE
                    //-----------------------------------------------------------------------
                    if (cmbDeductorType.SelectedIndex <= 0)
                    {
                        cmnService.J_UserMessage("Deductor Type - Cannot be Blank");
                        cmbDeductorType.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- COMPANY PREFIX
                    //-----------------------------------------------------------------------
                    //if (txtCompanyPrefix.Text.Trim() == "")
                    //{
                    //    cmnService.J_UserMessage("Please enter the Company Prefix");
                    //    txtCompanyPrefix.Select();
                    //    return false;
                    //}
                    //-----------------------------------------------------------------------
                    //-- ADDRESS1
                    //-----------------------------------------------------------------------
                    if (txtAddress1.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("Flt/Dr/Blck Number - Cannot be Blank");
                        txtAddress1.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- PIN
                    //-----------------------------------------------------------------------
                    if (txtPIN.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("PIN - Cannot be Blank");
                        txtPIN.Select();
                        return false;
                    }
                    // SIX CHARACTERS
                    if (txtPIN.Text.Trim().Length != 6)
                    {
                        cmnService.J_UserMessage("Incorrect Format of the PIN");
                        txtPIN.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- STATE
                    //-----------------------------------------------------------------------
                    if (cmbState.SelectedIndex <= 0)
                    {
                        cmnService.J_UserMessage("State - Cannot be Blank");
                        cmbState.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- PHONE & STD
                    //-----------------------------------------------------------------------
                    //if (txtSTD.Text.Trim() != "")
                    //    if (txtPhone.Text.Trim() == "")
                    //    {
                    //        cmnService.J_UserMessage("Phone No - Cannot be Blank");
                    //        txtPhone.Select();
                    //        return false;
                    //    }
                    ////------------------
                    //if (txtPhone.Text.Trim() != "")
                    //{
                    //    if (txtSTD.Text.Trim() == "")
                    //    {
                    //        cmnService.J_UserMessage("STD - Cannot be Blank");
                    //        txtSTD.Select();
                    //        return false;
                    //    }
                    //}
                    //// EMAIL
                    //if (txtEmail.Text.Trim() != "" && TdsMan.T_ValidateEmail(txtEmail.Text) == false)
                    //{
                    //    cmnService.J_UserMessage("Incorrect Format of Email");
                    //    txtEmail.Select();
                    //    return false;
                    //}
                    //-----------------------------------------------------------------------
                    //-- RESPONSIBLE PERSON NAME
                    //-----------------------------------------------------------------------
                    if (txtRPName.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("Responsible Person's name - Cannot be Blank");
                        txtRPName.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- DESIGNATION
                    //-----------------------------------------------------------------------
                    if (txtRPDesignation.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("Designation - Cannot be Blank");
                        txtRPDesignation.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- RP ADDRESS1
                    //-----------------------------------------------------------------------
                    if (txtRPAddress1.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("Responsible Person's Flt/Dr/Blck Number - Cannot be Blank");
                        txtRPAddress1.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- RP PIN
                    //-----------------------------------------------------------------------
                    if (txtRPPIN.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("Responsible Person's PIN - Cannot be Blank");
                        txtRPPIN.Select();
                        return false;
                    }
                    // SIX CHARACTERS
                    if (txtRPPIN.Text.Trim().Length != 6)
                    {
                        cmnService.J_UserMessage("Incorrect Format of the Responsible Person's PIN");
                        txtRPPIN.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    //-- RP STATE
                    //-----------------------------------------------------------------------
                    if (cmbRPState.SelectedIndex <= 0)
                    {
                        cmnService.J_UserMessage("Responsible Person's State - Cannot be Blank");
                        cmbRPState.Select();
                        return false;
                    }

                    //-----------------------------------------------------------------------
                    //-- RP_PHONE & RP_STD
                    //-----------------------------------------------------------------------
                    //if (txtRPSTD.Text.Trim() != "")
                    //    if (txtRPPhone.Text.Trim() == "")
                    //    {
                    //        cmnService.J_UserMessage("Responsible Person's Phone No - Cannot be Blank");
                    //        txtRPPhone.Select();
                    //        return false;
                    //    }
                    ////------------------
                    //if (txtRPPhone.Text.Trim() != "")
                    //    if (txtRPSTD.Text.Trim() == "")
                    //    {
                    //        cmnService.J_UserMessage("Responsible Person's STD - Cannot be Blank");
                    //        txtRPSTD.Select();
