                    //-----------------------------------------------------------------
                    //-- FINANCIAL YEAR CHECK FOR PAYMENT DATE WHEN BOOKENTRY CHECKED 
                    //-----------------------------------------------------------------
                    else if (chkBookEntry.Checked == true)
                    {
