                        //-- ANIK @ 2013/09/27 for FVU 4.0
                        if (dtService.J_ConvertToIntYYYYMMDD(mskDateOfPayment.Text) < dtService.J_ConvertToIntYYYYMMDD(TdsMan.T_ReturnStartDateFinancialYear(Convert.ToInt32(txtFAYearID.Text))))
                        {
                            //cmnService.J_UserMessage("Challan Date should not be for previous financial years");
