                    else
                    {
                        //ADDING FINANCIAL YEAR CLAUSE ON 22/03/2012

                        if (cmnService.J_ReturnInt64Value(txtFAYearID.Text.Trim()) >= T_FinancialYearID.F2010_11ID)
                        {
                            //Added by Shrey Kejriwal on 15/11/2011
                            if (Convert.ToDouble(txtTotalTax.Text.Trim()) == 0)
