                                //Commented by Shrey Kejriwal on 01/11/2012

                                ////Added by Shrey Kejriwal on 19/01/2011
                                //if (txtBSRCode.Text.Trim() == "")
                                //{
                                //    cmnService.J_UserMessage("24G Receipt No - Cannot be Blank");
                                //    txtBSRCode.Select();
                                //    return false;
