                            }
                        }
                        else
                        {
                            //Added by Shrey Kejriwal on 22/03/2012

                            //24G RECEIPT NO NOT APPLICABLE FOR F.Y. UPTO 2009-10
                            if (txtBSRCode.Text.Trim() != "")
                            {
                                cmnService.J_UserMessage("24G Receipt No. not applicable for F.Y. " + txtFAYear.Text);
                                txtBSRCode.Select();
