                    //Added by Shrey Kejriwal on 23/11/2012

                    //Date should be within Financial Year
                    if (dtService.J_ConvertToIntYYYYMMDD(mskDeducteeDate.Text) < dtService.J_ConvertToIntYYYYMMDD(TdsMan.T_ReturnStartDateFinancialYear(txtFAYearID.Text)) ||
                                dtService.J_ConvertToIntYYYYMMDD(mskDeducteeDate.Text) > dtService.J_ConvertToIntYYYYMMDD(TdsMan.T_ReturnQuarterEndDate(txtQtr.Text, txtFAYear.Text)))
                    {
                        cmnService.J_UserMessage("Date should be within the Financial Year and before the End Date of Quarter.");
                        mskDeducteeDate.Select();
                        return false;
                    }

                    //if(dtService.J_ConvertToIntYYYYMMDD(mskDeducteeDate.Text) > dtService.J_ConvertToIntYYYYMMDD(TdsMan.T_ReturnQuarterEndDate(txtQtr.Text, txtFAYear.Text)))
                    //{
                    //    cmnService.J_UserMessage("Date should be less than end of the Quarter.");
                    //    mskDeducteeDate.Select();
                    //    return false;
