                    //    {
                    //        if (dtService.J_ConvertToIntYYYYMMDD(mskDeducteeDate.Text) < dtService.J_ConvertToIntYYYYMMDD(TdsMan.T_ReturnQuarterStartDate(txtQtr.Text, txtFAYear.Text)) ||
                    //            dtService.J_ConvertToIntYYYYMMDD(mskDeducteeDate.Text) > dtService.J_ConvertToIntYYYYMMDD(TdsMan.T_ReturnQuarterEndDate(txtQtr.Text, txtFAYear.Text)))
