                        //---------------------------------------------------------------------------
                        if (dtService.J_ConvertToIntYYYYMMDD(mskDeductedDate.Text) < dtService.J_ConvertToIntYYYYMMDD(TdsMan.T_ReturnQuarterStartDate(txtQtr.Text, txtFAYear.Text)))
                        {
