                        //---------------------------------------------------------------------------
                        if (dtService.J_ConvertToIntYYYYMMDD(mskDeductedDate.Text) > dtService.J_ConvertToIntYYYYMMDD(TdsMan.T_ReturnQuarterEndDate(txtQtr.Text, txtFAYear.Text)))
