                    }

                    // Added by Shrey Kejriwal on 23-09-2014
                    // Amount should be less than 99,99,99,999.00 for Form 24Q

                    if (txtFormNo.Text == T_FormNo.F24Q)
                    {
                        if (Convert.ToDouble(cmnService.J_NumericData(txtDeducteeAmountOfPayment)) > 999999999.00)
                        {
                            cmnService.J_UserMessage("Amount value cannot exceed 99,99,99,999.00");
                            txtDeducteeAmountOfPayment.Select();
                            return false;
                        }
                    }

                    //     
                    //if (txtDeductedDateM.Text == "" || ChkGenerateModifyValues(Tabbed_Mode.Deductee) == true)
                    //{
                    //    if (Convert.ToDouble(cmnService.J_NumericData(txtDeducteeAmountOfPayment)) == 0)
