                    //
                    if (txtFormNo.Text == T_FormNo.F24Q)
                    {
                        HigherRate = 3;
                        NoDeduction = 2;
                    }
                    else if (txtFormNo.Text == T_FormNo.F26Q)
                    {
                        HigherRate = 7;
                        Transporter = 8;
                        NoDeduction = 6;
                        SoftwareVendor = 10;
                    }
                    else if (txtFormNo.Text == T_FormNo.F27Q)
                    {
                        HigherRate = 15;
                        //Transporter = 16;
                        NoDeduction = 14;
                        SoftwareVendor = 16;
                    }
                    else if (txtFormNo.Text == T_FormNo.F27EQ)
                    {
                        //HigherRate = 15;
                        //Transporter = 16;
