                            if ((txtDeducteePAN.Text == "PANNOTAVBL" || txtDeducteePAN.Text == "PANAPPLIED" || txtDeducteePAN.Text == "PANINVALID") && Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) != HigherRate)
                            {
