                        //MODIFIED BY SHREY KEJRIWAL ON 17/02/2012
                        if (Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == HigherRate && (txtDeducteePAN.Text != "PANNOTAVBL" && txtDeducteePAN.Text != "PANAPPLIED" && txtDeducteePAN.Text != "PANINVALID"))
                        {
