                            cmnService.J_UserMessage("Higher rate flag not allowed for structurally correct PAN.");
                            cmbRemarks.Select();
                            return false;
                        }
                    //}

                    //HIGHER RATE VALIDATIONS
                    if (cmnService.J_ReturnInt64Value(txtFAYearID.Text) >= T_FinancialYearID.F2010_11ID)
                    {
                        if (txtDeducteeRemarksM.Text.Trim() != "" && cmnService.J_Left(txtDeducteeRemarksM.Text, 1) == "C")
                        {
                            //Added by Shrey on 20/09/2011
                            int intCashBookEntry = 0;
                            if (chkCashBookEntry.Checked == true)
                                intCashBookEntry = 1;

                            //string strNonDeductionFlag = "";
                            //if (rbnLowerNoDeduction.Checked == true)
