                            // ***********************************************************

                            //MODIFIED BY SHREY KEJRIWAL ON 17/02/2012
                            //FOR INVALID PAN ONLY AMOUNT, DATE, AND PAN CAN BE MODIFIED

                            string strHigherRateAlert = "Only PAN, Amount of Payment, and Date of Payment can be changed for Invalid PAN";

                            //CHECK FOR INVALID PAN
                            if (txtDeducteePAN.Text == "PANNOTAVBL" || txtDeducteePAN.Text == "PANAPPLIED" || txtDeducteePAN.Text == "PANINVALID")
                            {
                                //CHECKING IF VALUES OTHER THAN AMOUNT, DATE, PAN ARE MODIFIED
                                if (txtDeducteeName.Text.Trim().ToUpper() != txtDeducteeNameM.Text.Trim().ToUpper())
                                {
                                    cmnService.J_UserMessage(strHigherRateAlert);
                                    txtDeducteeName.Select();
                                    return false;
                                }
                                else if (txtDeducteeRate.Text.Trim() != txtDeducteeRateM.Text.Trim())
                                {
                                    cmnService.J_UserMessage(strHigherRateAlert);
                                    txtDeducteeRate.Select();
                                    return false;
                                }
                                else if (txtDeducteeIncometax.Text.Trim() != txtDeducteeIncometaxM.Text.Trim())
                                {
                                    cmnService.J_UserMessage(strHigherRateAlert);
                                    txtDeducteeIncometax.Select();
                                    return false;
                                }
                                else if (txtDeducteeTotal.Text.Trim() != txtDeducteeTotalM.Text.Trim())
                                {
                                    cmnService.J_UserMessage(strHigherRateAlert);
                                    txtDeducteeIncometax.Select();
                                    return false;
                                }
                                else if (txtDeducteeSurcharge.Text.Trim() != txtDeducteeSurchargeM.Text.Trim())
                                {
                                    cmnService.J_UserMessage(strHigherRateAlert);
                                    txtDeducteeSurcharge.Select();
                                    return false;
                                }
                                else if (txtDeducteeCess.Text.Trim() != txtDeducteeCessM.Text.Trim())
                                {
                                    cmnService.J_UserMessage(strHigherRateAlert);
                                    txtDeducteeCess.Select();
                                    return false;
                                }
                                else if (txtDeducteeTaxDeposited.Text.Trim() != txtDeducteeTaxDepositedM.Text.Trim())
                                {
                                    cmnService.J_UserMessage(strHigherRateAlert);
                                    txtDeducteeTaxDeposited.Select();
                                    return false;
                                }
                                else if (Convert.ToInt32(txtCashBookEntryM.Text) != intCashBookEntry)
                                {
                                    cmnService.J_UserMessage(strHigherRateAlert);
                                    //txtDeducteeRemarks.Select();
                                    return false;
                                }
                                else if (cmbDeducteeCode.Visible == true)
                                {
                                    if (cmnService.J_Left(cmbDeducteeCode.Text, 2) != txtDeducteeCodeM.Text.Trim())
                                    {
                                        cmnService.J_UserMessage(strHigherRateAlert);
                                        cmbDeducteeCode.Select();
                                        return false;
                                    }
                                }
                            }

                            ////HIGHER RATE REMARK CANNOT BE MODIFIED
                            //if (txtDeducteeRemarksM.Text.ToUpper() != strNonDeductionFlag)
                            //{
                            //    cmnService.J_UserMessage("Higher rate remark cannot be modified");
                            //    rbnHigherRate.Checked = true;
                            //    rbnHigherRate.Select();
                            //    return false;
                            //}


                            //Added by Shrey Kejriwal on 16/12/2011
                            if (txtFormNo.Text == T_FormNo.F27Q)
                            {
                                //MODIFIED BY SHREY KEJRIWAL ON 17/02/2012
                                if (txtDeducteePAN.Text == "PANNOTAVBL" || txtDeducteePAN.Text == "PANAPPLIED" || txtDeducteePAN.Text == "PANINVALID")
                                {
                                    if (cmbGrossingUpIndicator.Text != txtToggleTextM.Text)
                                    {
                                        cmnService.J_UserMessage(strHigherRateAlert);
                                        cmbGrossingUpIndicator.Select();
                                        return false;
                                    }
                                }
                            }

                            //Added by Shrey Kejriwal on 16/12/2011
                            if (txtFormNo.Text == T_FormNo.F27EQ)
                            {
                                //MODIFIED BY SHREY KEJRIWAL ON 17/02/2012
                                if (txtDeducteePAN.Text == "PANNOTAVBL" || txtDeducteePAN.Text == "PANAPPLIED" || txtDeducteePAN.Text == "PANINVALID")
                                {
                                    if (txtTotValuePurchase.Text != txtToggleTextM.Text)
                                    {
                                        cmnService.J_UserMessage(strHigherRateAlert);
                                        txtTotValuePurchase.Select();
                                        return false;
                                    }
                                }
                            }
                        }

                    }

                    //if (rbnTransporter.Checked == true)
                    if (Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 8)
                    {
