                    //Added by Shrey Kejriwal on 04/10/2012
                    //if (rbnSoftware.Checked == true)
                    if (Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == SoftwareVendor)
                    {
