                    //-------------------------------------------------------------------------------
                    //ADDED BY DHRUB ON 14/01/2014 
                    //-------------------------------------------------------------------------------
                    //WARNING MESSAGE : IF TAX DEPOSITED AMOUNT IS ZERO AND REMARKS IS NORMAL SELECTED 
                    //-------------------------------------------------------------------------------
                    if (cmbRemarks.SelectedIndex > 0)
                    {
                        #region T_FormNo.F24Q
                        if (txtFormNo.Text == T_FormNo.F24Q)
                        {
                            if (Convert.ToDouble(txtDeducteeTotal.Text) == 0 && Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 4)
                            {
                                if (cmnService.J_UserMessage("Are you sure that there is no 'Remarks' for zero tax deduction?", MessageBoxButtons.YesNo) == DialogResult.No)
                                {
                                    cmbRemarks.Select();
                                    return false;
                                }
                            }
                            //-- ANIK @ 2014-04-26
                            if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2010_11ID)
                            {
                                if (cmbRemarks.Text.Substring(0, 1) == "C")
                                {
                                    if (cmnService.J_ReturnDoubleValue(txtDeducteeTotal.Text) < (20 * cmnService.J_ReturnDoubleValue(txtDeducteeAmountOfPayment.Text)) / 100)
                                    {
                                        if (cmnService.J_UserMessage("TDS deducted is less than 20% of the amount paid for higher rate selection.\nDo you want to continue ?", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.No)
                                        {
                                            txtDeducteeIncometax.Select();
                                            return false;
                                        }
                                        //cmnService.J_UserMessage("TDS deducted should not be less than 20% of the amount paid when higher rate is selected");
                                        //txtDeducteeIncometax.Select();
                                        //return false;
                                    }
                                }
