                        if (txtFormNo.Text == T_FormNo.F27Q)
                        {
                            if (Convert.ToDouble(txtDeducteeTotal.Text) == 0 && Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 17)
                            {
                                if (cmnService.J_UserMessage("Are you sure that there is no 'Remarks' for zero tax deduction?", MessageBoxButtons.YesNo) == DialogResult.No)
                                {
                                    cmbRemarks.Select();
                                    return false;
                                }

                            }
                        }
                        #endregion 

                        #region T_FormNo.F27EQ
                        //---------------------
                        if (txtFormNo.Text == T_FormNo.F27EQ)
                        {
                            if (Convert.ToDouble(txtDeducteeTotal.Text) == 0 && Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 20)
                            {
                                if (cmnService.J_UserMessage("Are you sure that there is no 'Remarks' for zero tax deduction?", MessageBoxButtons.YesNo) == DialogResult.No)
                                {
                                    cmbRemarks.Select();
                                    return false;
                                }

                            }
                        }
                        #endregion 
                    }
                    //-----------------------------------------------------------------------

                    //-----------------------------------------------------------------------
                    //-- TOTAL TAX DEDUCTED 
                    //-----------------------------------------------------------------------

                    // Added by Shrey Kejriwal 
                    // As per FVU 4.4 - Tax Deducted cannot be less than Amount in 24Q.
                    if (txtFormNo.Text == T_FormNo.F24Q)
                    {
                        if (Convert.ToDouble(txtDeducteeTotal.Text) > Convert.ToDouble(txtDeducteeAmountOfPayment.Text))
                        {
                            cmnService.J_UserMessage("Tax Deducted should be less than Amount paid");
                            txtDeducteeIncometax.Select();
                            return false;
                        }
                    }

                    //-----------------------------------------------------------------------
                    //-- TOTAL CHALLAN VALUE & TOTAL DEDUCTEE VALUE
                    //-----------------------------------------------------------------------
                    if (cmnService.J_ReturnDoubleValue(txtDeducteeTaxDeposited.Text) > cmnService.J_ReturnDoubleValue(txtDeducteeTaxDepositedM.Text))
                    {
                        if ((cmnService.J_ReturnDoubleValue(txtViewDeducteeTotalTaxDeposited.Text) +
                            cmnService.J_ReturnDoubleValue(txtDeducteeTaxDeposited.Text) -
                            cmnService.J_ReturnDoubleValue(txtDeducteeTaxDepositedM.Text)) > cmnService.J_ReturnDoubleValue(txtViewChallanDetailsTotalTax.Text))
                        {
                            cmnService.J_UserMessage("Total Deductee deposit can never be more than the Challan deposit");
                            txtDeducteeTaxDeposited.Select();
                            return false;
                        }
                    }
                    //----------------------------------------------------------
                    //-- DEDUCTED DATE
                    //----------------------------------------------------------

                    if (Convert.ToDouble(txtDeducteeTotal.Text) != 0)
                    {
                        //ADDED BY SHREY KEJRIWAL ON 26/03/2012

                        //BLANK CHECK
                        if (dtService.J_IsBlankDateCheck(ref mskDeductedDate, J_ShowMessage.NO))
                        {
                            cmnService.J_UserMessage("Date of Deduction cannot be blank");
                            mskDeductedDate.Select();
                            return false;
                        }

                        //VALID DATE CHECK
                        if (dtService.J_ConvertToIntYYYYMMDD(mskDeductedDate) < dtService.J_ConvertToIntYYYYMMDD(TdsMan.T_ReturnStartDateFinancialYear(txtFAYear.Text)))
                        {
                            cmnService.J_UserMessage("Deducted date cannot be before the Financial Year : " + txtFAYear.Text);
                            mskDeductedDate.Select();
                            return false;
                        }
                    }
                    //--
                    if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2013_14ID)
                    {
                        //-- CERTIFICATE
                        if (txtCertificateNo.Text.Trim() == "")
                        {
                            strSQL = "SELECT CERTIFICATE_REQD FROM MST_REASON WHERE REASON_ID = " + Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex));
                            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) == "1")
                            {
                                cmnService.J_UserMessage("Certificate No. mandatory for Remarks : '" + cmbRemarks.Text + "'");
                                txtCertificateNo.Select();
                                return false;
                            }
                        }
                        else
                        {
                            // Added by Shrey Kejriwal on 23/09/2014
                            // Valid Structure check if value is present
                            string strErrMessage = "";

                            if (TdsMan.Certificate197Check(txtCertificateNo.Text, out strErrMessage) == false)
                            {
                                cmnService.J_UserMessage(strErrMessage);
                                txtCertificateNo.Select();
                                return false;
                            }
                        }


                        if (grp27Q.Visible == true)
                        {
                            //-- COUNTRY - 2013/08/19
                            if (cmbCountry.SelectedIndex <= 0)
                            {
                                cmnService.J_UserMessage("Country of Residence cannot be blank");
                                cmbCountry.Select();
                                return false;
                            }
                        }
                    }
                    //-- 2014/09/03 WARNING FOR SHORT DEDUCTIONS
                    #region WARNING FOR SHORT DEDUCTIONS
                    if (txtFormNo.Text != T_FormNo.F24Q)
                    {
                        bool blShortDeductions = false;
                        string strSection = ""; double dblNonSalaryTDS = 0;
                        //
                        if (cmbDDSection.Visible == true)
                            strSection = cmbDDSection.Text;
                        else
                            strSection = txtViewChallanDetailsSection.Text;
                        //
                        if (TdsMan.CalcTDSRateForNonSalary(strSection, mskDeducteeDate.Text, txtDeducteePAN.Text) == 0)
                            TDSMAN.Classes.TDSMAN.T_NonSalaryTDSRate = 0;
                        //-- 2014/09/02
                        #region COMMENT
                        //                        strActualAmtCreation = @"IIF(" + strTableName + "." + strFieldPAN + " = 'PANNOTAVBL' " +
                        //                                               @"OR " + strTableName + "." + strFieldPAN + " = 'PANAPPLIED' " +
                        //                                               @"OR " + strTableName + "." + strFieldPAN + " = 'PANINVALID', " +
                        //                                               @"ROUND((TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.INVALID_PAN_RATE ) / 100,0), 
                        //                                                IIF(MID(" + strTableName + "." + strFieldPAN + ", 4, 1) = 'P' OR MID(" + strTableName + "." + strFieldPAN + ", 4, 1) = 'H', " +
                        //                                                           @"ROUND((TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.NON_COMPANY_RATE ) / 100,0), 
                        //                                                ROUND((TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT * MST_NONSALARY_TAX_SLAB.COMPANY_RATE ) / 100,0)))";
                        //                        strSQL = @"SELECT COUNT(*) 
                        //                                   FROM   TRN_DEDUCTEE_DETAILS, 
                        //                                          " + strTableName + "," +
                        //                                         @"MST_NONSALARY_TAX_SLAB 
                        //                                   WHERE  TRN_DEDUCTEE_DETAILS.PARTY_ID    = " + strTableName + "." + strFieldId + " " +
                        //                                 @"AND    TRN_DEDUCTEE_DETAILS.SECTION_ID = MST_NONSALARY_TAX_SLAB.SECTION_ID  
                        //                                   AND    TRN_DEDUCTEE_DETAILS.PAYMENT_DATE BETWEEN MST_NONSALARY_TAX_SLAB.FROM_DATE AND MST_NONSALARY_TAX_SLAB.TO_DATE
                        //                                   AND    TRN_DEDUCTEE_DETAILS.BASIC_INFO_ID = " + BasicInfoID + " " +
                        //                                 @"AND    TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT < " + strActualAmtCreation + " " +
                        //                                 @"AND    TRN_DEDUCTEE_DETAILS.REASON_ID IN (3,7,15,4,12,17,20)";
                        #endregion
                        //
                        if (Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 3
                            || Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 4
                            || Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 7
                            || Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 15
                            || Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 12
                            || Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 17
                            || Convert.ToInt32(Support.GetItemData(cmbRemarks, cmbRemarks.SelectedIndex)) == 20)
                        {
                            dblNonSalaryTDS = Math.Round((TDSMAN.Classes.TDSMAN.T_NonSalaryTDSRate / 100 * cmnService.J_ReturnDoubleValue(txtDeducteeAmountOfPayment.Text)), MidpointRounding.AwayFromZero);
                            if (txtDeducteePAN.Text == "PANNOTAVBL")
                            {
                                // GET RATE (INVALID_PAN_RATE) FROM MST_NONSALARY_TAX_SLAB
                                if (dblNonSalaryTDS > cmnService.J_ReturnDoubleValue(txtDeducteeTaxDeposited.Text))
                                    blShortDeductions = true;
                            }
                            else if (cmnService.J_Mid(txtDeducteePAN.Text, 4, 1) == "P"
                                || cmnService.J_Mid(txtDeducteePAN.Text, 4, 1) == "H")
                            {
                                // GET RATE (NON_COMPANY_RATE) FROM MST_NONSALARY_TAX_SLAB
                                if (dblNonSalaryTDS > cmnService.J_ReturnDoubleValue(txtDeducteeTaxDeposited.Text))
                                    blShortDeductions = true;

                            }
                            else
                            {
                                // GET RATE (COMPANY_RATE) FROM MST_NONSALARY_TAX_SLAB
                                //dblRate=cmnService.J_ReturnDoubleValue(dmlService.J_ExecSqlReturnScalar("SELECT COMPANY_RATE FROM MST_NONSALARY_TAX_SLAB WHERE SECTION_ID =" + lngSectionID) );
                                if (dblNonSalaryTDS > cmnService.J_ReturnDoubleValue(txtDeducteeTaxDeposited.Text))
                                    blShortDeductions = true;
                            }
                        }
                        //--
                        if (blShortDeductions == true)
                        {
                            if (cmnService.J_UserMessage("Please Note :\n\nTDS Rate\t\t: " + TDSMAN.Classes.TDSMAN.T_NonSalaryTDSRate + "%\nTDS\t\t: " + TDSMAN.Classes.TDSMAN.T_NonSalaryTDSRate + "% on " + txtDeducteeAmountOfPayment.Text + " = " + string.Format("{0:0.00}", dblNonSalaryTDS) + " \nTDS Entered\t: " + txtDeducteeTaxDeposited.Text + "\nShort Deduction\t: " + string.Format("{0:0.00}", (dblNonSalaryTDS - cmnService.J_ReturnDoubleValue(txtDeducteeTaxDeposited.Text))) + "\n\nAre you sure you want to continue ?", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button2) == DialogResult.No)
                            {
                                return false;
                            }
                        }

                    }
                    #endregion 
                    //
                    return true;
                }
                #endregion
                //
                #region GenerateTDS
                else if (lblSearchMode.Text == Tabbed_Mode.GenerateTDS)
                {
                    //-----------------------------------------------------------------------
                    //-- Total Challan
                    //-----------------------------------------------------------------------
                    if (cmnService.J_ReturnDoubleValue(txtTotalChallanRecords.Text) == 0)
                    {
                        cmnService.J_UserMessage("Total number of Challan should be at least 1");
                        BtnCancel.Select();
                        return false;
                    }

                    // AUTOMATIC CSI FILE DOWNLOAD
                    if (chkCSIFileDownload.Checked == true)
                    {
                        //-----------------------------------------------------------------------
                        //-- DATE
                        //-----------------------------------------------------------------------
                        if (dtService.J_IsBlankDateCheck(ref mskViewCSIFileDownloadFrom, "CSI File Download From Date - Cannot be Blank") == true)
                        {
                            mskViewCSIFileDownloadFrom.Select();
                            return false;
                        }
                        //-----------------------------------------------------------------------
                        if (dtService.J_IsBlankDateCheck(ref mskViewCSIFileDownloadTo, "CSI File Download To Date - Cannot be Blank") == true)
                        {
                            mskViewCSIFileDownloadTo.Select();
                            return false;
                        }
                        //----------------------------------------------------------
                        //-- VALID DATE CHECK
                        //----------------------------------------------------------
                        if (dtService.J_IsDateValid(mskViewCSIFileDownloadFrom) == false)
                        {
                            cmnService.J_UserMessage("Incorrect Format of the CSI File Download From Date");
                            mskViewCSIFileDownloadFrom.Select();
                            return false;
                        }
                        //----------------------------------------------------------
                        if (dtService.J_IsDateValid(mskViewCSIFileDownloadTo) == false)
                        {
                            cmnService.J_UserMessage("Incorrect Format of the CSI File Download To Date");
                            mskViewCSIFileDownloadTo.Select();
                            return false;
                        }

                        // FROM DATE STARTING FROM 2005
                        if (dtService.J_ConvertToIntYYYYMMDD(mskViewCSIFileDownloadFrom.Text) < 20050101)
                        {
                            cmnService.J_UserMessage("CSI File Download Date [From Date should not be less than 01/01/2005]!!");
                            mskViewCSIFileDownloadFrom.Select();
                            return false;
                        }
                        // FROM DATE & TO DATE STARTING FROM 2005
                        if (dtService.J_ConvertToIntYYYYMMDD(mskViewCSIFileDownloadTo.Text) < 20050101)
                        {
                            cmnService.J_UserMessage("CSI File Download Date [To Date should not be less than 01/01/2005]!!");
                            mskViewCSIFileDownloadTo.Select();
                            return false;
                        }

                        // FROM DATE GREATER THAN TO DATE
                        if (dtService.J_ConvertToIntYYYYMMDD(mskViewCSIFileDownloadFrom.Text) > dtService.J_ConvertToIntYYYYMMDD(mskViewCSIFileDownloadTo.Text))
                        {
                            cmnService.J_UserMessage("CSI File Download Date [From Date should not be greater than To Date]!!");
                            chkCSIFileDownload.Checked = false;
                            chkCSIFileDownload.Select();
                            return false;
                        }

                        // FROM DATE & TO DATE DURATION 15 MONTHS
                        if (TdsMan.T_DateDiff(T_DATE_DIFF.MONTH, dtService.J_ConvertddMMyyyy(mskViewCSIFileDownloadFrom), dtService.J_ConvertddMMyyyy(mskViewCSIFileDownloadTo)) > 24)
                        {
                            cmnService.J_UserMessage("Period selected should be within 24 months");
                            mskViewCSIFileDownloadFrom.Select();
                            return false;
                        }
                    }
                    //-----------------------------------------------------------------------
                    //-- FVU PATH
                    //-----------------------------------------------------------------------
                    //if (txtViewFVUPath.Text.Trim() == "")
                    //{
                    //    cmnService.J_UserMessage("FVU Path can never be blank");
                    //    btnFVUPathModify.Select();
                    //    return false;
                    //}
                    //-----------------------------------------------------------------------
                    //if ( this.J_IsProcessOpen(txtViewFVUPath.Text) == true)
                    //{
                    //    MessageBox.Show("Application is running.\nPlease close the application");
                    //    btnFVUPathModify.Select();
                    //    return false;
                    //}
                    ////-----------------------------------------------------------------------
                    //if (File.Exists(txtViewFVUPath.Text) == false)
                    //{
                    //    MessageBox.Show("Selected file does not exist");
                    //    btnFVUPathModify.Select();
                    //    return false;
                    //}
                    //-----------------------------------------------------------------------
                    //-- INPUT FILE PATH
                    //-----------------------------------------------------------------------
                    if (txtTextFilePath.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("Input File Path can never be blank");
                        BtnSort.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    if (TdsMan.J_IsProcessOpen(txtTextFilePath.Text) == true)
                    {
                        MessageBox.Show("Application is running.\nPlease close the application");
                        BtnSort.Select();
                        return false;
                    }
                    //-----------------------------------------------------------------------
                    if (File.Exists(txtTextFilePath.Text) == false)
                    {
                        MessageBox.Show("The file does not exist");
                        BtnSort.Select();
                        return false;
                    }
                    return true;
                }
                #endregion
                //
                #region ImportFromExcel
                else if (lblSearchMode.Text == Tabbed_Mode.ImportFromExcel)
                {
                    //-----------------------------------------------------------------------
                    //-- FVU FILE SELECTED
                    //-----------------------------------------------------------------------
                    if (txtExcelPath.Text.Trim() == "")
                    {
                        cmnService.J_UserMessage("Excel file not selected");
                        btnSelectExcelPath.Select();
                        return false;
                    }
                    // FILE SHOULD BE FVU
                    if (Path.GetExtension(txtExcelPath.Text).ToUpper() != ".XLS" && Path.GetExtension(txtExcelPath.Text).ToUpper() != ".XLSX")
                    {
                        cmnService.J_UserMessage("Selected file should be an Excel file");
                        btnSelectExcelPath.Select();
                        return false;
                    }
                    // FILE EXIST
                    if (cmnService.J_IsFileExist(txtExcelPath.Text) == false)
                    {
                        cmnService.J_UserMessage("Selected Excel file not found");
                        btnSelectExcelPath.Select();
                        return false;
                    }

                    // FILE OPEN
                    //-- ANIK 2011-09-09
                    string strPath = txtExcelPath.Text.ToString();
                    //if (cmnService.J_IsProcessOpen(txtExcelPath.Text) == true)
                    if (TdsMan.T_isFileOpenOrReadOnly(ref strPath) == true)
                    {
                        cmnService.J_UserMessage("Selected Excel file is open");
                        btnSelectExcelPath.Select();
                        return false;
                    }
                    return true;
                }
                #endregion
                //
                return true;
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
                return false;
            }
        }
        #endregion

        #region Insert_Update_Delete_Data
        private void Insert_Update_Delete_Data()
        {
            try
            {
                //--------------------------------------------
                //string strNonDeductionFlag = "";
                string strDEDUCTED_DATE = "";
                double dblSumValues = 0;
                int intBookEntry = 0;
                int intCashBookEntry = 0;
                int intChangeAddress = 0;
                int intRPChangeAddress = 0;
                string strImportFlagMode = "";
                string strDeducteeCode = "";
                string strGrossingUpIndicator = "";
                int intMinorID = 0;
                int intSectionID = 0;
                //--------------------------------------------
                switch (lblMode.Text)
                {
