            {
                if (cmbDeductorType.Text.Substring(0, 1) == "A" || cmbDeductorType.Text.Substring(0, 1) == "S")
                    strChallanGridColumn = "Challan/Trf Vch No.";
                else
                    strChallanGridColumn = "Challan No.";
            }
            else
                strChallanGridColumn = "Challan No.";
            //--
            string strSectionSize = "0";
            string strSectionVisibility = "";
            if (cmnService.J_ReturnInt32Value(txtFAYearID.Text) >= T_FinancialYearID.F2013_14ID)
            {
                strSectionSize = "0";
                strSectionVisibility = "F";
            }
            else
                strSectionSize = "55";
            //--
            string[,] strMatrixChallanDetails = {{"ChallanID", "0", "", "Right", "", "F", ""},
                                        {"Sl", "32", "", "", "", "", ""},
                                        {"NSDL Status", "72", "S", "", "", "", ""},
