            //Condition to show Total Tax based on Book entry value
            string[,] strLoadChallanTotTaxMatrix = {{"COR_TRN_CHALLAN.BOOK_ENTRY =  1", "F", "COR_TRN_CHALLAN.TOT_TAX - COR_TRN_CHALLAN.INTEREST_ALLOCATED - COR_TRN_CHALLAN.OTHERS_ALLOCATED", "F"},
                                                    {"COR_TRN_CHALLAN.BOOK_ENTRY <> 1", "F", "COR_TRN_CHALLAN.TOT_TAX - COR_TRN_CHALLAN.INTEREST_ALLOCATED - COR_TRN_CHALLAN.OTHERS_ALLOCATED - COR_TRN_CHALLAN.LATE_FEE", "F"}};

            
            //
            string[,] strLoadChallanUpdationIndicator = {{"COR_TRN_CHALLAN.CHALLAN_UPDATION_INDICATOR = 1", "F", "Upd", "T"},
                                                         {"COR_TRN_CHALLAN.CHALLAN_UPDATION_INDICATOR = 2", "F", "Add", "T"},
                                                         {"COR_TRN_CHALLAN.CHALLAN_UPDATION_INDICATOR = 0", "F", "", "T"}};
            //--
            //Added by Shrey Kejriwal on 09/08/2011
            string[,] strLoadChallanStatusIndicator = {{"COR_TRN_CHALLAN.CHALLAN_STATUS = 'M'", "F", "Matched", "T"},
                                            {"COR_TRN_CHALLAN.CHALLAN_STATUS = 'U'", "F", "Unmatched", "T"},
                                            {"COR_TRN_CHALLAN.CHALLAN_STATUS = 'O'", "F", "Overbooked", "T"},
                                            {"COR_TRN_CHALLAN.CHALLAN_STATUS = 'P'", "F", "Prov. Matched", "T"},
                                            {"COR_TRN_CHALLAN.CHALLAN_STATUS = ''", "F", "", "T"}};

            //{"COR_TRN_CHALLAN.MODE = 'C2'", "F", "", "T"}

            string[,] strLoadChallanDeducteeChanges = {{"COR_TRN_CHALLAN.MODE = 'C3'", "F", "Yes", "T"},
                                            {cmnService.J_SQLDBFormat("DEDUCTEE_CHANGES.PAN_CHANGES", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + " > 0", "F", "Yes", "T"},
                                            {"COR_TRN_CHALLAN.MODE = 'C2'", "F", "", "T"},
                                            {"COR_TRN_CHALLAN.MODE = 'C9'", "F", "", "T"},
                                            {"COR_TRN_CHALLAN.MODE = ''", "F", "", "T"}};

            string[,] strLoadHeaderChallanGridMatrix = {{"COR_HDR_CHALLAN.BOOK_ENTRY = 1", "F", "COR_HDR_CHALLAN.TRANSFER_VOUCHER_NO", "F"},
                                                        {"COR_HDR_CHALLAN.BOOK_ENTRY <> 1", "F", "COR_HDR_CHALLAN.CHALLAN_NO", "F"}};

            //--
            strOrderBy = "COR_TRN_CHALLAN.TRN_CHALLAN_ID";

            #region Commented

            /*Modified by Shrey Kejriwal on 16/08/2011
             * Earlier challan table was inner joined with Deductee table
             * which was modified to left join */
            //strQuery = "SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID     AS TRN_CHALLAN_ID," +
            //          "       COR_TRN_CHALLAN.SL_NO               AS SL_NO," +
            //          "       " + cmnService.J_SQLDBFormat(strLoadChallanStatusIndicator, J_SQLColFormat.Case_End) + " AS CHALLAN_STATUS, " +
            //          "       " + cmnService.J_SQLDBFormat(strLoadChallanUpdationIndicator, J_SQLColFormat.Case_End) + " AS MODE," +
            //          "       MST_SECTION.SECTION_NO              AS SECTION_NO," +
            //          "       " + cmnService.J_SQLDBFormat(strLoadChallanGridMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_TRF_NO," +
            //          "       COR_TRN_CHALLAN.DEPOSIT_DATE        AS DEPOSIT_DATE," +
            //          "      (COR_TRN_CHALLAN.TOT_TAX - " +
            //          "       COR_TRN_CHALLAN.INTEREST_ALLOCATED - " +
            //          "       COR_TRN_CHALLAN.OTHERS_ALLOCATED)   AS TOT_TAX," +
            //          "       COR_TRN_CHALLAN.CTRL_TOT_TAX        AS DEDUCTEE_TOTAL," +
            //          "     ((COR_TRN_CHALLAN.TOT_TAX - " +
            //          "       COR_TRN_CHALLAN.INTEREST_ALLOCATED - " +
            //          "       COR_TRN_CHALLAN.OTHERS_ALLOCATED) - COR_TRN_CHALLAN.CTRL_TOT_TAX) as DIFF, " +
            //          "       " + cmnService.J_SQLDBFormat(strLoadChallanDeducteeChanges, J_SQLColFormat.Case_End) + " AS DEDUCTEE_CHANGES " +
            //          "FROM   ((COR_TRN_CHALLAN " +
            //          "LEFT  JOIN  COR_TRN_DEDUCTEE_DETAILS" +
            //          "        ON  COR_TRN_CHALLAN.TRN_CHALLAN_ID  = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID) " +
            //          "INNER JOIN       MST_SECTION " +
            //          "        ON  COR_TRN_CHALLAN.SECTION_ID      = MST_SECTION.SECTION_ID) " +
            //          "WHERE  COR_TRN_CHALLAN.BATCH_HEADER_ID = " + BatchID + " ";

            ////--
            //strGroupBy = "GROUP BY COR_TRN_CHALLAN.TRN_CHALLAN_ID," +
            //          "            COR_TRN_CHALLAN.SL_NO," +
            //          "            " + cmnService.J_SQLDBFormat(strLoadChallanStatusIndicator, J_SQLColFormat.Case_End) + " , " +
            //          "            " + cmnService.J_SQLDBFormat(strLoadChallanUpdationIndicator, J_SQLColFormat.Case_End) + " ," +
            //          "            MST_SECTION.SECTION_NO," +
            //          "            " + cmnService.J_SQLDBFormat(strLoadChallanGridMatrix, J_SQLColFormat.Case_End) + "," +
            //          "            COR_TRN_CHALLAN.DEPOSIT_DATE," +
            //          "           (COR_TRN_CHALLAN.TOT_TAX - " +
            //          "            COR_TRN_CHALLAN.INTEREST_ALLOCATED - " +
            //          "            COR_TRN_CHALLAN.OTHERS_ALLOCATED)," +
            //          "            COR_TRN_CHALLAN.CTRL_TOT_TAX," +
            //          "          ((COR_TRN_CHALLAN.TOT_TAX - " +
            //          "            COR_TRN_CHALLAN.INTEREST_ALLOCATED - " +
            //          "            COR_TRN_CHALLAN.OTHERS_ALLOCATED) - COR_TRN_CHALLAN.CTRL_TOT_TAX), " +
            //          "            COR_TRN_CHALLAN.MODE ";
            #endregion

            strQuery = "SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID     AS TRN_CHALLAN_ID," +
                      "       COR_TRN_CHALLAN.SL_NO               AS SL_NO," +
                      "       " + cmnService.J_SQLDBFormat(strLoadChallanStatusIndicator, J_SQLColFormat.Case_End) + "   AS CHALLAN_STATUS, " +
                      "       " + cmnService.J_SQLDBFormat(strLoadChallanUpdationIndicator, J_SQLColFormat.Case_End) + " AS MODE," +
                      "       MST_SECTION.SECTION_NO              AS SECTION_NO," +
                      "       " + cmnService.J_SQLDBFormat(strLoadChallanGridMatrix, J_SQLColFormat.Case_End) + "        AS CHALLAN_TRF_NO," +
                      "       COR_TRN_CHALLAN.DEPOSIT_DATE        AS DEPOSIT_DATE," +
                      //"       (COR_TRN_CHALLAN.TOT_TAX - " +
                      //"        COR_TRN_CHALLAN.INTEREST_ALLOCATED - " +
                      //"        COR_TRN_CHALLAN.OTHERS_ALLOCATED)   AS TOT_TAX," +
                      "       " + cmnService.J_SQLDBFormat(strLoadChallanTotTaxMatrix, J_SQLColFormat.Case_End) + "      AS TOT_TAX," +
                      "        COR_TRN_CHALLAN.CTRL_TOT_TAX        AS DEDUCTEE_TOTAL," +
                      //"       ((COR_TRN_CHALLAN.TOT_TAX - " +
                      //"         COR_TRN_CHALLAN.INTEREST_ALLOCATED - " +
                      //"         COR_TRN_CHALLAN.OTHERS_ALLOCATED) - COR_TRN_CHALLAN.CTRL_TOT_TAX) AS DIFF, " +
                      "       " + cmnService.J_SQLDBFormat(strLoadChallanTotTaxMatrix, J_SQLColFormat.Case_End) + "- COR_TRN_CHALLAN.CTRL_TOT_TAX AS DIFF," +
                      "       " + cmnService.J_SQLDBFormat("CHALLAN_HEADER.SECTION_NO", J_ColumnType.String, J_SQLColFormat.NullCheck) + "        AS HDR_SECTION_NO, " +
                      "       " + cmnService.J_SQLDBFormat("CHALLAN_HEADER.CHALLAN_TRF_NO", J_ColumnType.String, J_SQLColFormat.NullCheck) + "    AS HDR_CHALLAN_TRF_NO, " +
                      "       CHALLAN_HEADER.DEPOSIT_DATE         AS HDR_DEPOSIT_DATE, " +
                      "       " + cmnService.J_SQLDBFormat("CHALLAN_HEADER.TOT_TAX", J_ColumnType.Double, J_SQLColFormat.NullCheck) + "           AS HDR_TOT_TAX, " +
                      "       " + cmnService.J_SQLDBFormat(strLoadChallanDeducteeChanges, J_SQLColFormat.Case_End) + "                            AS DEDUCTEE_CHANGES " +
                      "FROM    (((COR_TRN_CHALLAN " +
                      "LEFT JOIN       MST_SECTION " +
                      "        ON COR_TRN_CHALLAN.SECTION_ID      = MST_SECTION.SECTION_ID) " +
                      "LEFT JOIN  (SELECT HDR_CHALLAN_ID, " +
                      "                   MST_SECTION.SECTION_NO AS SECTION_NO, " +
                      "                   DEPOSIT_DATE, " +
                      "                   BSR_CODE, " +
                      "                   " + cmnService.J_SQLDBFormat(strLoadHeaderChallanGridMatrix, J_SQLColFormat.Case_End) + " AS CHALLAN_TRF_NO," +
                      "                   (COR_HDR_CHALLAN.TOT_TAX - " +
                      "                    COR_HDR_CHALLAN.INTEREST_ALLOCATED - " +
                      "                    COR_HDR_CHALLAN.OTHERS_ALLOCATED)   AS TOT_TAX " +
                      "            FROM   (COR_HDR_CHALLAN " +
                      "            LEFT JOIN MST_SECTION " +
                      "            ON    COR_HDR_CHALLAN.SECTION_ID  = MST_SECTION.SECTION_ID)) AS CHALLAN_HEADER " +
                      "        ON  COR_TRN_CHALLAN.HDR_CHALLAN_ID = CHALLAN_HEADER.HDR_CHALLAN_ID) " +
                      "LEFT  JOIN (SELECT TRN_CHALLAN_ID, " +
                      "                   SUM(PAN_UPDATION_INDICATOR) AS PAN_CHANGES " +
                      "            FROM COR_TRN_DEDUCTEE_DETAILS " +
                      "            GROUP BY TRN_CHALLAN_ID) AS DEDUCTEE_CHANGES " +
                      "        ON COR_TRN_CHALLAN.TRN_CHALLAN_ID = DEDUCTEE_CHANGES.TRN_CHALLAN_ID) " +
                      "WHERE  COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId + " ";

            //-----------------------------------------------------------
            //strSQL = strQuery + strGroupBy + "ORDER BY " + strOrderBy;
            strSQL = strQuery + "ORDER BY " + strOrderBy;

            //-----------------------------------------------------------
            if (dsetGridClone != null) dsetGridClone.Clear();
            dsetGridClone = dmlService.J_ShowDataInGrid(dmlService.J_pCommand, ref dgvViewChallan, strSQL, strMatrixChallanDetails);     //Show Data into the Grid


            dgvViewChallan.ClearSelection();
        }

