        #region GenerateTextFile
        private bool GenerateTextFile(string strInputFilePath)
        {
            if (ValidateFields() == false) return false;
            //ADDED BY SHREY KEJRIWAL ON 11/04/2012

            //CHECKING IF THE LATEST FILE IS USED FOR THE GENERATION
            if (TdsMan.T_CheckInternetConnectivty() == true)
            {
                try
                {
                    //declaring the object
                    NSDLAccount objnsdlAcc = new NSDLAccount();
                    IDataReader reader;
                    string strTan = string.Empty;
                    string strOrigianlReceiptNo = string.Empty;
                    string strPrevReceiptNo = string.Empty;

                    strSQL = "SELECT COR_HDR_BATCH.ORIGINAL_RRR_NO  AS ORIGINAL_RRR_NO," +
                             "       COR_HDR_BATCH.PREVIOUS_RRR_NO  AS PREVIOUS_RRR_NO," +
                             "       COR_HDR_COMPANY.TAN_NO         AS TAN_NO " +
                             "FROM   COR_HDR_BATCH, " +
                             "       COR_HDR_COMPANY " +
                             "WHERE  COR_HDR_BATCH.BATCH_HEADER_ID  = COR_HDR_COMPANY.BATCH_HEADER_ID " +
                             "AND    COR_HDR_BATCH.BATCH_HEADER_ID  = " + lngBatchId;

                    reader = dmlService.J_ExecSqlReturnReader(strSQL);

                    while (reader.Read())
                    {
                        strTan = reader["TAN_NO"].ToString();
                        strOrigianlReceiptNo = reader["ORIGINAL_RRR_NO"].ToString();
                        strPrevReceiptNo = reader["PREVIOUS_RRR_NO"].ToString();
                    }

                    reader.Dispose();
                    reader.Close();

                    //-- COMMENTED 2013/04/16 AS PER DISCUSSION
                    //-- OPENED 2013/04/29 AS PER DISCUSSION
                    //string strExpectedPrevReceiptNo = objnsdlAcc.get_Status_TDS_TCS_Statement(strOrigianlReceiptNo, strTan);

                    bool blnCheckLatestReturn = objnsdlAcc.get_Status_TDS_TCS_Statement(strPrevReceiptNo, strTan);
                    //if (objnsdlAcc.get_Status_TDS_TCS_Statement(strOrigianlReceiptNo, strTan, strPrevReceiptNo) == false)
                    if (blnCheckLatestReturn == false)
                    {
                        cmnService.J_UserMessage("The Consolidated Statement file used for correction return was not the latest file of that return.\n" +
                                                 "For filling the Correction Return only the latest Consolidated statement can be used (As per NSDL)\n\n" +
                                                 "For further assistance, call our Helpdesk at 033 - 2262 3535");
                        return false;
                    }
                }
                catch
                {
                    //if exception occurs continue with generation process
                }
            }


            //-------------------------------
            string strFVUVersion = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT FVU_VERSION FROM MST_ASSESSMENT WHERE ASST_ID = "
                                                    + Convert.ToInt32(txtFAYearID.Text)));
            //
            string strRPMobileNo = "";
            if (cmnService.J_ReturnDoubleValue(strFVUVersion) >= cmnService.J_ReturnDoubleValue(T_FVU_Version.FVU_3_0))
                strRPMobileNo = txtRPMobileNo.Text;
            //-------------------------------
            StreamWriter StreamWriter = null;

            int intPageNumber = 0;
            string strFileSequenceNo = "1";

            string strChangeAddress = "";
            string strPChangeAddress = "";

            IDataReader drdGenChallan = null;
            IDataReader drdGenDeductee = null;
            IDataReader drdBatch = null;

            long lngChallanRowCount = 0;

            string strGenTotalNoDeducteeForChallan = "";
            long lngGenChallanID = 0;
            string strNilChallanIndiactor = "";
            string strChallanDate = "";
            string strLastChallanDate = "";
            string strPaymentDate = "";
            string strDeductedDate = "";
            string strBookEntry = "N";
            string strChequeNo = "N";
            double dblTotalTax = 0;
            long lngNoOfBatchesC1 = 0;
            long lngNoOfBatchesC2 = 0;
            long lngNoOfBatchesC3 = 0;
            long lngNoOfBatchesC5 = 0;
            long lngNoOfBatchesC4 = 0;
            long lngNoOfBatchesC9 = 0;
            long lngNoOfBatches = 0;
            int intBatchNo = 0;
            string strFromDate = "";
            string strToDate = "";
            //
            string strFileType = "";
            string strDeducteeCode = "";
            string strDDChallanDate = "";
            string strDDRate = "";
            string strCountSDRecords = "";
            string strGrossTotalIncome = "";
            string strTotValPur = "";

            string strFileHashValue = "";

            string strFEE = "";
            string strSectionNo = "";
            string strCertificateNo = "";
            //
            try
            {
                //
                if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2012_13ID)
                    strFEE = "0.00";
                //if (ValidateFields() == false) return false;
                // 
                //
                if (txtFormNo.Text.Trim() == T_FormNo.F24Q)
                    strFileType = "SL1";
                else if (txtFormNo.Text.Trim() == T_FormNo.F26Q)
                    strFileType = "NS1";
                else if (txtFormNo.Text.Trim() == T_FormNo.F27Q)
                    strFileType = "NS1";
                else if (txtFormNo.Text.Trim() == T_FormNo.F27EQ)
                    strFileType = "TC1";

                // *******************************************************************************
                // **** ADDED BY SHREY KEJRIWAL ON 20/01/2012
                // **** NEW ADDITION FOR FVU 3.3 AND FVU 2.131
                // **** CHECKING FILE HASH VALUE AND IMPUT FILE PATH
                // *******************************************************************************

                //Added by Shrey Kejriwal on 19/01/2012
                strFileHashValue = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT HASH_VALUE FROM COR_HDR_BATCH WHERE BATCH_HEADER_ID = " + lngBatchId));

                strConsolidatedStatementPath = dmlService.J_ExecSqlReturnScalar("SELECT TDS_FILE_PATH FROM COR_HDR_BATCH WHERE BATCH_HEADER_ID = " + lngBatchId).ToString();

                if (strConsolidatedStatementPath != "")
                {
                    if (File.Exists(strConsolidatedStatementPath) == false)
