                    if (TDSMAN.Classes.TDSMAN.T_pHashValue == "") return false;

                    strFileHashValue = TDSMAN.Classes.TDSMAN.T_pHashValue;

                }

                StreamWriter = cmnService.J_ReturnStreamWriter(strInputFilePath);


                // WRITE LINE
                if (Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT MODE FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + lngBatchId)) == T_CorrectionMode.TANUpdation)
                {
                    intPageNumber = intPageNumber + 1;
                    // FILE HEADER
                    cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) + TdsMan.T_WriteField("FH") + TdsMan.T_WriteField(strFileType) +
