                                                TdsMan.T_WriteField("BH") +
                                                TdsMan.T_WriteField("1") +
                                                TdsMan.T_WriteBlankField(1, "^") +
                                                TdsMan.T_WriteField(drdBatch["FORM_NO"].ToString()) +
                                                TdsMan.T_WriteField(T_CorrectionMode.TANUpdation) +
                                                TdsMan.T_WriteBlankField(1, "^") +
                                                TdsMan.T_WriteField(drdBatch["ORIGINAL_RRR_NO"].ToString()) +
                                                TdsMan.T_WriteField(drdBatch["PREVIOUS_RRR_NO"].ToString()) +
                                                TdsMan.T_WriteBlankField(2, "^") +
                                                TdsMan.T_WriteField(drdBatch["COMPANY_TAN"].ToString()) +
                                                TdsMan.T_WriteField(drdBatch["COMPANY_TAN"].ToString()) +
                                                TdsMan.T_WriteBlankField(2, "^") +
                                                TdsMan.T_WriteField(cmnService.J_Left(drdBatch["ASST_YR"].ToString(), 4) + cmnService.J_Right(drdBatch["ASST_YR"].ToString(), 2)) +
                                                TdsMan.T_WriteField(cmnService.J_Left(drdBatch["FA_YEAR"].ToString(), 4) + cmnService.J_Right(drdBatch["FA_YEAR"].ToString(), 2)) +
                                                TdsMan.T_WriteField(drdBatch["PERIOD"].ToString()) +
                                                TdsMan.T_WriteField(drdBatch["COMPANY_NAME"].ToString()) +
