                                           TdsMan.T_WriteField(strFileSequenceNo) + TdsMan.T_WriteField("D") + TdsMan.T_WriteField(txtTAN.Text) +
                                           TdsMan.T_WriteField(Convert.ToString(lngNoOfBatches)) + TdsMan.T_WriteField("TDS-MAN") + TdsMan.T_WriteBlankField(7, "^") + strFileHashValue);

                    #endregion

                    #region BATCH HEADER
                    // BATCH HEADER
                    string[,] strCompanyAddressChange = {{"COR_TRN_COMPANY.ADDRESS_CHANGE = 0", "F", "N", "T"},
