                            "       COR_TRN_COMPANY.PAO_CODE                 AS PAO_CODE," +
                            "       COR_TRN_COMPANY.DDO_CODE                 AS DDO_CODE," +
                            "       MST_MINISTRY.MINISTRY_CODE               AS MINISTRY_CODE," +
                            "       COR_TRN_COMPANY.MINISTRY_OTHER           AS OTHER_MINISTRY," +
                            "       COR_TRN_COMPANY.PAO_REG_NO               AS PAO_REG_NO," +
                            "       COR_TRN_COMPANY.DDO_REG_NO               AS DDO_REG_NO " +
                            "FROM   (((((((((COR_TRN_COMPANY LEFT JOIN MST_CATEGORY " +
                            "       ON COR_TRN_COMPANY.D_CATEGORY_ID = MST_CATEGORY.CATEGORY_ID) " +
                            "INNER JOIN COR_HDR_COMPANY " +
                            "       ON COR_HDR_COMPANY.HDR_COMPANY_ID= COR_TRN_COMPANY.HDR_COMPANY_ID) " +
                            "LEFT JOIN MST_CATEGORY AS H_MST_CATEGORY " +
                            "       ON H_MST_CATEGORY.CATEGORY_ID= COR_HDR_COMPANY.D_CATEGORY_ID) " +
                            "INNER JOIN COR_HDR_BATCH " +
                            "       ON COR_HDR_BATCH.BATCH_HEADER_ID = COR_HDR_COMPANY.BATCH_HEADER_ID) " +
                            "INNER JOIN MST_ASSESSMENT " +
