                            "LEFT JOIN  MST_MINISTRY " +
                            "       ON COR_TRN_COMPANY.MINISTRY_ID   = MST_MINISTRY.MINISTRY_ID) " +
                            "WHERE  COR_TRN_COMPANY.BATCH_HEADER_ID   = " + lngBatchId + " ";

                    drdBatch = dmlService.J_ExecSqlReturnReader(strSQL);
