                        strBHArray[lngArrayCounter, (int)enmCompanyIndex.C_CATEGORY] = drdBatch["C_CATEGORY"].ToString();
                        strBHArray[lngArrayCounter, (int)enmCompanyIndex.PERSON_NAME] = drdBatch["PERSON_NAME"].ToString();
