                        strBHArray[lngArrayCounter, (int)enmCompanyIndex.P_ADDRESS1] = drdBatch["P_ADDRESS1"].ToString();
                        strBHArray[lngArrayCounter, (int)enmCompanyIndex.P_ADDRESS2] = drdBatch["P_ADDRESS2"].ToString();
                        strBHArray[lngArrayCounter, (int)enmCompanyIndex.P_ADDRESS3] = drdBatch["P_ADDRESS3"].ToString();
                        strBHArray[lngArrayCounter, (int)enmCompanyIndex.P_ADDRESS4] = drdBatch["P_ADDRESS4"].ToString();
                        strBHArray[lngArrayCounter, (int)enmCompanyIndex.P_ADDRESS5] = drdBatch["P_ADDRESS5"].ToString();
                        strBHArray[lngArrayCounter, (int)enmCompanyIndex.P_STATE] = drdBatch["P_STATE"].ToString();
                        strBHArray[lngArrayCounter, (int)enmCompanyIndex.P_PIN_CODE] = drdBatch["P_PIN_CODE"].ToString();
