                            intBatchNo = intBatchNo + 1;
                            //
                            cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                            TdsMan.T_WriteField("BH") +
                                            TdsMan.T_WriteField(intBatchNo.ToString()) +
                                            TdsMan.T_WriteField(strCOUNT_CHALLAN_RECORDS) +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FORM_NO]) +
                                            TdsMan.T_WriteField(T_CorrectionMode.C5) +
                                            TdsMan.T_WriteBlankField(1, "^") +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ORIGINAL_RRR_NO]) +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PREVIOUS_RRR_NO]) +
                                            TdsMan.T_WriteBlankField(2, "^") +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.COMPANY_TAN]) +
                                            TdsMan.T_WriteBlankField(3, "^") +
                                            TdsMan.T_WriteField(cmnService.J_Left(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ASST_YR], 4) + cmnService.J_Right(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ASST_YR], 2)) +
                                            TdsMan.T_WriteField(cmnService.J_Left(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FA_YEAR], 4) + cmnService.J_Right(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FA_YEAR], 2)) +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PERIOD]) +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.COMPANY_NAME]) +
                                            TdsMan.T_WriteBlankField(12, "^") +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.C_CATEGORY]) +
                                            TdsMan.T_WriteBlankField(16, "^") +
                                            TdsMan.T_WriteField(Convert.ToString(strCountSDRecords)) +
                                            TdsMan.T_WriteBlankField(1, "^") +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.AO_APPROVAL]) +
                                            TdsMan.T_WriteBlankField(10, "^") +
                                //-- ANIK 2013/07/09
                                            TdsMan.T_WriteBlankField(7, "^"));

                            lngChallanRowCount = Convert.ToInt64(strCOUNT_CHALLAN_RECORDS);


                            strCDArray = new string[lngChallanRowCount, 32];
                            //
                            //strSQL = "SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID      AS TRN_CHALLAN_ID," +
                            //         "       COR_TRN_CHALLAN.SL_NO               AS CHALLAN_DETAIL_RECORD_NO," +
                            //         "       COR_HDR_CHALLAN.CHALLAN_NO          AS LAST_CHALLAN_NO," +
                            //         "       COR_TRN_CHALLAN.CHALLAN_NO          AS NEW_CHALLAN_NO," +
                            //         "       COR_HDR_CHALLAN.TRANSFER_VOUCHER_NO AS LAST_TRANSFER_VOUCHER_NO," +
                            //         "       COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO AS TRANSFER_VOUCHER_NO," +
                            //         "       COR_HDR_CHALLAN.BSR_CODE            AS LAST_BSR_CODE," +
                            //         "       COR_TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                            //         "      " + cmnService.J_SQLDBFormat("COR_HDR_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "  AS LAST_DATE_OF_DEPOSIT," +
                            //         "      " + cmnService.J_SQLDBFormat("COR_TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "  AS DEPOSIT_DATE," +
                            //         "       MST_SECTION.SECTION_NAME            AS SECTION_NAME," +
                            //         "       COR_TRN_CHALLAN.CHEQUE_NO           AS CHEQUE_NO," +
                            //         "       COR_TRN_CHALLAN.TDS                 AS INCOME_TAX," +
                            //         "       COR_TRN_CHALLAN.SURCHARGE           AS SURCHARGE," +
                            //         "       COR_TRN_CHALLAN.EDUCATION_CESS      AS EDUCATION_CESS," +
                            //         "       COR_TRN_CHALLAN.INTEREST            AS INTEREST," +
                            //         "       COR_TRN_CHALLAN.OTHERS              AS OTHERS," +
                            //         "       COR_TRN_CHALLAN.TOT_TAX             AS TOT_TAX," +
                            //         "       COR_HDR_CHALLAN.TOT_TAX             AS LAST_TOT_TAX," +
                            //         "       COR_TRN_CHALLAN.INTEREST_ALLOCATED  AS INTEREST_ALLOCATED," +
                            //         "       COR_TRN_CHALLAN.OTHERS_ALLOCATED    AS OTHERS_ALLOCATED," +
                            //         "       COR_TRN_CHALLAN.BOOK_ENTRY          AS BOOK_ENTRY," +
                            //         "       COR_TRN_CHALLAN.REMARKS             AS REMARKS," +
                            //         "       COR_TRN_CHALLAN.CHALLAN_UPDATION_INDICATOR AS CHALLAN_UPDATION_INDICATOR " +
                            //         "FROM   COR_HDR_BATCH," +
                            //         "       COR_TRN_CHALLAN," +
                            //         "       COR_HDR_CHALLAN," +
                            //         "       MST_SECTION " +
                            //         "WHERE  COR_HDR_BATCH.BATCH_HEADER_ID  = COR_HDR_CHALLAN.BATCH_HEADER_ID " +
                            //         "AND    COR_HDR_CHALLAN.HDR_CHALLAN_ID = COR_TRN_CHALLAN.HDR_CHALLAN_ID " +
                            //         "AND    COR_TRN_CHALLAN.SECTION_ID     = MST_SECTION.SECTION_ID " +
                            //         "AND    COR_TRN_CHALLAN.TRN_CHALLAN_ID IN (SELECT DISTINCT TRN_CHALLAN_ID " +
                            //         "                                         FROM   COR_TRN_DEDUCTEE_DETAILS  " +
                            //         "                                         WHERE  PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " " +
                            //         "                                         AND    BATCH_HEADER_ID        = " + lngBatchId + ") " +
                            //    //"AND    COR_HDR_BATCH.BATCH_HEADER_ID  = " + lngBatchId + " " +
                            //         "ORDER BY COR_TRN_CHALLAN.SL_NO";

                            strSQL = "SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID      AS TRN_CHALLAN_ID," +
                                     "       COR_TRN_CHALLAN.SL_NO               AS CHALLAN_DETAIL_RECORD_NO," +
                                     "       COR_HDR_CHALLAN.CHALLAN_NO          AS LAST_CHALLAN_NO," +
                                     "       COR_TRN_CHALLAN.CHALLAN_NO          AS NEW_CHALLAN_NO," +
                                     "       COR_HDR_CHALLAN.TRANSFER_VOUCHER_NO AS LAST_TRANSFER_VOUCHER_NO," +
                                     "       COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO AS TRANSFER_VOUCHER_NO," +
                                     "       COR_HDR_CHALLAN.BSR_CODE            AS LAST_BSR_CODE," +
                                     "       COR_TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                                     "      " + cmnService.J_SQLDBFormat("COR_HDR_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "  AS LAST_DATE_OF_DEPOSIT," +
                                     "      " + cmnService.J_SQLDBFormat("COR_TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "  AS DEPOSIT_DATE," +
                                     "       MST_SECTION.SECTION_NAME            AS SECTION_NAME," +
                                     "       COR_TRN_CHALLAN.CHEQUE_NO           AS CHEQUE_NO," +
                                     "       COR_TRN_CHALLAN.TDS                 AS INCOME_TAX," +
                                     "       COR_TRN_CHALLAN.SURCHARGE           AS SURCHARGE," +
                                     "       COR_TRN_CHALLAN.EDUCATION_CESS      AS EDUCATION_CESS," +
                                     "       COR_TRN_CHALLAN.INTEREST            AS INTEREST," +
                                     "       COR_TRN_CHALLAN.OTHERS              AS OTHERS," +
                                     "       COR_TRN_CHALLAN.TOT_TAX             AS TOT_TAX," +
                                     "       COR_HDR_CHALLAN.TOT_TAX             AS LAST_TOT_TAX," +
                                     "       COR_TRN_CHALLAN.INTEREST_ALLOCATED  AS INTEREST_ALLOCATED," +
                                     "       COR_TRN_CHALLAN.OTHERS_ALLOCATED    AS OTHERS_ALLOCATED," +
                                     "       COR_TRN_CHALLAN.BOOK_ENTRY          AS BOOK_ENTRY," +
                                     "       COR_TRN_CHALLAN.REMARKS             AS REMARKS," +
                                     "       COR_TRN_CHALLAN.CHALLAN_UPDATION_INDICATOR AS CHALLAN_UPDATION_INDICATOR," +
                                     "       COR_TRN_CHALLAN.LATE_FEE            AS LATE_FEE," +
                                     "       MST_MINOR_HEAD.MINOR_HEAD_CODE      AS MINOR_HEAD_CODE " +
                                     "FROM   (((((COR_HDR_BATCH " +
                                     "INNER JOIN COR_HDR_CHALLAN " +
                                     "        ON COR_HDR_BATCH.BATCH_HEADER_ID  = COR_HDR_CHALLAN.BATCH_HEADER_ID) " +
                                     "INNER JOIN COR_TRN_CHALLAN " +
                                     "        ON COR_HDR_CHALLAN.HDR_CHALLAN_ID  = COR_TRN_CHALLAN.HDR_CHALLAN_ID) " +
                                     "LEFT JOIN MST_SECTION " +
                                     "        ON COR_TRN_CHALLAN.SECTION_ID  = MST_SECTION.SECTION_ID) " +
                                     "INNER JOIN (SELECT TRN_CHALLAN_ID," +
                                     "                   SUM(PAN_UPDATION_INDICATOR) AS SUM_PAN_UPDATION_INDICATOR " +
                                     "            FROM COR_TRN_DEDUCTEE_DETAILS " +
                                     "            GROUP BY TRN_CHALLAN_ID) AS DEDUCTEE_DETAILS " +
                                     "       ON  COR_TRN_CHALLAN.TRN_CHALLAN_ID = DEDUCTEE_DETAILS.TRN_CHALLAN_ID) " +
                                     "LEFT JOIN MST_MINOR_HEAD " +
                                     "        ON COR_TRN_CHALLAN.MINOR_HEAD_ID  = MST_MINOR_HEAD.MINOR_HEAD_ID) " +
                                     "WHERE DEDUCTEE_DETAILS.SUM_PAN_UPDATION_INDICATOR > 0 " +
                                     "AND   COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId + " " +
                                     "ORDER BY COR_TRN_CHALLAN.SL_NO";

                            drdGenChallan = dmlService.J_ExecSqlReturnReader(strSQL);
                            if (drdGenChallan == null)
                                return false;
                            //--
                            lngArrayCounter = 0;

                            while (drdGenChallan.Read())
                            {
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.TRN_CHALLAN_ID] = drdGenChallan["TRN_CHALLAN_ID"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO] = drdGenChallan["CHALLAN_DETAIL_RECORD_NO"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_CHALLAN_NO] = drdGenChallan["LAST_CHALLAN_NO"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.NEW_CHALLAN_NO] = drdGenChallan["NEW_CHALLAN_NO"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_TRANSFER_VOUCHER_NO] = drdGenChallan["LAST_TRANSFER_VOUCHER_NO"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.TRANSFER_VOUCHER_NO] = drdGenChallan["TRANSFER_VOUCHER_NO"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_BSR_CODE] = drdGenChallan["LAST_BSR_CODE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.BSR_CODE] = drdGenChallan["BSR_CODE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_DATE_OF_DEPOSIT] = drdGenChallan["LAST_DATE_OF_DEPOSIT"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.DEPOSIT_DATE] = drdGenChallan["DEPOSIT_DATE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.SECTION_NAME] = drdGenChallan["SECTION_NAME"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CHEQUE_NO] = drdGenChallan["CHEQUE_NO"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.INCOME_TAX] = drdGenChallan["INCOME_TAX"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.SURCHARGE] = drdGenChallan["SURCHARGE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.EDUCATION_CESS] = drdGenChallan["EDUCATION_CESS"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.INTEREST] = drdGenChallan["INTEREST"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.OTHERS] = drdGenChallan["OTHERS"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.TOT_TAX] = drdGenChallan["TOT_TAX"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_TOT_TAX] = drdGenChallan["LAST_TOT_TAX"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.INTEREST_ALLOCATED] = drdGenChallan["INTEREST_ALLOCATED"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.OTHERS_ALLOCATED] = drdGenChallan["OTHERS_ALLOCATED"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.BOOK_ENTRY] = drdGenChallan["BOOK_ENTRY"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.REMARKS] = drdGenChallan["REMARKS"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CHALLAN_UPDATION_INDICATOR] = drdGenChallan["CHALLAN_UPDATION_INDICATOR"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LATE_FEE] = drdGenChallan["LATE_FEE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.MINOR_HEAD_CODE] = drdGenChallan["MINOR_HEAD_CODE"].ToString();

                                lngArrayCounter++;
                            }
                            drdGenChallan.Close();

                            if (lngArrayCounter > 0)
                            {
                                //-------------------------------------------------------------------------
                                for (long lngCounter = 0; lngCounter <= lngArrayCounter - 1; lngCounter++)
                                {
                                    //------------------------------------------------
                                    intPageNumber = intPageNumber + 1;

                                    //-- INITIALIZE
                                    strBookEntry = "";
                                    strChequeNo = "";
                                    strNilChallanIndiactor = "";
                                    strGenTotalNoDeducteeForChallan = "";
                                    strChallanDate = "";
                                    dblTotalTax = 0;
                                    lngGenChallanID = 0;
                                    //--

                                    lngGenChallanID = cmnService.J_ReturnInt32Value(strCDArray[lngCounter, (int)enmCHALLANIndex.TRN_CHALLAN_ID]);

                                    strGenTotalNoDeducteeForChallan = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(HDR_DEDUCTEE_DETAIL_ID) AS COUNT_DEDUCTEE_DETAIL_ID FROM COR_TRN_DEDUCTEE_DETAILS WHERE TRN_CHALLAN_ID = " + lngGenChallanID));

                                    // NIL CHALLAN INDICATOR
                                    dblTotalTax = cmnService.J_ReturnDoubleValue(strCDArray[lngCounter, (int)enmCHALLANIndex.TOT_TAX]);

                                    if (dblTotalTax == 0)
                                    {
                                        strNilChallanIndiactor = "Y";
                                        strLastChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(TdsMan.T_ReturnQuarterEndDate(txtQtr.Text, txtFAYear.Text));
                                        strChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(TdsMan.T_ReturnQuarterEndDate(txtQtr.Text, txtFAYear.Text));
                                        strChequeNo = "";
                                    }
                                    else
                                    {
                                        strNilChallanIndiactor = "N";
                                        strLastChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_DATE_OF_DEPOSIT]);
                                        strChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(strCDArray[lngCounter, (int)enmCHALLANIndex.DEPOSIT_DATE]);
                                        strChequeNo = strCDArray[lngCounter, (int)enmCHALLANIndex.CHEQUE_NO];
                                        if (strChequeNo == "")
                                            strChequeNo = "0";
                                    }

                                    // BOOK ENTRY
                                    if (strCDArray[lngCounter, (int)enmCHALLANIndex.TRANSFER_VOUCHER_NO].Trim() != "")
                                    {
                                        strBookEntry = "Y";
                                        strChequeNo = "";
                                    }
                                    else
                                        strBookEntry = "N";

                                    //if (txtCategory.Text.Substring(0, 1) == "A" || txtCategory.Text.Substring(0, 1) == "S")
                                    if (strBHArray[intCompanyCounter, (int)enmCompanyIndex.C_CATEGORY].Substring(0, 1) == "A" ||
                                        strBHArray[intCompanyCounter, (int)enmCompanyIndex.C_CATEGORY].Substring(0, 1) == "S")
                                        if (cmnService.J_ReturnDoubleValue(strCDArray[lngCounter, (int)enmCHALLANIndex.TOT_TAX]) > 0)
                                            if (strCDArray[lngCounter, (int)enmCHALLANIndex.TRANSFER_VOUCHER_NO].Trim() == "" &&
                                                strCDArray[lngCounter, (int)enmCHALLANIndex.BSR_CODE].Trim() == "" &&
                                                strCDArray[lngCounter, (int)enmCHALLANIndex.NEW_CHALLAN_NO].Trim() == "")
                                                strBookEntry = "Y";

                                    if (strBookEntry == "Y")
                                        strChequeNo = "";
                                    //
                                    //-- FOR PREVIOUS 2010-11
                                    if (cmnService.J_ReturnInt64Value(txtFAYearID.Text) < T_FinancialYearID.F2010_11ID)
                                        strBookEntry = "";
                                    //
                                    strSQL = "SELECT COUNT(*) AS DEDUCTEE_DETAIL_ROW_COUNT " +
                                        "     FROM   COR_TRN_DEDUCTEE_DETAILS " +
                                        "     WHERE  BATCH_HEADER_ID        = " + lngBatchId + " " +
                                        "     AND    PAN_UPDATION_INDICATOR = " + T_UPDATION_INDICATOR.ON + " " +
                                        "     AND    TRN_CHALLAN_ID         = " + strCDArray[lngCounter, (int)enmCHALLANIndex.TRN_CHALLAN_ID];

                                    string strCountPartyRecords = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                                    //                                
                                    cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                        TdsMan.T_WriteField("CD") +
                                        TdsMan.T_WriteField(intBatchNo.ToString()) +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO]) +
                                        TdsMan.T_WriteField(strCountPartyRecords) +
                                        TdsMan.T_WriteField(strNilChallanIndiactor) +
                                        TdsMan.T_WriteBlankField(4, "^") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_CHALLAN_NO]) +
                                        TdsMan.T_WriteBlankField(1, "^") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_TRANSFER_VOUCHER_NO]) +
                                        TdsMan.T_WriteBlankField(1, "^") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_BSR_CODE]) +
                                        TdsMan.T_WriteBlankField(1, "^") +
                                        TdsMan.T_WriteField(strLastChallanDate) +
                                        TdsMan.T_WriteBlankField(10, "^") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_TOT_TAX], "0.00") +
                                        TdsMan.T_WriteBlankField(8, "^") +
                                        TdsMan.T_WriteField(strBookEntry) +
                                        TdsMan.T_WriteBlankField(1, "^") +
                                        //-- ANIK 2013/07/09
                                        TdsMan.T_WriteBlankField(2, "^"));

                                    // DEDUCTEE DETAIL
                                    string[,] strGenerateTextFile = {{"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL'", "F", "C", "T"},
                                                                 {"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN <> 'PANNOTAVBL'", "F", "COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG", "F"}};

                                    strSQL = "SELECT COR_TRN_CHALLAN.SL_NO                          AS CHALLAN_SL_NO," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.SL_NO                 AS DEDUCTEE_SL_NO," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.MODE                  AS MODE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_CODE         AS DEDUCTEE_CODE," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.DEDUCTEE_PAN          AS LAST_DEDUCTEE_PAN," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN          AS DEDUCTEE_PAN," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.DEDUCTEE_PAN_REF      AS LAST_AND_CURRENT_PAN_REF," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME         AS DEDUCTEE_NAME," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TAX_AMOUNT            AS TAX_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.SURCHARGE_AMOUNT      AS SURCHARGE_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.CESS_AMOUNT           AS CESS_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT          AS TOTAL_AMOUNT," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.TOTAL_AMOUNT          AS LAST_TOTAL_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT  AS TAX_DEPOSITED_AMOUNT," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT  AS LAST_TAX_DEPOSITED_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TOT_VALUE_PURCHASE    AS TOT_VALUE_PURCHASE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT        AS PAYMENT_AMOUNT," +
                                             "      " + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "  AS PAYMENT_DATE," +
                                             "      " + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " AS DEDUCTED_DATE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.RATE                  AS RATE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.GROSSING_UP_INDICATOR AS GROSSING_UP_INDICATOR," +
                                             "       COR_TRN_CHALLAN.BOOK_ENTRY                     AS BOOK_ENTRY," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY       AS CASH_BOOK_ENTRY,";

                                    if (cmnService.J_ReturnDoubleValue(strFVUVersion) >= cmnService.J_ReturnDoubleValue(T_FVU_Version.FVU_3_0))
                                        strSQL = strSQL + cmnService.J_SQLDBFormat(strGenerateTextFile, J_SQLColFormat.Case_End) + " AS NON_DEDUCTION_FLAG ";
                                    else
                                        strSQL = strSQL + "COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG AS NON_DEDUCTION_FLAG ";

                                    strSQL = strSQL + "FROM (((COR_TRN_CHALLAN INNER JOIN COR_HDR_BATCH " +
                                        "    ON COR_HDR_BATCH.BATCH_HEADER_ID           = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                                        "INNER JOIN   COR_TRN_DEDUCTEE_DETAILS " +
                                        "    ON COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID = COR_TRN_CHALLAN.TRN_CHALLAN_ID) " +
                                        "LEFT JOIN    COR_HDR_DEDUCTEE_DETAILS " +
                                        "    ON COR_HDR_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID  = COR_TRN_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID) " +
                                        "WHERE   COR_TRN_CHALLAN.TRN_CHALLAN_ID                  =  " + strCDArray[lngCounter, (int)enmCHALLANIndex.TRN_CHALLAN_ID] + " " +
                                        "AND     COR_HDR_BATCH.BATCH_HEADER_ID                   = " + lngBatchId + " " +
