                            //                            
                            strSQL = "SELECT SUM(TOT_TAX) AS CHALLAN_TOTAL_DEPOSIT " +
                                     "FROM   COR_TRN_CHALLAN " +
                                     "WHERE  MODE            = '" + T_CorrectionMode.C3 + "'  " +
                                     "AND    BATCH_HEADER_ID = " + lngBatchId + " ";
                            string strCHALLAN_TOTAL_DEPOSIT = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                            //
