                                                TdsMan.T_WriteField(cmnService.J_Left(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FA_YEAR], 4) + cmnService.J_Right(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FA_YEAR], 2)) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PERIOD]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.COMPANY_NAME]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.BRANCH_DIV]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ADDRESS1]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ADDRESS2]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ADDRESS3]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ADDRESS4]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ADDRESS5]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.C_STATE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PIN_CODE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.EMAIL]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.STD]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PHONE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ADDRESS_CHANGE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.C_CATEGORY]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PERSON_NAME]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.DESIGNATION]) +
