                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.P_PIN_CODE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.P_EMAIL]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.P_MOBILE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.P_STD]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.P_PHONE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.P_ADDRESS_CHANGE]) +
                                                TdsMan.T_WriteField(strCHALLAN_TOTAL_DEPOSIT, "0.00") +
                                                TdsMan.T_WriteBlankField(3, "^") +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.AO_APPROVAL]) +
                                                TdsMan.T_WriteBlankField(1, "^") +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.L_CATEGORY]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.D_STATE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PAO_CODE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.DDO_CODE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.MINISTRY_CODE]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.OTHER_MINISTRY]) +
                                                TdsMan.T_WriteBlankField(1, "^") +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PAO_REG_NO]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.DDO_REG_NO]) +
                                    //-- ANIK 2013/07/09
                                                TdsMan.T_WriteBlankField(7, "^"));
                            }
                            else
                            {
                                cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                                TdsMan.T_WriteField("BH") +
                                                TdsMan.T_WriteField(intBatchNo.ToString()) +
                                                TdsMan.T_WriteField(strCOUNT_CHALLAN_RECORDS) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FORM_NO]) +
