                                     "       COR_TRN_CHALLAN.LATE_FEE            AS LATE_FEE," +
                                     "       MST_MINOR_HEAD.MINOR_HEAD_CODE      AS MINOR_HEAD_CODE " +
                                     "FROM   ((((COR_HDR_BATCH " +
                                     "INNER JOIN COR_HDR_CHALLAN " +
                                     "        ON COR_HDR_BATCH.BATCH_HEADER_ID  = COR_HDR_CHALLAN.BATCH_HEADER_ID) " +
                                     "INNER JOIN COR_TRN_CHALLAN " +
                                     "        ON COR_HDR_CHALLAN.HDR_CHALLAN_ID  = COR_TRN_CHALLAN.HDR_CHALLAN_ID) " +
                                     "LEFT JOIN MST_SECTION " +
                                     "        ON COR_TRN_CHALLAN.SECTION_ID  = MST_SECTION.SECTION_ID) " +
                                     "LEFT JOIN MST_MINOR_HEAD " +
                                     "        ON COR_TRN_CHALLAN.MINOR_HEAD_ID  = MST_MINOR_HEAD.MINOR_HEAD_ID) " +
