                                            strFEE = string.Format("{0:0.00}", Convert.ToDouble(strCDArray[lngCounter, (int)enmCHALLANIndex.LATE_FEE].Trim() == "" ? "0" : strCDArray[lngCounter, (int)enmCHALLANIndex.LATE_FEE].Trim()));
                                        else
                                            strFEE = "";
                                        //
                                        cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                            TdsMan.T_WriteField("CD") +
                                            TdsMan.T_WriteField(intBatchNo.ToString()) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO]) +
                                            TdsMan.T_WriteField(strCountPartyRecords) +
                                            TdsMan.T_WriteField(strNilChallanIndiactor) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_UPDATION_INDICATOR]) +
                                            TdsMan.T_WriteBlankField(3, "^") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_CHALLAN_NO]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.NEW_CHALLAN_NO]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_TRANSFER_VOUCHER_NO]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.TRANSFER_VOUCHER_NO]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_BSR_CODE]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.BSR_CODE]) +
                                            TdsMan.T_WriteField(strLastChallanDate) +
                                            TdsMan.T_WriteField(strChallanDate) +
                                            TdsMan.T_WriteBlankField(2, "^") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.SECTION_NAME]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.INCOME_TAX], "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.SURCHARGE], "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.EDUCATION_CESS], "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.INTEREST], "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.OTHERS], "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.TOT_TAX], "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_TOT_TAX], "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblTaxDepositedA + dblTaxDepositedU) - dblTaxDepositedD), "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblIncomeTaxA + dblIncomeTaxU) - dblIncomeTaxD), "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblSurchargeA + dblSurchargeU) - dblSurchargeD), "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblCessA + dblCessU) - dblCessD), "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblTotalAmountA + dblTotalAmountU) - dblTotalAmountD), "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.INTEREST_ALLOCATED], "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.OTHERS_ALLOCATED], "0.00") +
                                            TdsMan.T_WriteField(strChequeNo) +
                                            TdsMan.T_WriteField(strBookEntry) +
                                            TdsMan.T_WriteBlankField(1, "^") +
                                            //-- ANIK 2013/07/09
                                            TdsMan.T_WriteField(strFEE) + // FEE
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.MINOR_HEAD_CODE]));
                                    }
                                    else
                                    {

                                        //Added by Shrey Kejriwal

                                        //Changes as per FVU 4.1
                                        if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2012_13ID)
                                            strFEE = string.Format("{0:0.00}", Convert.ToDouble(strCDArray[lngCounter, (int)enmCHALLANIndex.LATE_FEE].Trim() == "" ? "0" : strCDArray[lngCounter, (int)enmCHALLANIndex.LATE_FEE].Trim()));
                                        else
                                            strFEE = "";


                                        string Section = strCDArray[lngCounter, (int)enmCHALLANIndex.SECTION_NAME];
                                        if (cmnService.J_ReturnInt64Value(txtFAYearID.Text) < T_FinancialYearID.F2010_11ID)
                                            Section = "";
                                        //
                                        cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                            TdsMan.T_WriteField("CD") +
                                            TdsMan.T_WriteField(intBatchNo.ToString()) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO]) +
                                            TdsMan.T_WriteField(strCountPartyRecords) +
                                            TdsMan.T_WriteField(strNilChallanIndiactor) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_UPDATION_INDICATOR]) +
                                            TdsMan.T_WriteBlankField(3, "^") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_CHALLAN_NO]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_CHALLAN_NO]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_TRANSFER_VOUCHER_NO]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_TRANSFER_VOUCHER_NO]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_BSR_CODE]) +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_BSR_CODE]) +
                                            TdsMan.T_WriteField(strLastChallanDate) +
                                            TdsMan.T_WriteField(strLastChallanDate) +
                                            TdsMan.T_WriteBlankField(2, "^") +
                                            TdsMan.T_WriteField(Section) +
                                            TdsMan.T_WriteBlankField(5, "^") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_TOT_TAX], "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_TOT_TAX], "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblTaxDepositedA + dblTaxDepositedU) - dblTaxDepositedD), "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblIncomeTaxA + dblIncomeTaxU) - dblIncomeTaxD), "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblSurchargeA + dblSurchargeU) - dblSurchargeD), "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblCessA + dblCessU) - dblCessD), "0.00") +
                                            TdsMan.T_WriteField(Convert.ToString((dblTotalAmountA + dblTotalAmountU) - dblTotalAmountD), "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.INTEREST_ALLOCATED], "0.00") +
                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.OTHERS_ALLOCATED], "0.00") +
                                            TdsMan.T_WriteBlankField(1, "^") +
                                            TdsMan.T_WriteField(strBookEntry) +
                                            TdsMan.T_WriteBlankField(1, "^") +
                                            //-- ANIK 2013/07/09
                                            //Commented by Shrey Kejriwal on 03/01/2014
                                            //TdsMan.T_WriteBlankField(2, "^"));

                                            //Added by Shrey Kejriwal on 03/01/2014
                                            TdsMan.T_WriteField(strFEE) +
                                            TdsMan.T_WriteBlankField(1, "^"));

                                    }
                                    // DEDUCTEE DETAIL
                                    //string[,] strGenerateTextFile = {{"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL'", "F", "C", "T"},
                                    //                             {"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN <> 'PANNOTAVBL'", "F", "COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG", "F"}};
                                    string[,] strReasonGenerateTextFile = {{"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL'", "F", "C", "T"},
                                                             {"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN <> 'PANNOTAVBL'", "F", "MST_REASON.REASON", "F"}};
                                    
                                    strSQL = "SELECT COR_TRN_CHALLAN.SL_NO                          AS CHALLAN_SL_NO," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.SL_NO                 AS DEDUCTEE_SL_NO," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.MODE                  AS MODE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_CODE         AS DEDUCTEE_CODE," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.DEDUCTEE_PAN          AS LAST_DEDUCTEE_PAN," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN          AS DEDUCTEE_PAN," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.DEDUCTEE_PAN_REF      AS LAST_AND_CURRENT_PAN_REF," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME         AS DEDUCTEE_NAME," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TAX_AMOUNT            AS TAX_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.SURCHARGE_AMOUNT      AS SURCHARGE_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.CESS_AMOUNT           AS CESS_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT          AS TOTAL_AMOUNT," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.TOTAL_AMOUNT          AS LAST_TOTAL_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT  AS TAX_DEPOSITED_AMOUNT," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT  AS LAST_TAX_DEPOSITED_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TOT_VALUE_PURCHASE    AS TOT_VALUE_PURCHASE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT        AS PAYMENT_AMOUNT," +
                                             "      " + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "  AS PAYMENT_DATE," +
                                             "      " + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " AS DEDUCTED_DATE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.RATE                  AS RATE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.GROSSING_UP_INDICATOR AS GROSSING_UP_INDICATOR," +
                                             "       COR_TRN_CHALLAN.BOOK_ENTRY                     AS BOOK_ENTRY," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY       AS CASH_BOOK_ENTRY," +
                                             "       MST_SECTION.SECTION_NAME                       AS SECTION_NAME," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO        AS CERTIFICATE_NO," +
                                        //"       COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG    AS NON_DEDUCTION_FLAG_27EQ," +
                                             "       MST_REASON.REASON                              AS REASON_27EQ," +
                                             "       MST_COUNTRY.COUNTRY_CODE                       AS COUNTRY_CODE,";

                                    if (cmnService.J_ReturnDoubleValue(strFVUVersion) >= cmnService.J_ReturnDoubleValue(T_FVU_Version.FVU_3_0))
                                        strSQL = strSQL + cmnService.J_SQLDBFormat(strReasonGenerateTextFile, J_SQLColFormat.Case_End) + " AS REASON ";
                                    else
                                    {
                                        //strSQL = strSQL + "COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG AS NON_DEDUCTION_FLAG ";
                                        strSQL = strSQL + "MST_REASON.REASON AS REASON ";
                                    }

                                    strSQL = strSQL + "FROM ((((((COR_TRN_CHALLAN INNER JOIN COR_HDR_BATCH " +
                                        "    ON COR_HDR_BATCH.BATCH_HEADER_ID           = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                                        "INNER JOIN   COR_TRN_DEDUCTEE_DETAILS " +
                                        "    ON COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID = COR_TRN_CHALLAN.TRN_CHALLAN_ID) " +
                                        "INNER JOIN   MST_SECTION " +
                                        "    ON COR_TRN_DEDUCTEE_DETAILS.SECTION_ID = MST_SECTION.SECTION_ID) " +
                                        "LEFT JOIN    COR_HDR_DEDUCTEE_DETAILS " +
                                        "    ON COR_HDR_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID = COR_TRN_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID) " +
                                        "LEFT JOIN MST_COUNTRY " +
                                        "    ON COR_TRN_DEDUCTEE_DETAILS.COUNTRY_ID = MST_COUNTRY.COUNTRY_ID) " +
                                        "LEFT JOIN MST_REASON " +
                                        "    ON COR_TRN_DEDUCTEE_DETAILS.REASON_ID = MST_REASON.REASON_ID)" +
                                        "WHERE   COR_TRN_CHALLAN.TRN_CHALLAN_ID                 =  " + strCDArray[lngCounter, (int)enmCHALLANIndex.TRN_CHALLAN_ID] + " " +
                                        "AND     COR_TRN_CHALLAN.MODE                           = '" + T_CorrectionMode.C3 + "' " +
                                        "AND     COR_TRN_DEDUCTEE_DETAILS.MODE                  IN ('" + T_CorrectionMode.Modify + "','" + T_CorrectionMode.Delete + "','" + T_CorrectionMode.Add + "') " +
                                        "AND     COR_HDR_BATCH.BATCH_HEADER_ID                  =" + lngBatchId + " " +
                                        "ORDER BY COR_TRN_DEDUCTEE_DETAILS.SL_NO";

                                    drdGenDeductee = dmlService.J_ExecSqlReturnReader(strSQL);
                                    if (drdGenDeductee == null)
                                        return false;

                                    while (drdGenDeductee.Read())
                                    {
                                        intPageNumber = intPageNumber + 1;

                                        strPaymentDate = TdsMan.J_ConvertToIntDDMMYYYY(Convert.ToString(drdGenDeductee["PAYMENT_DATE"]));
                                        strDeductedDate = TdsMan.J_ConvertToIntDDMMYYYY(Convert.ToString(drdGenDeductee["DEDUCTED_DATE"]));
                                        //
                                        strDeducteeCode = Convert.ToString(cmnService.J_ReturnInt64Value(Convert.ToString(drdGenDeductee["DEDUCTEE_CODE"])));
                                        if (strDeducteeCode == "0")
                                            strDeducteeCode = "";
                                        //
                                        if (txtFormNo.Text.Trim() == T_FormNo.F24Q)
                                        {
                                            strDDChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(Convert.ToString(strCDArray[lngCounter, (int)enmCHALLANIndex.DEPOSIT_DATE]));
                                            strDDRate = "";
                                            strBookEntry = "";
                                        }
                                        else
                                        {
                                            //strDDRate = Convert.ToString(drdGenDeductee["RATE"]).ToString("0.0000");
                                            strDDRate = string.Format("{0:0.0000}", Convert.ToDouble(Convert.ToString(drdGenDeductee["RATE"])));
                                        }
                                        //
                                        if (txtFormNo.Text.Trim() == T_FormNo.F27EQ)
                                            strTotValPur = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdGenDeductee["TOT_VALUE_PURCHASE"])));
                                        //
                                        // ANIK 2011-08-04
                                        if (txtFormNo.Text != T_FormNo.F24Q)
                                        {
                                            if (Convert.ToString(drdGenDeductee["CASH_BOOK_ENTRY"]) == "1")
                                                strBookEntry = "Y";
                                            else if (Convert.ToString(drdGenDeductee["CASH_BOOK_ENTRY"]) == "0")
                                                strBookEntry = "N";
                                        }

                                        string strNonDeductionFlag = "";
                                        string strCountryCode = "";

                                        // -------------------------------------------------------------------------------------------
                                        
                                        //Commented by Shrey Kejriwal on 30-04-2014
                                        //Dont know the reason for financial year checking when already all checks are provided before
                                        //saving data in the database

                                        //if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2010_11ID)
                                        //    strNonDeductionFlag = Convert.ToString(drdGenDeductee["NON_DEDUCTION_FLAG"]);
                                        //else
                                        //    strNonDeductionFlag = "";
                                        ////

                                        //Added by Shrey Kejriwal on 30-04-2014
                                        strNonDeductionFlag = Convert.ToString(drdGenDeductee["REASON"]);

                                        // -------------------------------------------------------------------------------------------


                                        if (txtFormNo.Text.Trim() == T_FormNo.F27EQ)
                                            strNonDeductionFlag = Convert.ToString(drdGenDeductee["REASON_27EQ"]);
                                        //
                                        if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2013_14ID)
                                        {
                                            strSectionNo = Convert.ToString(drdGenDeductee["SECTION_NAME"]);
                                            strCertificateNo = Convert.ToString(drdGenDeductee["CERTIFICATE_NO"]);
                                            strBookEntry = "";
                                        }
                                        else
                                        {
                                            strSectionNo = "";
                                            strCertificateNo = "";
                                        }
                                        //
                                        if (txtFormNo.Text.Trim() == T_FormNo.F27Q)
                                        {
                                            strCountryCode = Convert.ToString(drdGenDeductee["COUNTRY_CODE"]);
                                        }
                                        //
                                        if (Convert.ToString(drdGenDeductee["MODE"]) == T_CorrectionMode.Add)
                                        {
                                            cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                                            TdsMan.T_WriteField("DD") +
                                                            TdsMan.T_WriteField(intBatchNo.ToString()) +
                                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO]) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_SL_NO"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["MODE"])) +
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                            TdsMan.T_WriteField(strDeducteeCode) +
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_PAN"])) +
                                                            TdsMan.T_WriteBlankField(2, "^") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_NAME"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TAX_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["SURCHARGE_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["CESS_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TOTAL_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TAX_DEPOSITED_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                            TdsMan.T_WriteField(strTotValPur) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["PAYMENT_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(strPaymentDate) +
                                                            TdsMan.T_WriteField(strDeductedDate) +
                                                            TdsMan.T_WriteField(strDDChallanDate) +
                                                            TdsMan.T_WriteField(strDDRate) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["GROSSING_UP_INDICATOR"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(strBookEntry)) +
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                //TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["NON_DEDUCTION_FLAG"])) +
                                                            TdsMan.T_WriteField(strNonDeductionFlag) +
                                                            TdsMan.T_WriteBlankField(2, "^") +
                                                //-- ANIK 2013/07/09
                                                            TdsMan.T_WriteField(strSectionNo) + TdsMan.T_WriteField(strCertificateNo) +
                                                //-- ANIK 2013/11/21
                                                //TdsMan.T_WriteBlankField(4, "^") +
                                                            TdsMan.T_WriteBlankField(3, "^") +
                                                            TdsMan.T_WriteField(strCountryCode));
                                        }
                                        else if (Convert.ToString(drdGenDeductee["MODE"]) == T_CorrectionMode.Modify)
                                        {
                                            cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                                            TdsMan.T_WriteField("DD") +
                                                            TdsMan.T_WriteField(intBatchNo.ToString()) +
                                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO]) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_SL_NO"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["MODE"])) +
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                            TdsMan.T_WriteField(strDeducteeCode) +
                                                //TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_DEDUCTEE_PAN"])) +          //Commented by Shrey Kejriwal on 18/10/2011
                                                //TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_DEDUCTEE_PAN"])) +          //Commented by Shrey Kejriwal on 18/10/2011
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_PAN"])) +                 //Modified by Shrey Kejriwal on 18/10/2011
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_PAN"])) +                 //Modified by Shrey Kejriwal on 18/10/2011
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_AND_CURRENT_PAN_REF"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_AND_CURRENT_PAN_REF"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_NAME"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TAX_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["SURCHARGE_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["CESS_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TOTAL_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_TOTAL_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TAX_DEPOSITED_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_TAX_DEPOSITED_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(strTotValPur) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["PAYMENT_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(strPaymentDate) +
                                                            TdsMan.T_WriteField(strDeductedDate) +
                                                            TdsMan.T_WriteField(strDDChallanDate) +
                                                            TdsMan.T_WriteField(strDDRate) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["GROSSING_UP_INDICATOR"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(strBookEntry)) +
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                            TdsMan.T_WriteField(strNonDeductionFlag) +
                                                            TdsMan.T_WriteBlankField(2, "^") +
                                                //-- ANIK 2013/07/09
                                                            TdsMan.T_WriteField(strSectionNo) + TdsMan.T_WriteField(strCertificateNo) +
                                                //-- ANIK 2013/11/21
                                                //TdsMan.T_WriteBlankField(4, "^") +
                                                            TdsMan.T_WriteBlankField(3, "^") +
                                                            TdsMan.T_WriteField(strCountryCode));
                                        }
                                        else if (Convert.ToString(drdGenDeductee["MODE"]) == T_CorrectionMode.Delete)
                                        {
                                            cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                                            TdsMan.T_WriteField("DD") +
                                                            TdsMan.T_WriteField(intBatchNo.ToString()) +
                                                            TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO]) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_SL_NO"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["MODE"])) +
                                                            TdsMan.T_WriteBlankField(2, "^") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_DEDUCTEE_PAN"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_DEDUCTEE_PAN"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_AND_CURRENT_PAN_REF"])) +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_AND_CURRENT_PAN_REF"])) +
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TAX_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["SURCHARGE_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["CESS_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TOTAL_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_TOTAL_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TAX_DEPOSITED_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["LAST_TAX_DEPOSITED_AMOUNT"]), "0.00") +
                                                            TdsMan.T_WriteBlankField(9, "^") +
                                                            TdsMan.T_WriteField(strNonDeductionFlag) +   //Modified on 04/06/2012 by Shrey
                                                            TdsMan.T_WriteBlankField(2, "^") +
                                                //-- ANIK 2013/07/09
                                                //TdsMan.T_WriteField(strSectionNo) + 
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                //TdsMan.T_WriteField(strCertificateNo) +
                                                            TdsMan.T_WriteBlankField(1, "^") +
                                                            TdsMan.T_WriteBlankField(4, "^"));
                                        }
                                    }
                                    drdGenDeductee.Close();
                                }
                            }
                            lngNoOfBatchesC3 = 0;
                        }
                        //
                        #endregion

                        #region C9
                        if (lngNoOfBatchesC9 == 1)
                        {
                            //
                            strSQL = "SELECT COUNT(TRN_CHALLAN_ID) AS COUNT_CHALLAN_RECORDS " +
                                     "FROM   COR_TRN_CHALLAN " +
                                     "WHERE  MODE            = '" + T_CorrectionMode.C9 + "' " +
                                     "AND    BATCH_HEADER_ID = " + lngBatchId + " ";
                            string strCOUNT_CHALLAN_RECORDS = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                            //                            
                            strSQL = "SELECT SUM(TOT_TAX) AS CHALLAN_TOTAL_DEPOSIT " +
                                     "FROM   COR_TRN_CHALLAN " +
                                     "WHERE  MODE            = '" + T_CorrectionMode.C9 + "'  " +
                                     "AND    BATCH_HEADER_ID = " + lngBatchId + " ";
                            string strCHALLAN_TOTAL_DEPOSIT = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                            //
                            intPageNumber = intPageNumber + 1;
                            intBatchNo = intBatchNo + 1;
                            //
                            cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                            TdsMan.T_WriteField("BH") +
                                            TdsMan.T_WriteField(intBatchNo.ToString()) +
                                            TdsMan.T_WriteField(strCOUNT_CHALLAN_RECORDS) +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FORM_NO]) +
                                            TdsMan.T_WriteField(T_CorrectionMode.C9) +
                                            TdsMan.T_WriteBlankField(1, "^") +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ORIGINAL_RRR_NO]) +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PREVIOUS_RRR_NO]) +
                                            TdsMan.T_WriteBlankField(2, "^") +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.COMPANY_TAN]) +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.COMPANY_TAN]) +
                                            TdsMan.T_WriteBlankField(2, "^") +
                                            TdsMan.T_WriteField(cmnService.J_Left(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ASST_YR], 4) + cmnService.J_Right(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ASST_YR], 2)) +
                                            TdsMan.T_WriteField(cmnService.J_Left(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FA_YEAR], 4) + cmnService.J_Right(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FA_YEAR], 2)) +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PERIOD]) +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.COMPANY_NAME]) +
                                            TdsMan.T_WriteBlankField(12, "^") +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.C_CATEGORY]) +
                                            TdsMan.T_WriteBlankField(14, "^") +
                                            TdsMan.T_WriteField(strCHALLAN_TOTAL_DEPOSIT, "0.00") +
                                            TdsMan.T_WriteBlankField(3, "^") +
                                            TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.AO_APPROVAL]) +
                                            TdsMan.T_WriteBlankField(10, "^") +
                                //-- ANIK 2013/07/09
                                            TdsMan.T_WriteBlankField(7, "^"));

                            // CHALLAN HEADER                        
                            strSQL = "SELECT COUNT(*) AS CHALLN_ROW_COUNT " +
                                     "FROM   COR_TRN_CHALLAN " +
                                     "WHERE  MODE            = '" + T_CorrectionMode.C9 + "'  " +
                                     "AND    BATCH_HEADER_ID = " + lngBatchId + " ";
                            lngChallanRowCount = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL));
                            strCDArray = new string[lngChallanRowCount, 32];
                            //
                            strSQL = "SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID      AS TRN_CHALLAN_ID," +
                                     "       COR_TRN_CHALLAN.SL_NO               AS CHALLAN_DETAIL_RECORD_NO," +
                                //"       COR_HDR_CHALLAN.CHALLAN_NO          AS LAST_CHALLAN_NO," +
                                     "       COR_TRN_CHALLAN.CHALLAN_NO          AS NEW_CHALLAN_NO," +
                                //"       COR_HDR_CHALLAN.TRANSFER_VOUCHER_NO AS LAST_TRANSFER_VOUCHER_NO," +
                                     "       COR_TRN_CHALLAN.TRANSFER_VOUCHER_NO AS TRANSFER_VOUCHER_NO," +
                                //"       COR_HDR_CHALLAN.BSR_CODE            AS LAST_BSR_CODE," +
                                     "       COR_TRN_CHALLAN.BSR_CODE            AS BSR_CODE," +
                                //"       COR_HDR_CHALLAN.DEPOSIT_DATE        AS LAST_DATE_OF_DEPOSIT," +
                                     "      " + cmnService.J_SQLDBFormat("COR_TRN_CHALLAN.DEPOSIT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "  AS DEPOSIT_DATE," +
                                     "       MST_SECTION.SECTION_NAME            AS SECTION_NAME," +
                                     "       COR_TRN_CHALLAN.CHEQUE_NO           AS CHEQUE_NO," +
                                     "       COR_TRN_CHALLAN.TDS                 AS INCOME_TAX," +
                                     "       COR_TRN_CHALLAN.SURCHARGE           AS SURCHARGE," +
                                     "       COR_TRN_CHALLAN.EDUCATION_CESS      AS EDUCATION_CESS," +
                                     "       COR_TRN_CHALLAN.INTEREST            AS INTEREST," +
                                     "       COR_TRN_CHALLAN.OTHERS              AS OTHERS," +
                                     "       COR_TRN_CHALLAN.TOT_TAX             AS TOT_TAX," +
                                //"       COR_HDR_CHALLAN.TOT_TAX             AS LAST_TOT_TAX," +
                                     "       COR_TRN_CHALLAN.INTEREST_ALLOCATED  AS INTEREST_ALLOCATED," +
                                     "       COR_TRN_CHALLAN.OTHERS_ALLOCATED    AS OTHERS_ALLOCATED," +
                                     "       COR_TRN_CHALLAN.BOOK_ENTRY          AS BOOK_ENTRY," +
                                     "       COR_TRN_CHALLAN.REMARKS             AS REMARKS," +
                                     "       COR_TRN_CHALLAN.CHALLAN_UPDATION_INDICATOR AS CHALLAN_UPDATION_INDICATOR," +
                                     "       COR_TRN_CHALLAN.CTRL_TDS            AS CTRL_TDS," +
                                     "       COR_TRN_CHALLAN.CTRL_SURCHARGE      AS CTRL_SURCHARGE," +
                                     "       COR_TRN_CHALLAN.CTRL_EDU_CESS       AS CTRL_EDU_CESS," +
                                     "       COR_TRN_CHALLAN.CTRL_TOT_TAX        AS CTRL_TOT_TAX," +
                                     "       COR_TRN_CHALLAN.CTRL_TOT            AS CTRL_TOT," +
                                     "       COR_TRN_CHALLAN.LATE_FEE            AS LATE_FEE," +
                                     "       MST_MINOR_HEAD.MINOR_HEAD_CODE      AS MINOR_HEAD_CODE " +
                                     "FROM   (((COR_HDR_BATCH " +
                                     "INNER JOIN COR_TRN_CHALLAN " +
                                     "        ON COR_HDR_BATCH.BATCH_HEADER_ID  = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                                     "LEFT JOIN MST_SECTION " +
                                     "        ON COR_TRN_CHALLAN.SECTION_ID  = MST_SECTION.SECTION_ID) " +
                                     "LEFT JOIN MST_MINOR_HEAD " +
                                     "        ON COR_TRN_CHALLAN.MINOR_HEAD_ID  = MST_MINOR_HEAD.MINOR_HEAD_ID) " +
                                //"FROM   COR_HDR_BATCH," +
                                //"       COR_TRN_CHALLAN," +
                                //"       MST_SECTION " +
                                //"WHERE  COR_HDR_BATCH.BATCH_HEADER_ID  = COR_TRN_CHALLAN.BATCH_HEADER_ID " +
                                //"AND    COR_TRN_CHALLAN.SECTION_ID     = MST_SECTION.SECTION_ID " +
                                     "WHERE  COR_TRN_CHALLAN.MODE           = '" + T_CorrectionMode.C9 + "'  " +
                                     "AND    COR_TRN_CHALLAN.BATCH_HEADER_ID  = " + lngBatchId + " " +
                                     "ORDER BY COR_TRN_CHALLAN.SL_NO";

                            drdGenChallan = dmlService.J_ExecSqlReturnReader(strSQL);
                            if (drdGenChallan == null)
                                return false;
                            //
                            lngArrayCounter = 0;

                            while (drdGenChallan.Read())
                            {
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.TRN_CHALLAN_ID] = drdGenChallan["TRN_CHALLAN_ID"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO] = drdGenChallan["CHALLAN_DETAIL_RECORD_NO"].ToString();
                                //strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_CHALLAN_NO] = drdGenChallan["LAST_CHALLAN_NO"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.NEW_CHALLAN_NO] = drdGenChallan["NEW_CHALLAN_NO"].ToString();
                                //strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_TRANSFER_VOUCHER_NO] = drdGenChallan["LAST_TRANSFER_VOUCHER_NO"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.TRANSFER_VOUCHER_NO] = drdGenChallan["TRANSFER_VOUCHER_NO"].ToString();
                                //strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_BSR_CODE] = drdGenChallan["LAST_BSR_CODE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.BSR_CODE] = drdGenChallan["BSR_CODE"].ToString();
                                //strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_DATE_OF_DEPOSIT] = drdGenChallan["LAST_DATE_OF_DEPOSIT"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.DEPOSIT_DATE] = drdGenChallan["DEPOSIT_DATE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.SECTION_NAME] = drdGenChallan["SECTION_NAME"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CHEQUE_NO] = drdGenChallan["CHEQUE_NO"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.INCOME_TAX] = drdGenChallan["INCOME_TAX"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.SURCHARGE] = drdGenChallan["SURCHARGE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.EDUCATION_CESS] = drdGenChallan["EDUCATION_CESS"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.INTEREST] = drdGenChallan["INTEREST"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.OTHERS] = drdGenChallan["OTHERS"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.TOT_TAX] = drdGenChallan["TOT_TAX"].ToString();
                                //strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LAST_TOT_TAX] = drdGenChallan["LAST_TOT_TAX"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.INTEREST_ALLOCATED] = drdGenChallan["INTEREST_ALLOCATED"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.OTHERS_ALLOCATED] = drdGenChallan["OTHERS_ALLOCATED"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.BOOK_ENTRY] = drdGenChallan["BOOK_ENTRY"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.REMARKS] = drdGenChallan["REMARKS"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CHALLAN_UPDATION_INDICATOR] = drdGenChallan["CHALLAN_UPDATION_INDICATOR"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CTRL_TDS] = drdGenChallan["CTRL_TDS"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CTRL_SURCHARGE] = drdGenChallan["CTRL_SURCHARGE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CTRL_EDU_CESS] = drdGenChallan["CTRL_EDU_CESS"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CTRL_TOT_TAX] = drdGenChallan["CTRL_TOT_TAX"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.CTRL_TOT] = drdGenChallan["CTRL_TOT"].ToString();
                                //
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.LATE_FEE] = drdGenChallan["LATE_FEE"].ToString();
                                strCDArray[lngArrayCounter, (int)enmCHALLANIndex.MINOR_HEAD_CODE] = drdGenChallan["MINOR_HEAD_CODE"].ToString();

                                lngArrayCounter++;
                            }
                            drdGenChallan.Close();

                            if (lngArrayCounter > 0)
                            {
                                //-------------------------------------------------------------------------
                                for (long lngCounter = 0; lngCounter <= lngArrayCounter - 1; lngCounter++)
                                {
                                    //------------------------------------------------
                                    intPageNumber = intPageNumber + 1;

                                    //-- INITIALIZE
                                    strBookEntry = "";
                                    strChequeNo = "";
                                    strNilChallanIndiactor = "";
                                    strGenTotalNoDeducteeForChallan = "";
                                    strChallanDate = "";
                                    dblTotalTax = 0;
                                    lngGenChallanID = 0;
                                    //--

                                    lngGenChallanID = cmnService.J_ReturnInt32Value(strCDArray[lngCounter, (int)enmCHALLANIndex.TRN_CHALLAN_ID]);

                                    strGenTotalNoDeducteeForChallan = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(HDR_DEDUCTEE_DETAIL_ID) AS COUNT_DEDUCTEE_DETAIL_ID FROM COR_TRN_DEDUCTEE_DETAILS WHERE TRN_CHALLAN_ID = " + lngGenChallanID));

                                    // NIL CHALLAN INDICATOR
                                    dblTotalTax = cmnService.J_ReturnDoubleValue(strCDArray[lngCounter, (int)enmCHALLANIndex.TOT_TAX]);

                                    if (dblTotalTax == 0)
                                    {
                                        strNilChallanIndiactor = "Y";
                                        strLastChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(TdsMan.T_ReturnQuarterEndDate(txtQtr.Text, txtFAYear.Text));
                                        strChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(TdsMan.T_ReturnQuarterEndDate(txtQtr.Text, txtFAYear.Text));
                                        strChequeNo = "";
                                    }
                                    else
                                    {
                                        strNilChallanIndiactor = "N";
                                        strLastChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(strCDArray[lngCounter, (int)enmCHALLANIndex.LAST_DATE_OF_DEPOSIT]);
                                        strChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(strCDArray[lngCounter, (int)enmCHALLANIndex.DEPOSIT_DATE]);
                                        strChequeNo = strCDArray[lngCounter, (int)enmCHALLANIndex.CHEQUE_NO];
                                        if (strChequeNo == "")
                                            strChequeNo = "0";
                                    }

                                    // BOOK ENTRY
                                    if (strCDArray[lngCounter, (int)enmCHALLANIndex.TRANSFER_VOUCHER_NO].Trim() != "")
                                    {
                                        strBookEntry = "Y";
                                        strChequeNo = "";
                                    }
                                    else
                                        strBookEntry = "N";

                                    //if (txtCategory.Text.Substring(0, 1) == "A" || txtCategory.Text.Substring(0, 1) == "S")
                                    if (strBHArray[intCompanyCounter, (int)enmCompanyIndex.C_CATEGORY].Substring(0, 1) == "A" ||
                                        strBHArray[intCompanyCounter, (int)enmCompanyIndex.C_CATEGORY].Substring(0, 1) == "S")
                                        if (cmnService.J_ReturnDoubleValue(strCDArray[lngCounter, (int)enmCHALLANIndex.TOT_TAX]) > 0)
                                            if (strCDArray[lngCounter, (int)enmCHALLANIndex.TRANSFER_VOUCHER_NO].Trim() == "" &&
                                                strCDArray[lngCounter, (int)enmCHALLANIndex.BSR_CODE].Trim() == "" &&
                                                strCDArray[lngCounter, (int)enmCHALLANIndex.NEW_CHALLAN_NO].Trim() == "")
                                                strBookEntry = "Y";

                                    if (strBookEntry == "Y")
                                        strChequeNo = "";
                                    //
                                    strSQL = "SELECT COUNT(*) AS DEDUCTEE_DETAIL_ROW_COUNT " +
                                        "     FROM   COR_TRN_DEDUCTEE_DETAILS " +
                                        "     WHERE  BATCH_HEADER_ID        = " + lngBatchId + " " +
                                        "     AND    TRN_CHALLAN_ID         = " + strCDArray[lngCounter, (int)enmCHALLANIndex.TRN_CHALLAN_ID];

                                    string strCountPartyRecords = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                                    //    
                                    if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2013_14ID)
                                        strChequeNo = "";
                                    //
                                    if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2012_13ID)
                                        strFEE = string.Format("{0:0.00}", Convert.ToDouble(strCDArray[lngCounter, (int)enmCHALLANIndex.LATE_FEE].Trim() == "" ? "0" : strCDArray[lngCounter, (int)enmCHALLANIndex.LATE_FEE].Trim()));
                                    else
                                        strFEE = "";

                                    //
                                    if (dblTotalTax == 0)
                                        strBookEntry = "";
                                    //
                                    cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                        TdsMan.T_WriteField("CD") +
                                        TdsMan.T_WriteField(intBatchNo.ToString()) +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO]) +
                                        TdsMan.T_WriteField(strCountPartyRecords) +
                                        TdsMan.T_WriteField(strNilChallanIndiactor) +
                                        TdsMan.T_WriteBlankField(5, "^") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.NEW_CHALLAN_NO]) +
                                        TdsMan.T_WriteBlankField(1, "^") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.TRANSFER_VOUCHER_NO]) +
                                        TdsMan.T_WriteBlankField(1, "^") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.BSR_CODE]) +
                                        TdsMan.T_WriteBlankField(1, "^") +
                                        TdsMan.T_WriteField(strChallanDate) +
                                        TdsMan.T_WriteBlankField(2, "^") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.SECTION_NAME]) +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.INCOME_TAX], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.SURCHARGE], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.EDUCATION_CESS], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.INTEREST], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.OTHERS], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.TOT_TAX], "0.00") +
                                        TdsMan.T_WriteBlankField(1, "^") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CTRL_TOT_TAX], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CTRL_TDS], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CTRL_SURCHARGE], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CTRL_EDU_CESS], "0.00") +
                                        //TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CTRL_TOT_TAX], "0.00") + //Commented by Shrey Kejriwal on 20-11-2012
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CTRL_TOT], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.INTEREST_ALLOCATED], "0.00") +
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.OTHERS_ALLOCATED], "0.00") +
                                        TdsMan.T_WriteField(strChequeNo) +
                                        TdsMan.T_WriteField(strBookEntry) +
                                        TdsMan.T_WriteBlankField(1, "^") +
                                        //-- ANIK 2013/07/09
                                        TdsMan.T_WriteField(strFEE) + // FEE
                                        TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.MINOR_HEAD_CODE]));

                                    // DEDUCTEE DETAIL
                                    //string[,] strGenerateTextFile = {{"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL'", "F", "C", "T"},
                                    //                         {"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN <> 'PANNOTAVBL'", "F", "COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG", "F"}};
                                    string[,] strReasonGenerateTextFile = {{"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN = 'PANNOTAVBL'", "F", "C", "T"},
                                                             {"COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN <> 'PANNOTAVBL'", "F", "MST_REASON.REASON", "F"}};
                                    
                                    strSQL = "SELECT COR_TRN_CHALLAN.SL_NO                          AS CHALLAN_SL_NO," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.SL_NO                 AS DEDUCTEE_SL_NO," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.MODE                  AS MODE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_CODE         AS DEDUCTEE_CODE," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.DEDUCTEE_PAN          AS LAST_DEDUCTEE_PAN," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_PAN          AS DEDUCTEE_PAN," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.DEDUCTEE_PAN_REF      AS LAST_AND_CURRENT_PAN_REF," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.DEDUCTEE_NAME         AS DEDUCTEE_NAME," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TAX_AMOUNT            AS TAX_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.SURCHARGE_AMOUNT      AS SURCHARGE_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.CESS_AMOUNT           AS CESS_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TOTAL_AMOUNT          AS TOTAL_AMOUNT," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.TOTAL_AMOUNT          AS LAST_TOTAL_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT  AS TAX_DEPOSITED_AMOUNT," +
                                             "       COR_HDR_DEDUCTEE_DETAILS.TAX_DEPOSITED_AMOUNT  AS LAST_TAX_DEPOSITED_AMOUNT," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.TOT_VALUE_PURCHASE    AS TOT_VALUE_PURCHASE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.PAYMENT_AMOUNT        AS PAYMENT_AMOUNT," +
                                             "      " + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.PAYMENT_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + "  AS PAYMENT_DATE," +
                                             "      " + cmnService.J_SQLDBFormat("COR_TRN_DEDUCTEE_DETAILS.DEDUCTED_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " AS DEDUCTED_DATE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.RATE                  AS RATE," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.GROSSING_UP_INDICATOR AS GROSSING_UP_INDICATOR," +
                                             "       COR_TRN_CHALLAN.BOOK_ENTRY                     AS BOOK_ENTRY," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY       AS CASH_BOOK_ENTRY," +
                                             "       COR_TRN_DEDUCTEE_DETAILS.CERTIFICATE_NO        AS CERTIFICATE_NO," +
                                             "       MST_SECTION.SECTION_NAME                       AS SECTION_NAME," +
                                             //"       COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG    AS NON_DEDUCTION_FLAG_27EQ," +
                                             "       MST_REASON.REASON                              AS REASON_27EQ," +
                                             "       MST_COUNTRY.COUNTRY_CODE                       AS COUNTRY_CODE,";

                                    if (cmnService.J_ReturnDoubleValue(strFVUVersion) >= cmnService.J_ReturnDoubleValue(T_FVU_Version.FVU_3_0))
                                        strSQL = strSQL + cmnService.J_SQLDBFormat(strReasonGenerateTextFile, J_SQLColFormat.Case_End) + " AS REASON ";
                                    else
                                    {
                                        //strSQL = strSQL + "COR_TRN_DEDUCTEE_DETAILS.NON_DEDUCTION_FLAG AS NON_DEDUCTION_FLAG ";
                                        strSQL = strSQL + "MST_REASON.REASON AS REASON ";
                                    }

                                    strSQL = strSQL + "FROM ((((((COR_TRN_CHALLAN INNER JOIN COR_HDR_BATCH " +
                                        "    ON COR_HDR_BATCH.BATCH_HEADER_ID           = COR_TRN_CHALLAN.BATCH_HEADER_ID) " +
                                        "INNER JOIN   COR_TRN_DEDUCTEE_DETAILS " +
                                        "    ON COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID = COR_TRN_CHALLAN.TRN_CHALLAN_ID) " +
                                        "INNER JOIN   MST_SECTION " +
                                        "    ON COR_TRN_DEDUCTEE_DETAILS.SECTION_ID = MST_SECTION.SECTION_ID) " +
                                        "LEFT JOIN    COR_HDR_DEDUCTEE_DETAILS " +
                                        "    ON COR_HDR_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID  = COR_TRN_DEDUCTEE_DETAILS.HDR_DEDUCTEE_DETAIL_ID) " +
                                        "LEFT JOIN MST_COUNTRY " +
                                        "    ON COR_TRN_DEDUCTEE_DETAILS.COUNTRY_ID = MST_COUNTRY.COUNTRY_ID) " +
                                        "LEFT JOIN MST_REASON " +
                                        "    ON COR_TRN_DEDUCTEE_DETAILS.REASON_ID = MST_REASON.REASON_ID)" +
                                        "WHERE   COR_TRN_CHALLAN.TRN_CHALLAN_ID                  =  " + strCDArray[lngCounter, (int)enmCHALLANIndex.TRN_CHALLAN_ID] + " " +
                                        "AND     COR_HDR_BATCH.BATCH_HEADER_ID                   = " + lngBatchId + " " +
                                        "ORDER BY COR_TRN_DEDUCTEE_DETAILS.SL_NO";

                                    drdGenDeductee = dmlService.J_ExecSqlReturnReader(strSQL);
                                    if (drdGenDeductee == null)
                                        return false;
                                    //
                                    string strNonDeductionFlag = "";
                                    string strCountryCode = "";
                                    //
                                    while (drdGenDeductee.Read())
                                    {
                                        intPageNumber = intPageNumber + 1;

                                        strPaymentDate = TdsMan.J_ConvertToIntDDMMYYYY(Convert.ToString(drdGenDeductee["PAYMENT_DATE"]));
                                        strDeductedDate = TdsMan.J_ConvertToIntDDMMYYYY(Convert.ToString(drdGenDeductee["DEDUCTED_DATE"]));
                                        //
                                        strDeducteeCode = Convert.ToString(cmnService.J_ReturnInt64Value(Convert.ToString(drdGenDeductee["DEDUCTEE_CODE"])));
                                        if (strDeducteeCode == "0")
                                            strDeducteeCode = "";
                                        //
                                        if (txtFormNo.Text.Trim() == T_FormNo.F24Q)
                                        {
                                            strDDChallanDate = TdsMan.J_ConvertToIntDDMMYYYY(Convert.ToString(strCDArray[lngCounter, (int)enmCHALLANIndex.DEPOSIT_DATE]));
                                            strDDRate = "";
                                            strBookEntry = "";
                                        }
                                        else
                                        {
                                            //strDDRate = Convert.ToString(drdGenDeductee["RATE"]).ToString("0.0000");
                                            strDDRate = string.Format("{0:0.0000}", Convert.ToDouble(Convert.ToString(drdGenDeductee["RATE"])));
                                        }
                                        //
                                        if (txtFormNo.Text.Trim() == T_FormNo.F27EQ)
                                        {
                                            strNonDeductionFlag = Convert.ToString(drdGenDeductee["REASON_27EQ"]);
                                            strTotValPur = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(drdGenDeductee["TOT_VALUE_PURCHASE"])));
                                        }
                                        else
                                        {
                                            strNonDeductionFlag = Convert.ToString(drdGenDeductee["REASON"]);
                                        }
                                        //
                                        // ANIK 2011-08-04
                                        if (txtFormNo.Text != T_FormNo.F24Q)
                                        {
                                            if (Convert.ToString(drdGenDeductee["CASH_BOOK_ENTRY"]) == "1")
                                                strBookEntry = "Y";
                                            else if (Convert.ToString(drdGenDeductee["CASH_BOOK_ENTRY"]) == "0")
                                                strBookEntry = "N";
                                        }
                                        //
                                        if (Convert.ToInt32(txtFAYearID.Text) >= T_FinancialYearID.F2013_14ID)
                                        {
                                            strSectionNo = Convert.ToString(drdGenDeductee["SECTION_NAME"]);
                                            strCertificateNo = Convert.ToString(drdGenDeductee["CERTIFICATE_NO"]);
                                            strBookEntry = "";
                                        }
                                        else
                                        {
                                            strSectionNo = "";
                                            strCertificateNo = "";
                                        }
                                        //
                                        if (txtFormNo.Text.Trim() == T_FormNo.F27Q)
                                        {
                                            strCountryCode = Convert.ToString(drdGenDeductee["COUNTRY_CODE"]);
                                        }
                                        //
                                        cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                                                TdsMan.T_WriteField("DD") +
                                                                TdsMan.T_WriteField(intBatchNo.ToString()) +
                                                                TdsMan.T_WriteField(strCDArray[lngCounter, (int)enmCHALLANIndex.CHALLAN_DETAIL_RECORD_NO]) +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_SL_NO"])) +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["MODE"])) +
                                                                TdsMan.T_WriteBlankField(1, "^") +
                                                                TdsMan.T_WriteField(strDeducteeCode) +
                                                                TdsMan.T_WriteBlankField(1, "^") +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["DEDUCTEE_PAN"])) +
                                                                TdsMan.T_WriteBlankField(2, "^") +
                                                                TdsMan.T_WriteField(TdsMan.RemoveSpecialCharacters(Convert.ToString(drdGenDeductee["DEDUCTEE_NAME"]))) +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TAX_AMOUNT"]), "0.00") +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["SURCHARGE_AMOUNT"]), "0.00") +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["CESS_AMOUNT"]), "0.00") +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TOTAL_AMOUNT"]), "0.00") +
                                                                TdsMan.T_WriteBlankField(1, "^") +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["TAX_DEPOSITED_AMOUNT"]), "0.00") +
                                                                TdsMan.T_WriteBlankField(1, "^") +
                                                                TdsMan.T_WriteField(strTotValPur) +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["PAYMENT_AMOUNT"]), "0.00") +
                                                                TdsMan.T_WriteField(strPaymentDate) +
                                                                TdsMan.T_WriteField(strDeductedDate) +
                                                                TdsMan.T_WriteField(strDDChallanDate) +
                                                                TdsMan.T_WriteField(strDDRate) +
                                                                TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["GROSSING_UP_INDICATOR"])) +
                                                                TdsMan.T_WriteField(Convert.ToString(strBookEntry)) +
                                                                TdsMan.T_WriteBlankField(1, "^") +
                                            //TdsMan.T_WriteField(Convert.ToString(drdGenDeductee["NON_DEDUCTION_FLAG"])) +
                                                                TdsMan.T_WriteField(strNonDeductionFlag) +
                                                                TdsMan.T_WriteBlankField(2, "^") +
                                            //-- ANIK 2013/07/09
                                                                TdsMan.T_WriteField(strSectionNo) + TdsMan.T_WriteField(strCertificateNo) +
                                            //-- ANIK 2013/11/21
                                            //TdsMan.T_WriteBlankField(4, "^") +
                                                                TdsMan.T_WriteBlankField(3, "^") +
                                                                TdsMan.T_WriteField(strCountryCode));
                                    }
                                    drdGenDeductee.Close();
                                }
                            }
                            lngNoOfBatchesC9 = 0;
                        }
                        #endregion

                        #region C4
                        if (lngNoOfBatchesC4 == 1)
                        {
                            if (txtFormNo.Text.Trim() == T_FormNo.F24Q && txtQtr.Text.Trim() == T_Qtr.Q4)
                            {
                                //
                                //GET COUNT OF SD RECORDS
                                //if (txtFormNo.Text.Trim() == T_FormNo.F24Q && txtQtr.Text.Trim() == T_Qtr.Q4)
                                //{
                                strSQL = "SELECT COUNT(*) AS COUNT_SD " +
                                         "FROM   COR_TRN_SALARY_DETAILS " +
                                         "WHERE  BATCH_HEADER_ID = " + lngBatchId + " " +
                                         "AND    MODE            <> '' ";
                                strCountSDRecords = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                                //
                                strSQL = "SELECT SUM(GROSS_TOTAL_INCOME) AS GROSS_TOTAL_INCOME " +
                                          "FROM  COR_TRN_SALARY_DETAILS " +
                                          "WHERE BATCH_HEADER_ID = " + lngBatchId + " " +
                                          "AND   MODE            <> '' ";
                                strGrossTotalIncome = Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL));
                                //}
                                //
                                intPageNumber = intPageNumber + 1;
                                intBatchNo = intBatchNo + 1;
                                //
                                cmnService.J_WriteLine(ref StreamWriter, TdsMan.T_WriteField(intPageNumber.ToString()) +
                                                TdsMan.T_WriteField("BH") +
                                                TdsMan.T_WriteField(intBatchNo.ToString()) +
                                                TdsMan.T_WriteBlankField(1, "^") +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FORM_NO]) +
                                                TdsMan.T_WriteField(T_CorrectionMode.C4) +
                                                TdsMan.T_WriteBlankField(1, "^") +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ORIGINAL_RRR_NO]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PREVIOUS_RRR_NO]) +
                                                TdsMan.T_WriteBlankField(2, "^") +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.COMPANY_TAN]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.COMPANY_TAN]) +
                                                TdsMan.T_WriteBlankField(2, "^") +
                                                TdsMan.T_WriteField(cmnService.J_Left(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ASST_YR], 4) + cmnService.J_Right(strBHArray[intCompanyCounter, (int)enmCompanyIndex.ASST_YR], 2)) +
                                                TdsMan.T_WriteField(cmnService.J_Left(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FA_YEAR], 4) + cmnService.J_Right(strBHArray[intCompanyCounter, (int)enmCompanyIndex.FA_YEAR], 2)) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.PERIOD]) +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.COMPANY_NAME]) +
                                                TdsMan.T_WriteBlankField(12, "^") +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.C_CATEGORY]) +
                                                TdsMan.T_WriteBlankField(16, "^") +
                                                TdsMan.T_WriteField(Convert.ToString(strCountSDRecords)) +
                                                TdsMan.T_WriteField(strGrossTotalIncome, "0.00") +
                                                TdsMan.T_WriteField(strBHArray[intCompanyCounter, (int)enmCompanyIndex.AO_APPROVAL]) +
                                                TdsMan.T_WriteBlankField(10, "^") +
                                    //-- ANIK 2013/07/09
                                                TdsMan.T_WriteBlankField(7, "^"));
                                // SALARY DETAIL
                                // CHALLAN HEADER
                                strSQL = "SELECT COUNT(*) AS SD_ROW_COUNT " +
                                    "     FROM   COR_TRN_SALARY_DETAILS " +
                                    "     WHERE  BATCH_HEADER_ID = " + lngBatchId + " " +
                                    "     AND   (COR_TRN_SALARY_DETAILS.MODE     <> ''" +
                                    "         OR COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR = 1)";

                                long lngSDRowCount = Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strSQL));
                                strSDArray = new string[lngSDRowCount, 29];
                                //
                                string[,] strShowHigherRateRecordMatrix = {{"COR_TRN_SALARY_DETAILS.TAX_DEDUCTED_HIGHER_RATE = 1 ", "F", "Y", "T"},
                                                               {"COR_TRN_SALARY_DETAILS.TAX_DEDUCTED_HIGHER_RATE = 0 ", "F", "N", "T"}};

                                strSQL = "SELECT COR_TRN_COMPANY.TRN_COMPANY_ID                           AS COMPANY_ID," +
                                            "       COR_TRN_COMPANY.COMPANY_NAME                          AS COMPANY_NAME," +
                                            "       COR_HDR_BATCH.FORM_NO                                 AS FORM_NO," +
                                            "       COR_HDR_BATCH.QTR                                     AS QTR," +
                                            "       COR_TRN_COMPANY.TAN_NO                                AS TAN_NO," +
                                            "       COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID          AS TRN_SALARY_DETAILS_ID," +
                                            "       COR_TRN_SALARY_DETAILS.MODE                           AS MODE," +
                                            "       COR_TRN_SALARY_DETAILS.SL_NO                          AS SL_NO," +
                                            "       COR_TRN_SALARY_DETAILS.EMPLOYEE_NAME                  AS EMPLOYEE_NAME," +
                                            "       COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN                   AS EMPLOYEE_PAN," +
                                            "       COR_TRN_SALARY_DETAILS.EMPLOYEE_CATEGORY              AS EMPLOYEE_CATEGORY," +
                                            "       " + cmnService.J_SQLDBFormat("COR_TRN_SALARY_DETAILS.FROM_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatDDMMYYYY) + " AS FROM_DATE," +
                                            "       " + cmnService.J_SQLDBFormat("COR_TRN_SALARY_DETAILS.TO_DATE", J_ColumnType.Date, J_SQLColFormat.DateFormatDDMMYYYY) + " AS TO_DATE," +
                                            "       COR_TRN_SALARY_DETAILS.TS_BALANCE                     AS TS_BALANCE," +
                                            "       COR_TRN_SALARY_DETAILS.US_16_EA                       AS US_16_EA," +
                                            "       COR_TRN_SALARY_DETAILS.US_16_TE                       AS US_16_TE," +
                                            "       COR_TRN_SALARY_DETAILS.US_16_AGGREGATE                AS US_16_AGGREGATE," +
                                            "       COR_TRN_SALARY_DETAILS.INCOME_CHARGEABLE              AS INCOME_CHARGEABLE," +
                                            "       COR_TRN_SALARY_DETAILS.AIS_Total                      AS AIS_Total," +
                                            "       COR_TRN_SALARY_DETAILS.GROSS_TOTAL_INCOME             AS GROSS_TOTAL_INCOME," +
                                            "       COR_HDR_SALARY_DETAILS.GROSS_TOTAL_INCOME             AS LAST_GROSS_TOTAL_INCOME," +
                                            "       COR_TRN_SALARY_DETAILS.CVIA_SEC80CCE_TOTAL_DED_AMOUNT AS CVIA_SEC80CCE_TOTAL_DED_AMOUNT," +
                                            "       COR_TRN_SALARY_DETAILS.CVIA_SEC80CCF_DED_AMOUNT       AS CVIA_SEC80CCF_DED_AMOUNT," +
                                            "       COR_TRN_SALARY_DETAILS.CVIA_OTH_DED_TOTAL             AS CVIA_OTH_DED_TOTAL," +
                                            "       COR_TRN_SALARY_DETAILS.CVIA_DED_TOTAL                 AS CVIA_DED_TOTAL," +
                                            "       COR_TRN_SALARY_DETAILS.TOTAL_INCOME                   AS TOTAL_INCOME," +
                                            "       COR_TRN_SALARY_DETAILS.TAX_TOTAL_INCOME               AS TAX_TOTAL_INCOME," +
                                            "       COR_TRN_SALARY_DETAILS.SCHG_TOTAL_INCOME              AS SCHG_TOTAL_INCOME," +
                                            "       COR_TRN_SALARY_DETAILS.ECESS_TOTAL_INCOME             AS ECESS_TOTAL_INCOME," +
                                            "       COR_TRN_SALARY_DETAILS.TAX_PAYABLE_AGGREGATE          AS TAX_PAYABLE_AGGREGATE," +
                                            "       COR_TRN_SALARY_DETAILS.US_89_LESS                     AS US_89_LESS," +
                                            "       COR_TRN_SALARY_DETAILS.TAX_PAYABLE                    AS TAX_PAYABLE," +
                                            "       COR_TRN_SALARY_DETAILS.TOTAL_TDS_DEDUCTED             AS TOTAL_TDS_DEDUCTED," +
                                            "       COR_TRN_SALARY_DETAILS.SHORTFALL_TAX                  AS SHORTFALL_TAX," +
                                            "       COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR         AS PAN_UPDATION_INDICATOR," +
                                            //Added By Anik on 22/04/2014 Adding the new Fields into TextFile 
                                            "       COR_TRN_SALARY_DETAILS.TAXABLE_AMOUNT                 AS TAXABLE_AMOUNT, " +
                                            "       COR_TRN_SALARY_DETAILS.REPORTED_TAXABLE_AMOUNT        AS REPORTED_TAXABLE_AMOUNT, " +
                                            "       COR_TRN_SALARY_DETAILS.TOTAL_TAX_DEDUCTED_AMOUNT      AS TOTAL_TAX_DEDUCTED_AMOUNT, " +
                                            "       COR_TRN_SALARY_DETAILS.PREVIOUS_TAX_DEDUCTED_TOTAL    AS PREVIOUS_TAX_DEDUCTED_TOTAL, " +
                                            "       " + cmnService.J_SQLDBFormat(strShowHigherRateRecordMatrix, J_SQLColFormat.Case_End) + " AS TAX_DEDUCTED_HIGHER_RATE " +
                                            " FROM  (((COR_HDR_BATCH INNER JOIN COR_TRN_COMPANY " +
                                            "       ON COR_HDR_BATCH.BATCH_HEADER_ID = COR_TRN_COMPANY.BATCH_HEADER_ID) " +
                                            "       INNER JOIN COR_TRN_SALARY_DETAILS " +
                                            "       ON COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID = COR_HDR_BATCH.BATCH_HEADER_ID) " +
                                            "       LEFT JOIN COR_HDR_SALARY_DETAILS " +
                                            "       ON COR_TRN_SALARY_DETAILS.HDR_SALARY_DETAILS_ID = COR_HDR_SALARY_DETAILS.HDR_SALARY_DETAILS_ID) " +
                                            " WHERE COR_TRN_COMPANY.BATCH_HEADER_ID                = " + lngBatchId + " " +
                                            " AND   COR_HDR_BATCH.FORM_NO                          = '" + T_FormNo.F24Q + "'" +
                                            " AND   COR_HDR_BATCH.QTR                              = '" + T_Qtr.Q4 + "'" +
                                            " AND   COR_TRN_SALARY_DETAILS.MODE                    <> '' " +
                                            " ORDER BY COR_TRN_SALARY_DETAILS.SL_NO";
                                drdGenDeductee = dmlService.J_ExecSqlReturnReader(strSQL);
                                if (drdGenDeductee == null)
                                    return false;

                                lngArrayCounter = 0;
                                while (drdGenDeductee.Read())
                                {
                                    strFromDate = TdsMan.J_ConvertToIntDDMMYYYY(Convert.ToString(drdGenDeductee["FROM_DATE"]));
                                    strToDate = TdsMan.J_ConvertToIntDDMMYYYY(Convert.ToString(drdGenDeductee["TO_DATE"]));
                                    //---    
                                    strSDArray[lngArrayCounter, (int)enmSALARY_DETAILIndex.SD_ID] = drdGenDeductee["TRN_SALARY_DETAILS_ID"].ToString();
                                    strSDArray[lngArrayCounter, (int)enmSALARY_DETAILIndex.SL_NO] = drdGenDeductee["SL_NO"].ToString();
                                    strSDArray[lngArrayCounter, (int)enmSALARY_DETAILIndex.MODE] = drdGenDeductee["MODE"].ToString();
                                    strSDArray[lngArrayCounter, (int)enmSALARY_DETAILIndex.EMPLOYEE_NAME] = drdGenDeductee["EMPLOYEE_NAME"].ToString();
                                    strSDArray[lngArrayCounter, (int)enmSALARY_DETAILIndex.EMPLOYEE_PAN] = drdGenDeductee["EMPLOYEE_PAN"].ToString();
                                    strSDArray[lngArrayCounter, (int)enmSALARY_DETAILIndex.EMPLOYEE_CATEGORY] = drdGenDeductee["EMPLOYEE_CATEGORY"].ToString();
