        #region CleanOutputFolder
        private void CleanOutputFolder(long BasicInfoId)
        {
            try
            {
                // DELETE FILES OF SAME BASIC INFO FROM THE '\FVU files' FOLDER
                //strSQL = "SELECT OUTPUT_FILE_PATH + '\\' + LEFT(INPUT_FILE_NAME,8) AS FILE_PATH " +
                //         "FROM TRN_FILE_GENERATION_LOG " +
                //         "WHERE BASIC_INFO_ID = " + BasicInfoId + " " +
                //         "AND OUTPUT_FILE_PATH <> ' ' " +
                //         "AND CORR = 1 " +
                //         "ORDER BY  FG_LOG_ID DESC";
                strSQL = "SELECT OUTPUT_FILE_PATH + '\\' + LEFT(INPUT_FILE_NAME,7) AS FILE_PATH " +
                         "FROM TRN_FILE_GENERATION_LOG " +
                         "WHERE BASIC_INFO_ID = " + BasicInfoId + " " +
                         "AND OUTPUT_FILE_PATH <> ' ' " +
                         "AND CORR = 1 " +
                         "ORDER BY  FG_LOG_ID DESC";
                string strInputFileName = Convert.ToString(dmlService.J_ExecSqlReturnScalar(dmlService.J_pCommand, strSQL));
                //
                if (strInputFileName != "")
                {
                    // DELETE .txt FILES
                    //if (File.Exists(Path.Combine(newPath, Path.ChangeExtension(strInputFileName, ".txt"))) == true)
                    //    File.Delete(Path.Combine(newPath, Path.ChangeExtension(strInputFileName, ".txt")));
                    //// DELETE err FILES
                    if (File.Exists(strInputFileName + "_Electronic_Statement_Warning_File.html") == true)
                        File.Delete(strInputFileName + "_Electronic_Statement_Warning_File.html");
                    // DELETE err FILES
                    if (File.Exists(strInputFileName + "err.html") == true)
                        File.Delete(strInputFileName + "err.html");
                    // DELETE _BH FILES
                    if (File.Exists(strInputFileName + "_BH.html") == true)
                        File.Delete(strInputFileName + "_BH.html");
                    // DELETE _CD FILES
                    if (File.Exists(strInputFileName + "_CD.html") == true)
                        File.Delete(strInputFileName + "_CD.html");
                    // DELETE _PAN_Statistics FILES
                    if (File.Exists(strInputFileName + "_PAN_Statistics.html") == true)
                        File.Delete(strInputFileName + "_PAN_Statistics.html");
                    // DELETE .html FILES
                    if (File.Exists(strInputFileName + ".html") == true)
                        File.Delete(strInputFileName + ".html");
                    // DELETE .err FILES
                    if (File.Exists(strInputFileName + ".err") == true)
                        File.Delete(strInputFileName + ".err");
                    // DELETE .fvu FILES
                    if (File.Exists(strInputFileName + ".fvu") == true)
                        File.Delete(strInputFileName + ".fvu");

                    //Added by Shrey Kejriwal on 03/01/2014
                    //Delete fvu.log files
                    if (File.Exists(strInputFileName + ".fvu.log") == true)
                        File.Delete(strInputFileName + ".fvu.log");


                    ////Added by Shrey Kejriwal on 03/01/2014

                    string strForm27APath = ReturnGeneratedForm27APath();

                    if (File.Exists(strForm27APath) == true)
                    {
                        //Deleting the existing form 27A pdf file --- only if it is not open.
                        if (TdsMan.T_isFileOpenOrReadOnly(ref strForm27APath) == false)
                            File.Delete(strForm27APath);
                    }

                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region LoadBatch
        private void LoadBatch()
        {
            //-----------------------------------------------------------
            string[,] strMatrixBatch = {{"BATCH_HEADER_ID", "0", "", "Right", "", "F", ""},
                                        {"FA Year", "70", "S", "", "", "", ""},
                                        {"Form No", "75", "S", "", "", "", ""},
                                        {"Qtr", "35", "", "", "", "", ""},
                                        {"Company Name", "250", "", "", "", "", "T"},
                                        {"TAN No.", "90", "", "", "", "", ""},
                                        {"Imported date & Time", "140", "dd/MM/yyyy", "", "", "", ""},
                                        {"Total Corrections", "100", "", "Right", "", "", ""}};
            //-----------------------------------------------------------
            strMatrixBatchGrid = strMatrixBatch;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------

            string[,] strLoadCorrectionMatrix = {{"COR_TRN_COMPANY.MODE = '" + T_CorrectionMode.TANUpdation + "'", "F", "Cancelled", "T"},
                                                 {"JAYA", "F", "COR_HDR_BATCH.TOTAL_CORRECTION", "F"}};

            strOrderBy = "COR_HDR_BATCH.BATCH_HEADER_ID DESC";
            strQuery = "SELECT COR_HDR_BATCH.BATCH_HEADER_ID  AS BATCH_HEADER_ID," +
                      "        MST_ASSESSMENT.FA_YEAR         AS FA_YEAR," +
                      "        COR_HDR_BATCH.FORM_NO          AS FORM_NO," +
                      "        COR_HDR_BATCH.QTR              AS QTR," +
                      "        COR_TRN_COMPANY.COMPANY_NAME   AS COMPANY_NAME," +
                      "        COR_TRN_COMPANY.TAN_NO         AS TAN_NO," +
                      "        FORMAT(COR_HDR_BATCH.IMPORTED_DATE, \"dd/MM/yyyy h:m AMPM\")   AS IMPORTED_DATE," +
                      "        " + cmnService.J_SQLDBFormat(strLoadCorrectionMatrix, J_SQLColFormat.Case_End, J_ElsePart.YES) + " AS TOTAL_CORRECTION " +
                      "FROM    COR_HDR_BATCH," +
                      "        MST_ASSESSMENT," +
                      "        COR_TRN_COMPANY " +
                      "WHERE   COR_HDR_BATCH.ASST_ID            = MST_ASSESSMENT.ASST_ID " +
                      "AND     COR_HDR_BATCH.BATCH_HEADER_ID    = COR_TRN_COMPANY.BATCH_HEADER_ID ";
            //-----------------------------------------------------------
            strSQL = strQuery + "ORDER BY " + strOrderBy;
            //-----------------------------------------------------------
            if (dsetGridClone != null) dsetGridClone.Clear();
            dsetGridClone = dmlService.J_ShowDataInGrid(ref  dgcViewBatch, strSQL, strMatrixBatchGrid);       //Show Data into the Grid

        }
        #endregion

        #region ShowBatchRecord
        private bool ShowBatchRecord(long Id)
        {
            IDataReader drdShowBatchRecord = null;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            try
            {
                //MODIFIED BY SHREY KEJRIWAL ON 02/03/2012

                strSQL = "SELECT MST_ASSESSMENT.FA_YEAR         AS FA_YEAR," +
                    "            COR_HDR_BATCH.ASST_ID          AS ASST_ID," +
                    "            COR_HDR_BATCH.FORM_NO          AS FORM_NO," +
                    "            COR_HDR_BATCH.QTR              AS QTR," +
                    "            COR_HDR_COMPANY.TAN_NO         AS TAN_NO," +
                    "            COR_HDR_COMPANY.HDR_COMPANY_ID AS HDR_COMPANY_ID," +
                    "            COR_HDR_COMPANY.COMPANY_NAME   AS COMPANY_NAME," +
                    "            MST_CATEGORY.CATEGORY_CODE + ' ' + MST_CATEGORY.CATEGORY_DESCRIPTION AS CATEGORY_DESCRIPTION," +
                    "            COR_HDR_BATCH.RPU_NAME         AS RPU_NAME," +
                    "            COR_HDR_BATCH.FILE_DATE        AS FILE_DATE," +
                    "            COR_HDR_BATCH.IMPORTED_DATE    AS IMPORTED_DATE," +
                    "            COR_HDR_BATCH.INVALID_RETURN   AS INVALID_RETURN" +
                    "     FROM   (((COR_HDR_BATCH INNER JOIN COR_HDR_COMPANY " +
                    "            ON COR_HDR_BATCH.BATCH_HEADER_ID = COR_HDR_COMPANY.BATCH_HEADER_ID)" +
                    "            INNER JOIN MST_ASSESSMENT " +
                    "            ON COR_HDR_BATCH.ASST_ID         = MST_ASSESSMENT.ASST_ID)" +
                    "            LEFT JOIN MST_CATEGORY " +
                    "            ON COR_HDR_COMPANY.D_CATEGORY_ID = MST_CATEGORY.CATEGORY_ID)" +
                    "     WHERE  COR_HDR_COMPANY.BATCH_HEADER_ID = " + Id + " ";


                drdShowBatchRecord = dmlService.J_ExecSqlReturnReader(strSQL);
                if (drdShowBatchRecord == null)
                {
                    drdShowBatchRecord.Close();
                    drdShowBatchRecord.Dispose();
                    return false;
                }
                while (drdShowBatchRecord.Read())
                {
                    lngChallanID = Id;

                    grpMain.Visible = true;
                    txtFAYear.Text = Convert.ToString(drdShowBatchRecord["FA_YEAR"]);
                    txtFAYearID.Text = Convert.ToString(drdShowBatchRecord["ASST_ID"]);
                    txtFormNo.Text = Convert.ToString(drdShowBatchRecord["FORM_NO"]);
                    txtQtr.Text = Convert.ToString(drdShowBatchRecord["QTR"]);
                    txtTAN.Text = Convert.ToString(drdShowBatchRecord["TAN_NO"]);
                    txtCompanyID.Text = Convert.ToString(drdShowBatchRecord["HDR_COMPANY_ID"]);
                    txtCompany.Text = Convert.ToString(drdShowBatchRecord["COMPANY_NAME"]);
                    txtCategory.Text = Convert.ToString(drdShowBatchRecord["CATEGORY_DESCRIPTION"]);
                    txtRPUName.Text = Convert.ToString(drdShowBatchRecord["RPU_NAME"]);
                    txtRPUDate.Text = Convert.ToString(drdShowBatchRecord["FILE_DATE"]);
                    txtImportDate.Text = string.Format("{0:dd/MM/yyyy hh:mm tt}", Convert.ToDateTime(drdShowBatchRecord["IMPORTED_DATE"]));

                    //Added by Shrey Kejriwal on 18/05/2012
                    intInvalidReturnValue = Convert.ToInt32(drdShowBatchRecord["INVALID_RETURN"]);

                    //
                    drdShowBatchRecord.Close();
                    drdShowBatchRecord.Dispose();

                    cmbSection.Select();
                    //ControlSummaryChallan(lngChallanID);                
                    return true;
                }
                //-----------------------------------------------------------
                drdShowBatchRecord.Close();
                drdShowBatchRecord.Dispose();

                //ControlSummaryChallan(lngChallanID);
                //-----------------------------------------------------------
                cmnService.J_UserMessage(J_Msg.RecNotExist);
                //-----------------------------------------------------------
                lngChallanID = 0;
                //-----------------------------------------------------------
                if (strCheckFields == "")
                    strSQL = strQuery + " ORDER BY " + strOrderBy;
                else
                    strSQL = strQuery + strCheckFields + " ORDER BY " + strOrderBy;
                //-----------------------------------------------------------
                if (dsetChallanGridClone != null) dsetChallanGridClone.Clear();
                dsetChallanGridClone = dmlService.J_ShowDataInGrid(ref dgvViewChallan, strSQL, strMatrix);       //Show Data into the Grid
                return false;
            }
            catch (Exception err_handler)
            {
                drdShowBatchRecord.Close();
                drdShowBatchRecord.Dispose();
                cmnService.J_UserMessage(err_handler.Message);
                return false;
            }
        }
        #endregion

        #region EnableControl

        #region EnableControl[1]
        private void EnableControl(TextBox txtBox, string Enablity_T_F)
        {
            try
            {
                if (Enablity_T_F.ToUpper() == "T")
                {
                    txtBox.Text = "";
                    txtBox.Enabled = true;
                    txtBox.BackColor = Color.White;
                }
                else if (Enablity_T_F.ToUpper() == "F")
                {
                    txtBox.Text = "";
                    txtBox.Enabled = false;
                    txtBox.BackColor = Color.LightGray;
                }

            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

        #region EnableControl[2]
        private void EnableControl(ComboBox cmbBox, string Enablity_T_F)
        {
            try
            {
                if (Enablity_T_F.ToUpper() == "T")
                {
                    if (cmbBox.SelectedIndex >= 0)
                        cmbBox.SelectedIndex = 0;
                    cmbBox.Enabled = true;
                    cmbBox.BackColor = Color.White;
                }
                else if (Enablity_T_F.ToUpper() == "F")
                {
                    if (cmbBox.SelectedIndex >= 0)
                        cmbBox.SelectedIndex = 0;
                    cmbBox.Enabled = false;
                    cmbBox.BackColor = Color.LightGray;
                }
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion


        #endregion

