        #region ShowCorrectionSummary
        private void ShowCorrectionSummary(long BatchId)
        {
            string strCancellationFlag = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT MODE FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + BatchId));

            if (strCancellationFlag != T_CorrectionMode.TANUpdation)
            {
                grpControlSummary.Visible = true;
                grpCancelStatement.Visible = false;

                string strChangeCompanyDetails = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT BATCH_UPDATION_INDICATOR FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + BatchId));
                if (strChangeCompanyDetails == "0")
                    txtChangeCompanyDetails.Text = "NO";
                else
                    txtChangeCompanyDetails.Text = "YES";
                //
                txtChallanUpdates.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(CHALLAN_UPDATION_INDICATOR) FROM COR_TRN_CHALLAN WHERE CHALLAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchId));
                txtDeducteeUpdates.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE IN ('" + T_CorrectionMode.Modify + "','" + T_CorrectionMode.Delete + "','" + T_CorrectionMode.Add + "') AND BATCH_HEADER_ID = " + BatchId));
                txtPANUpdates.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchId));
                txtNewChallanAdded.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_CHALLAN_ID) FROM COR_TRN_CHALLAN WHERE HDR_CHALLAN_ID = 0 AND BATCH_HEADER_ID = " + BatchId));
                txtNewDeducteeAdded.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.C9Mode + "' AND BATCH_HEADER_ID = " + BatchId));
                //
                if (txtFormNo.Text == T_FormNo.F24Q && txtQtr.Text == T_Qtr.Q4)
                {
                    txtSDPANUpdates.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + BatchId));
                    txtSDUpdates.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE MODE <> '' AND BATCH_HEADER_ID = " + BatchId));
                }
                else
                {
                    lblSDPANUpdates.Visible = false;
                    txtSDPANUpdates.Visible = false;
                    lblSDUpdates.Visible = false;
                    txtSDUpdates.Visible = false;
                }
                //
                txtCorrections.Text = Convert.ToString(cmnService.J_ReturnInt64Value(strChangeCompanyDetails) +
                                      cmnService.J_ReturnInt64Value(txtChallanUpdates.Text) +
                                      cmnService.J_ReturnInt64Value(txtDeducteeUpdates.Text) +
                                      cmnService.J_ReturnInt64Value(txtPANUpdates.Text) +
                                      cmnService.J_ReturnInt64Value(txtNewChallanAdded.Text) +
                                      cmnService.J_ReturnInt64Value(txtNewDeducteeAdded.Text) +
                                      cmnService.J_ReturnInt64Value(txtSDPANUpdates.Text) +
                                      cmnService.J_ReturnInt64Value(txtSDUpdates.Text));
                //
                //if (TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.PROFESSIONAL_EDITION)
                //{
                if (dmlService.J_ReturnNoOfRows("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE BATCH_HEADER_ID = " + BatchId, J_QueryType.DirectQuery) > 0
                    || dmlService.J_ReturnNoOfRows("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE BATCH_HEADER_ID = " + BatchId, J_QueryType.DirectQuery) > 0)
                {
                    //btnBulkPANVerification.Visible = true;
                    //btnBulkPANValidation.Visible = true;
                    grpVerifyButtons.Visible = true;
                }
                else
                {
                    //btnBulkPANVerification.Visible = false;
                    //btnBulkPANValidation.Visible = false;
                    grpVerifyButtons.Visible = false;
                }
                //}
            }
            else
            {
                //WHEN CANCELLATION STATEMENT IS PREPARED
                grpControlSummary.Visible = false;

                grpCancelStatement.Visible = true;
                grpCancelStatement.Text = "";

            }
        }
