        #region UpdateTotalCorrection
        private void UpdateTotalCorrection()
        {
            //-----------------------------------------------------------
            // ADDED BY SHREY KEJRIWAL ON 24/02/2012
            // NEW FN ONLY CALCULATION FOR THE CURRENT BATCH
            //-----------------------------------------------------------
            long lngBATCH_UPDATION_INDICATOR = 0;
            long lngCHALLAN_UPDATION_INDICATOR = 0;
            long lngDeducteeUpdates = 0;
            long lngPANUpdates = 0;
            long lngNewChallanAdded = 0;
            long lngNewDeducteeAdded = 0;
            long lngSDPANUpdates = 0;
            long lngSDUpdates = 0;
            //

            //
            lngBATCH_UPDATION_INDICATOR = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar("SELECT BATCH_UPDATION_INDICATOR FROM COR_TRN_COMPANY WHERE BATCH_HEADER_ID = " + lngBatchId));
            lngCHALLAN_UPDATION_INDICATOR = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(CHALLAN_UPDATION_INDICATOR) FROM COR_TRN_CHALLAN WHERE CHALLAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + lngBatchId));
            lngDeducteeUpdates = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE IN ('" + T_CorrectionMode.Modify + "','" + T_CorrectionMode.Delete + "','" + T_CorrectionMode.Add + "') AND BATCH_HEADER_ID = " + lngBatchId));
            lngPANUpdates = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + lngBatchId));
            lngNewChallanAdded = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_CHALLAN_ID) FROM COR_TRN_CHALLAN WHERE HDR_CHALLAN_ID =0 AND BATCH_HEADER_ID = " + lngBatchId));
            lngNewDeducteeAdded = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_DEDUCTEE_DETAIL_ID) FROM COR_TRN_DEDUCTEE_DETAILS WHERE MODE = '" + T_CorrectionMode.C9Mode + "' AND BATCH_HEADER_ID = " + lngBatchId));
            lngSDPANUpdates = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE PAN_UPDATION_INDICATOR =" + T_UPDATION_INDICATOR.ON + " AND BATCH_HEADER_ID = " + lngBatchId));
            lngSDUpdates = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(TRN_SALARY_DETAILS_ID) FROM COR_TRN_SALARY_DETAILS WHERE MODE <> '' AND BATCH_HEADER_ID = " + lngBatchId));
            //
            strSQL = "UPDATE COR_HDR_BATCH SET  " +
                "            TOTAL_CORRECTION = " + (lngBATCH_UPDATION_INDICATOR + lngCHALLAN_UPDATION_INDICATOR + lngDeducteeUpdates + lngPANUpdates + lngNewChallanAdded + lngNewDeducteeAdded + lngSDPANUpdates + lngSDUpdates) + " " +
                "     WHERE  BATCH_HEADER_ID  = " + lngBatchId;
            if (dmlService.J_ExecSql(strSQL) == false)
            {
                return;
            }
        }
        #endregion

