                    //txtTotalDeducteeTDS.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(TOTAL_TAX_DEDUCTED) AS SUM_TOTAL_AMOUNT FROM TEMP_DEDUCTEE_DETAILS")) == "" ? "0" : Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(TOTAL_TAX_DEDUCTED) AS SUM_TOTAL_AMOUNT FROM TEMP_DEDUCTEE_DETAILS"))));
                    //txtAmountPaid.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(AMOUNT_PAID) AS PAYMENT_AMOUNT FROM TEMP_DEDUCTEE_DETAILS")) == "" ? "0" : Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(AMOUNT_PAID) AS PAYMENT_AMOUNT FROM TEMP_DEDUCTEE_DETAILS"))));
                    ////----

                    LoadTempChallanGrid();
                    return true;
                }
                return false;
            }
