        #region LoadTempChallanGrid
        public void LoadTempChallanGrid()
        {
            //Adding Challan Information to temp_table

            #region CREATING TEMPORARY TABLE FOR COMPARISON
            //
            strSQL = "DELETE FROM TEMP_CORR_CHALLAN";
            dmlService.J_ExecSql(strSQL);
            // UPDATING BLANK TO ZERO TDS
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET TDS = '0' " +
                     "WHERE TDS IS NULL";
            dmlService.J_ExecSql(strSQL);
            //
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET TDS = '0' " +
                     "WHERE TDS = ''";
            dmlService.J_ExecSql(strSQL);
            // UPDATING BLANK TO ZERO SURCHARGE
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET SURCHARGE = '0' " +
                     "WHERE SURCHARGE IS NULL";
            dmlService.J_ExecSql(strSQL);
            //
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET SURCHARGE = '0' " +
                     "WHERE SURCHARGE = ''";
            dmlService.J_ExecSql(strSQL);

            // UPDATING BLANK TO ZERO EDUCATION_CESS
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET EDUCATION_CESS = '0' " +
                     "WHERE EDUCATION_CESS IS NULL";
            dmlService.J_ExecSql(strSQL);
            //
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET EDUCATION_CESS = '0' " +
                     "WHERE EDUCATION_CESS = ''";
            dmlService.J_ExecSql(strSQL);
            // UPDATING BLANK TO ZERO TOTAL_TAX_DEDUCTED
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET TOTAL_TAX_DEDUCTED = '0' " +
                     "WHERE TOTAL_TAX_DEDUCTED IS NULL";
            dmlService.J_ExecSql(strSQL);
            //
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET TOTAL_TAX_DEDUCTED = '0' " +
                     "WHERE TOTAL_TAX_DEDUCTED = ''";
            dmlService.J_ExecSql(strSQL);
            // UPDATING BLANK TO ZERO TOTAL_TAX_DEPOSITED
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET TOTAL_TAX_DEPOSITED = '0' " +
                     "WHERE TOTAL_TAX_DEPOSITED IS NULL";
            dmlService.J_ExecSql(strSQL);
            //
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET TOTAL_TAX_DEPOSITED = '0' " +
                     "WHERE TOTAL_TAX_DEPOSITED = ''";
            dmlService.J_ExecSql(strSQL);
            // UPDATING NULL TO ZERO 
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET DEDUCTEE_SERIAL_NO = '0' " +
                     "WHERE DEDUCTEE_SERIAL_NO IS NULL";
            dmlService.J_ExecSql(strSQL);
            // UPDATING NULL TO ZERO 
            strSQL = "UPDATE TEMP_DEDUCTEE_DETAILS " +
                     "SET CHALLAN_SERIAL_NO = '0' " +
                     "WHERE CHALLAN_SERIAL_NO IS NULL";
            dmlService.J_ExecSql(strSQL);
            //--
            strSQL = "INSERT INTO TEMP_CORR_CHALLAN " +
                //"SELECT CINT(EXISTING.CHALLAN_SERIAL_NO)      AS CHALLAN_SERIAL_NO, " +
                     "SELECT CLNG(EXISTING.CHALLAN_SERIAL_NO)      AS CHALLAN_SERIAL_NO, " +
                     "       CDBL(EXISTING.CHALLAN_TAX)            AS CHALLAN_TAX, " +
                     "       CDBL(EXISTING.COUNT_DEDUCTEE_RECORDS) AS EXISTING_COUNT_DEDUCTEE_RECORDS, " +
                     "       CDBL(EXISTING.CTRL_TDS)               AS EXISTING_CTRL_TDS, " +
                     "       CDBL(EXISTING.CTRL_SURCHARGE)         AS EXISTING_CTRL_SURCHARGE, " +
                     "       CDBL(EXISTING.CTRL_EDU_CESS)          AS EXISTING_CTRL_EDU_CESS, " +
                     "       CDBL(EXISTING.CTRL_TOT)               AS EXISTING_CTRL_TOT, " +
                     "       CDBL(EXISTING.CTRL_TOT_TAX)           AS EXISTING_CTRL_TOT_TAX, " +
                //"       CINT(NEW.COUNT_DEDUCTEE_RECORDS)      AS NEW_COUNT_DEDUCTEE_RECORDS, " +
                     "       CLNG(NEW.COUNT_DEDUCTEE_RECORDS)      AS NEW_COUNT_DEDUCTEE_RECORDS, " +
                     "       CDBL(NEW.CTRL_TDS)                    AS NEW_CTRL_TDS, " +
                     "       CDBL(NEW.CTRL_SURCHARGE)              AS NEW_CTRL_SURCHARGE, " +
                     "       CDBL(NEW.CTRL_EDU_CESS)               AS NEW_CTRL_EDU_CESS, " +
                     "       CDBL(NEW.CTRL_TOT)                    AS NEW_CTRL_TOT, " +
                     "       CDBL(NEW.CTRL_TOT_TAX)                AS NEW_CTRL_TOT_TAX " +
                     "FROM       (SELECT    COR_TRN_CHALLAN.SL_NO          AS CHALLAN_SERIAL_NO, " +
                     "                      COR_TRN_CHALLAN.TDS + COR_TRN_CHALLAN.SURCHARGE + COR_TRN_CHALLAN.EDUCATION_CESS AS CHALLAN_TAX, " +
                     "                  " + cmnService.J_SQLDBFormat("COUNT(COR_TRN_DEDUCTEE_DETAILS.TRN_DEDUCTEE_DETAIL_ID)", J_ColumnType.Double, J_SQLColFormat.NullCheck) + " AS COUNT_DEDUCTEE_RECORDS, " +
                     "                      COR_TRN_CHALLAN.CTRL_TDS       AS CTRL_TDS, " +
                     "                      COR_TRN_CHALLAN.CTRL_SURCHARGE AS CTRL_SURCHARGE, " +
                     "                      COR_TRN_CHALLAN.CTRL_EDU_CESS  AS CTRL_EDU_CESS, " +
                     "                      COR_TRN_CHALLAN.CTRL_TOT_TAX   AS CTRL_TOT_TAX, " +
                     "                      COR_TRN_CHALLAN.CTRL_TOT       AS CTRL_TOT " +
                     "            FROM      COR_TRN_CHALLAN " +
                     "            LEFT JOIN COR_TRN_DEDUCTEE_DETAILS " +
                     "             ON COR_TRN_CHALLAN.TRN_CHALLAN_ID = COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID " +
                     "            GROUP BY COR_TRN_CHALLAN.BATCH_HEADER_ID, " +
                     "                     COR_TRN_CHALLAN.TRN_CHALLAN_ID, " +
                     "                     COR_TRN_CHALLAN.SL_NO, " +
                     "                     COR_TRN_CHALLAN.TDS + COR_TRN_CHALLAN.SURCHARGE + COR_TRN_CHALLAN.EDUCATION_CESS, " +
                     "                     COR_TRN_CHALLAN.CTRL_TDS, " +
                     "                     COR_TRN_CHALLAN.CTRL_SURCHARGE, " +
                     "                     COR_TRN_CHALLAN.CTRL_EDU_CESS, " +
                     "                     COR_TRN_CHALLAN.CTRL_TOT_TAX, " +
                     "                     COR_TRN_CHALLAN.CTRL_TOT " +
                     "            HAVING   COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId + " ) AS EXISTING " +
                //"INNER JOIN (SELECT " + cmnService.J_SQLDBFormat("CINT(TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO)", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + " AS CHALLAN_SERIAL_NO, " +
                     "INNER JOIN (SELECT " + cmnService.J_SQLDBFormat("CLNG(TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO)", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + " AS CHALLAN_SERIAL_NO, " +
                     "                   " + cmnService.J_SQLDBFormat("COUNT(DEDUCTEE_DETAILS_ID)", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + "         AS COUNT_DEDUCTEE_RECORDS, " +
                     "                   " + cmnService.J_SQLDBFormat("SUM(CDBL(TDS))", J_ColumnType.Double, J_SQLColFormat.NullCheck) + "                    AS CTRL_TDS, " +
                     "                   " + cmnService.J_SQLDBFormat("SUM(CDBL(SURCHARGE))", J_ColumnType.Double, J_SQLColFormat.NullCheck) + "              AS CTRL_SURCHARGE, " +
                     "                   " + cmnService.J_SQLDBFormat("SUM(CDBL(EDUCATION_CESS))", J_ColumnType.Double, J_SQLColFormat.NullCheck) + "         AS CTRL_EDU_CESS, " +
                     "                   " + cmnService.J_SQLDBFormat("SUM(CDBL(TOTAL_TAX_DEDUCTED))", J_ColumnType.Double, J_SQLColFormat.NullCheck) + "     AS CTRL_TOT, " +
                     "                   " + cmnService.J_SQLDBFormat("SUM(CDBL(TOTAL_TAX_DEPOSITED))", J_ColumnType.Double, J_SQLColFormat.NullCheck) + "    AS CTRL_TOT_TAX " +
                     "            FROM TEMP_DEDUCTEE_DETAILS " +
                     "            GROUP BY TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO) AS NEW " +
                     "ON          " + cmnService.J_SQLDBFormat("EXISTING.CHALLAN_SERIAL_NO", J_ColumnType.Integer, J_SQLColFormat.Cast) + " " +
                     "          = " + cmnService.J_SQLDBFormat("NEW.CHALLAN_SERIAL_NO ", J_ColumnType.Integer, J_SQLColFormat.Cast) + " ";

            if (dmlService.J_ExecSql(strSQL) == false) return;

            #endregion

            string[,] strMatrixChallanDetails = {{"Sl No.", "50", "S", "", "", "", ""},
                                        {"Challan Tax", "100", "0.00", "R", "", "", "T"},
                                        {"Existing Ded. Records", "120", "0", "R", "", "", "T"},
                                        {"Existing Ded. Total", "100", "0.00", "R", "", "", "T"},
                                        {"Add Records", "90", "0", "R", "", "", "T"},
                                        {"Add Ded Total", "90", "0.00", "R", "", "", "T"},
                                        {"Ded. Records", "90", "0", "R", "", "", "T"},
                                        {"Ded Total", "100", "0.00", "R", "", "", "T"},
                                        {"Difference", "100", "0.00", "R", "", "", "T"},
                                        {"Status .", "95", "0.00", "R", "", "", "T"}};
            //-----------------------------------------------------------
            //strMatrix = strMatrix1;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            //-----------------------------------------------------------
            string[,] strError = {{"(CHALLAN_TAX - EXISTING_CTRL_TOT_TAX - NEW_CTRL_TOT_TAX) < 0 ", "F", "Error!!", "T"},
                                                {"JAYA", "F", "", "T"}};

            strOrderBy = "CHALLAN_SERIAL_NO";

            strQuery = "SELECT CHALLAN_SERIAL_NO                            AS SERIAL_NO," +
                       "       CHALLAN_TAX                                  AS TAX," +
                       "       EXISTING_COUNT_DEDUCTEE_RECORDS              AS EXISTING_DEDUCTEE_RECORDS," +
                       "       EXISTING_CTRL_TOT_TAX                        AS EXISTING_CTRL_TAX_DEPOSITED," +
                       "       NEW_COUNT_DEDUCTEE_RECORDS                   AS ADD_COUNT_DEDUCTEE_RECORDS," +
                       "       NEW_CTRL_TOT_TAX                             AS ADD_CTRL_TOT_TAX," +
                       "       EXISTING_COUNT_DEDUCTEE_RECORDS +  NEW_COUNT_DEDUCTEE_RECORDS AS NEW_RECORDS," +
                       "       EXISTING_CTRL_TOT_TAX +  NEW_CTRL_TOT_TAX    AS NEW_ADD_CTRL_TOT_TAX," +
                       "       CHALLAN_TAX - EXISTING_CTRL_TOT_TAX - NEW_CTRL_TOT_TAX AS DIFFERENCE," +
                       "    " + cmnService.J_SQLDBFormat(strError, J_SQLColFormat.Case_End) + " AS STATUS " +
                       "FROM   TEMP_CORR_CHALLAN ";

            strSQL = strQuery + "ORDER BY " + strOrderBy;
            //-----------------------------------------------------------

            dgcViewChallanExcel.Visible = true;

            dsetGridClone = dmlService.J_ShowDataInGrid(ref  dgcViewChallanExcel, strSQL, strMatrixChallanDetails);     //Show Data into the Grid
        }
        #endregion

        #region LoadDeducteeDetailsGrid
        private bool LoadDeducteeDetailsGrid(long ChallanId)
        {
            try
            {
                string strSectionSize = "0";
                if (Convert.ToInt32(txtFAYearID.Text) < T_FinancialYearID.F2013_14ID)
                    strSectionSize = "0";
                else
                    strSectionSize = "55";

                //-----------------------------------------------------------
                string[,] strMatrixDeducteeDetails = {{"DeducteeDetailsID", "0", "", "Right", "", "", ""},
                                        {"Challan Srl No.", "100", "S", "", "", "", ""},
                                        {"Srl No.", "100", "S", "", "", "", ""},
                                        {"PAN", "100", "S", "", "", "", ""},
                                        {"Name", "250", "S", "", "", "", ""},
                                        {"Date", "100", "dd/MM/yyyy", "", "", "", ""},
                                        {"Section", strSectionSize, "S", "", "", "", ""},
                                        {"Amount Paid", "100", "0.00", "R", "", "", "T"},
                                        {"Total TDS", "100", "0.00", "R", "", "", "T"},
                                        {"TDS Deposited", "100", "0.00", "R", "", "", "T"}};
                //-----------------------------------------------------------
                //strMatrix = strMatrix1;
                //-----------------------------------------------------------
                /* (1) Column Value
                 * (2) Column Data Type
                 * (3) Replace String
                 * (4) Replace String Data Type */
                //-----------------------------------------------------------
                //-----------------------------------------------------------
                strOrderBy = "DEDUCTEE_DETAILS_ID";
                strQuery = "SELECT DEDUCTEE_DETAILS_ID       AS DEDUCTEE_DETAILS_ID," +
                          "        CHALLAN_SERIAL_NO         AS CHALLAN_SERIAL_NO," +
                          "        DEDUCTEE_SERIAL_NO        AS SERIAL_NO," +
                          "        DEDUCTEE_PAN              AS PAN," +
                          "        DEDUCTEE_NAME             AS NAME," +
                          "        " + cmnService.J_SQLDBFormat("DATE_PAYMENT", J_SQLColFormat.DateFormatDDMMYYYY) + " AS DATE_PAYMENT," +
                          "        SECTION_CODE              AS SECTION_NAME," +
                          "        CDBL(AMOUNT_PAID)         AS AMOUNT_PAID," +
                          "        CDBL(TOTAL_TAX_DEDUCTED)  AS TOTAL_TAX_DEDUCTED," +
                          "        CDBL(TOTAL_TAX_DEPOSITED) AS TOTAL_TAX_DEPOSITED " +
                          "FROM    TEMP_DEDUCTEE_DETAILS " +
                          "WHERE   CHALLAN_SERIAL_NO = '" + ChallanId + "' ";
                //-----------------------------------------------------------
                strSQL = strQuery + " ORDER BY " + strOrderBy;
                //-----------------------------------------------------------
                if (dsetGridClone != null) dsetGridClone.Clear();
                dsetGridClone = dmlService.J_ShowDataInGrid(ref  dgcViewDeducteeExcel, strSQL, strMatrixDeducteeDetails);       //Show Data into the Grid
                //--
                return true;
            }
            catch
            {
                return false;
            }
        }
