                                      {"TEMP_DEDUCTEE_DETAILS.SURCHARGE = ''" , "F", "0", "F"}};
                //
                string[,] strEducationCess = {{"TEMP_DEDUCTEE_DETAILS.EDUCATION_CESS <> ''" , "F", "CCUR(TEMP_DEDUCTEE_DETAILS.EDUCATION_CESS)", "F"},
                                      {"TEMP_DEDUCTEE_DETAILS.EDUCATION_CESS = ''" , "F", "0", "F"}};
                //
                string[,] strTaxDed = {{"TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEDUCTED <> ''" , "F", "CCUR(TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEDUCTED)", "F"},
                                      {"TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEDUCTED = ''" , "F", "0", "F"}};
                //
                string[,] strTaxDep = {{"TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEPOSITED <> ''" , "F", "CCUR(TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEPOSITED)", "F"},
                                      {"TEMP_DEDUCTEE_DETAILS.TOTAL_TAX_DEPOSITED = ''" , "F", "0", "F"}};
                //
                string[,] strTotValPur = {{"TEMP_DEDUCTEE_DETAILS.TOT_VALUE_PURCHASE <> ''" , "F", "CCUR(TEMP_DEDUCTEE_DETAILS.TOT_VALUE_PURCHASE)", "F"},
                                      {"TEMP_DEDUCTEE_DETAILS.TOT_VALUE_PURCHASE = ''" , "F", "0", "F"}};

                string[,] strCashBookEntry = {{"TEMP_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY = 'N'" , "F", "0", "N"},
                                              {"TEMP_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY = 'No'" , "F", "0", "N"},
                                              {"TEMP_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY = 'Y'" , "F", "1", "N"},
                                              {"TEMP_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY = 'Yes'" , "F", "1", "N"},
                                              {"TEMP_DEDUCTEE_DETAILS.CASH_BOOK_ENTRY = ''" , "F", "0", "N"}};


                //Added by Shrey Kejriwal on 04/11/2011

                string[,] strCorrectionMode = {{"COR_TRN_CHALLAN.IMPORT_FLAG = 1" , "F", T_CorrectionMode.Add, "T"},
                                               {"COR_TRN_CHALLAN.IMPORT_FLAG = 0" , "F", T_CorrectionMode.C9Mode, "T"}};
                //
                if (Convert.ToInt32(txtFAYearID.Text) < T_FinancialYearID.F2013_14ID)
                {

                }
                else
                {
                }
                //--
                dmlService.J_BeginTransaction();
                //--
                strSQL = "UPDATE  TEMP_DEDUCTEE_DETAILS SET REASON = '' WHERE REASON IS NULL";
                dmlService.J_ExecSql(strSQL);
                //--
                strSQL = "INSERT INTO COR_TRN_DEDUCTEE_DETAILS " +
                                 "           (TRN_CHALLAN_ID," +
                                 "            HDR_DEDUCTEE_DETAIL_ID," +
                                 "            MODE," +
                                 "            BATCH_HEADER_ID," +
                                 "            SL_NO," +
                                 "            DEDUCTEE_NAME," +
                                 "            DEDUCTEE_PAN," +
                                 "            DEDUCTEE_CODE," +
                                 "            PAYMENT_DATE," +
                                 "            DEDUCTED_DATE," +
                                 "            PAYMENT_AMOUNT," +
                                 "            RATE," +
                                 "            TAX_AMOUNT," +
                                 "            SURCHARGE_AMOUNT," +
                                 "            CESS_AMOUNT," +
                                 "            TOTAL_AMOUNT," +
                                 "            TAX_DEPOSITED_AMOUNT," +
                                 //"            NON_DEDUCTION_FLAG, " +
                                 //"            CASH_BOOK_ENTRY," +
                                 "            SECTION_ID," +
                                 "            REASON_ID," +
                                 "            CERTIFICATE_NO";
                if (txtFormNo.Text == T_FormNo.F27Q)
                    strSQL = strSQL + ",GROSSING_UP_INDICATOR)";
                else if (txtFormNo.Text == T_FormNo.F27EQ)
                    strSQL = strSQL + ",TOT_VALUE_PURCHASE)";
                else
                    strSQL = strSQL + ")";
                strSQL = strSQL + " SELECT COR_TRN_CHALLAN.TRN_CHALLAN_ID," +
                       "                   0, " +
                       "                   " + cmnService.J_SQLDBFormat(strCorrectionMode, J_SQLColFormat.Case_End) + "," +
                       "                   " + lngBatchId + "," +
                    //"                   CINT(TEMP_DEDUCTEE_DETAILS.DEDUCTEE_SERIAL_NO)," +
                       "                   CLNG(TEMP_DEDUCTEE_DETAILS.DEDUCTEE_SERIAL_NO)," +
                       "                   TEMP_DEDUCTEE_DETAILS.DEDUCTEE_NAME," +
                       "                   TEMP_DEDUCTEE_DETAILS.DEDUCTEE_PAN," +
                       "                   TEMP_DEDUCTEE_DETAILS.DEDUCTEE_CODE," +
                       "                   CDATE(TEMP_DEDUCTEE_DETAILS.DATE_PAYMENT)," +
                       "                   CDATE(TEMP_DEDUCTEE_DETAILS.DATE_PAYMENT)," +
                       "                  " + cmnService.J_SQLDBFormat(strAmtPaid, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strRate, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strTDS, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strSurcharge, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strEducationCess, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strTaxDed, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat(strTaxDep, J_SQLColFormat.Case_End) + "," +
                       //"                  TEMP_DEDUCTEE_DETAILS.REASON, " +
                       //"                  " + cmnService.J_SQLDBFormat(strCashBookEntry, J_SQLColFormat.Case_End) + "," +
                       "                  " + cmnService.J_SQLDBFormat("MST_SECTION.SECTION_ID", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + "," +
                       "                  " + cmnService.J_SQLDBFormat("REASON_ASPER_FORM.REASON_ID", J_ColumnType.Integer, J_SQLColFormat.NullCheck) + "," +
                       "                   TEMP_DEDUCTEE_DETAILS.CERTIFICATE_NO ";

                if (txtFormNo.Text == T_FormNo.F27Q)
                    strSQL = strSQL + ",TEMP_DEDUCTEE_DETAILS.GROSSING_UP_INDICATOR";
                else if (txtFormNo.Text == T_FormNo.F27EQ)
                    strSQL = strSQL + "," + cmnService.J_SQLDBFormat(strTotValPur, J_SQLColFormat.Case_End) + " ";
                else
                    strSQL = strSQL + " ";
                strSQL = strSQL + " FROM  (((TEMP_DEDUCTEE_DETAILS INNER JOIN COR_TRN_CHALLAN" +
                    //"               WHERE CINT(TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO) = COR_TRN_CHALLAN.SL_NO" +
                    "               ON    CLNG(TEMP_DEDUCTEE_DETAILS.CHALLAN_SERIAL_NO) = COR_TRN_CHALLAN.SL_NO)" +
                    "               LEFT  JOIN MST_SECTION " +
                    "                       ON TEMP_DEDUCTEE_DETAILS.SECTION_CODE       = MST_SECTION.SECTION_NO) " +
                    "               LEFT  JOIN (SELECT REASON_ID, " +
                    "                              REASON " +
                    "                       FROM MST_REASON " +
                    "                       WHERE FORM_NO = '" + txtFormNo.Text + "') AS REASON_ASPER_FORM " +
                    "                       ON TEMP_DEDUCTEE_DETAILS.REASON = REASON_ASPER_FORM.REASON) " +
                    "               WHERE COR_TRN_CHALLAN.BATCH_HEADER_ID               = " + lngBatchId + " " +
                    "               ORDER BY CLNG(TEMP_DEDUCTEE_DETAILS.DEDUCTEE_SERIAL_NO)";
                //-----------------------------------------------------------
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    btnImport.Enabled = false;
                    dmlService.J_Rollback();
                    return false;
                }

                //UPDATE DEDUCTED DATE TO BLANK IF TOTAL DEDUCTION IS ZERO
                strSQL = "UPDATE COR_TRN_DEDUCTEE_DETAILS SET DEDUCTED_DATE = NULL WHERE TOTAL_AMOUNT = 0";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    btnImport.Enabled = false;
                    return false;
                }


                //UPDATE CONTROL TOTALS OF CHALLAN TABLE USING TEMP TABLE

                //UPDATING IMPORTED CHALLANS

                //Modified by Shrey Kejriwal on 23/02/2012

                //UPDATING EXISTING DEDUCTEE RECORD NO ONLY IF VALUE EXISTS IN THE FIELD (EXISTING DEDUCTEE RECORD NO)
                string strUpdateExistingDeducteeRecordNo = string.Empty;

                if (blnExpectedDeducteeRecord == true)
                    strUpdateExistingDeducteeRecordNo = ", COR_TRN_CHALLAN.EXPECTED_DEDUCTEE_RECORD_NO = COR_TRN_CHALLAN.EXPECTED_DEDUCTEE_RECORD_NO + TEMP_CORR_CHALLAN.NEW_COUNT_DEDUCTEE_RECORDS";

                strSQL = "UPDATE COR_TRN_CHALLAN" +
                "                INNER JOIN  TEMP_CORR_CHALLAN " +
                "                  ON COR_TRN_CHALLAN.SL_NO     = TEMP_CORR_CHALLAN.CHALLAN_SERIAL_NO " +
                "         SET    COR_TRN_CHALLAN.MODE           = '" + T_CorrectionMode.C3 + "', " +
                "                COR_TRN_CHALLAN.CTRL_TDS       = COR_TRN_CHALLAN.CTRL_TDS       + TEMP_CORR_CHALLAN.NEW_CTRL_TDS," +
                "                COR_TRN_CHALLAN.CTRL_SURCHARGE = COR_TRN_CHALLAN.CTRL_SURCHARGE + TEMP_CORR_CHALLAN.NEW_CTRL_SURCHARGE," +
                "                COR_TRN_CHALLAN.CTRL_EDU_CESS  = COR_TRN_CHALLAN.CTRL_EDU_CESS  + TEMP_CORR_CHALLAN.NEW_CTRL_EDU_CESS," +
                "                COR_TRN_CHALLAN.CTRL_TOT       = COR_TRN_CHALLAN.CTRL_TOT       + TEMP_CORR_CHALLAN.NEW_CTRL_TOT," +
                "                COR_TRN_CHALLAN.CTRL_TOT_TAX   = COR_TRN_CHALLAN.CTRL_TOT_TAX   + TEMP_CORR_CHALLAN.NEW_CTRL_TOT_TAX " +
                "                " + strUpdateExistingDeducteeRecordNo + " " +
                "         WHERE COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId + " " +
                "         AND   COR_TRN_CHALLAN.IMPORT_FLAG = 1";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return false;
                }

                //UPDATING NEW CHALLANS
                strSQL = "UPDATE COR_TRN_CHALLAN" +
                "                INNER JOIN  TEMP_CORR_CHALLAN " +
                "                  ON COR_TRN_CHALLAN.SL_NO     = TEMP_CORR_CHALLAN.CHALLAN_SERIAL_NO " +
                "         SET    COR_TRN_CHALLAN.CTRL_TDS       = COR_TRN_CHALLAN.CTRL_TDS       + TEMP_CORR_CHALLAN.NEW_CTRL_TDS," +
                "                COR_TRN_CHALLAN.CTRL_SURCHARGE = COR_TRN_CHALLAN.CTRL_SURCHARGE + TEMP_CORR_CHALLAN.NEW_CTRL_SURCHARGE," +
                "                COR_TRN_CHALLAN.CTRL_EDU_CESS  = COR_TRN_CHALLAN.CTRL_EDU_CESS  + TEMP_CORR_CHALLAN.NEW_CTRL_EDU_CESS," +
                "                COR_TRN_CHALLAN.CTRL_TOT       = COR_TRN_CHALLAN.CTRL_TOT       + TEMP_CORR_CHALLAN.NEW_CTRL_TOT," +
                "                COR_TRN_CHALLAN.CTRL_TOT_TAX   = COR_TRN_CHALLAN.CTRL_TOT_TAX   + TEMP_CORR_CHALLAN.NEW_CTRL_TOT_TAX" +
                "         WHERE COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId + " " +
                "         AND   COR_TRN_CHALLAN.IMPORT_FLAG = 0";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return false;
                }
                //-- UPDATE ALL EXISTING COR_TRN_DEDUCTEE_DETAILS WITH THE SECTION ID
                strSQL = "UPDATE COR_TRN_DEDUCTEE_DETAILS " +
                         "INNER JOIN COR_TRN_CHALLAN " +
                         "ON     COR_TRN_DEDUCTEE_DETAILS.TRN_CHALLAN_ID = COR_TRN_CHALLAN.TRN_CHALLAN_ID " +
                         "SET    COR_TRN_DEDUCTEE_DETAILS.SECTION_ID     = COR_TRN_CHALLAN.SECTION_ID " +
                         "WHERE  COR_TRN_DEDUCTEE_DETAILS.SECTION_ID     = 0 " +
                         "AND    COR_TRN_CHALLAN.SECTION_ID             <> 0 " +
                         "AND    COR_TRN_CHALLAN.BATCH_HEADER_ID = " + lngBatchId;
                dmlService.J_ExecSql(strSQL);
                //--
                dmlService.J_Commit();
                //
                UpdateTotalCorrection();

                btnImport.Enabled = false;
                return true;
            }
            catch (Exception e)
            {
                dmlService.J_Rollback();
                cmnService.J_UserMessage(e.Message);
                btnImport.Enabled = false;

                return false;
            }
        }

        #endregion

        #region DROP_TEMP_TABLES
        private bool DROP_TEMP_TABLES()
        {
            try
            {
                //
                if (dmlService.J_IsDatabaseObjectExist("TEMP_DEDUCTEE_DETAILS") == true)
                {
                    strSQL = "DROP TABLE TEMP_DEDUCTEE_DETAILS";
                    dmlService.J_ExecSql(strSQL);
                }
                //
                if (dmlService.J_IsDatabaseObjectExist("TEMP_CORR_CHALLAN") == true)
                {
                    strSQL = "DROP TABLE TEMP_CORR_CHALLAN";
                    dmlService.J_ExecSql(strSQL);
                }


                return true;
            }
            catch
            {
                return false;
            }
        }
        #endregion

