        #region Return_Next_Deductee_Record_no
        public void Return_Next_Deductee_Record_no()
        {
            long lngSerialNo;

            strSQL = "SELECT EXPECTED_DEDUCTEE_RECORD_NO FROM COR_TRN_CHALLAN WHERE TRN_CHALLAN_ID = " + lngChallanID;
            lngSerialNo = cmnService.J_NullToZero(dmlService.J_ExecSqlReturnScalar(strSQL));

            if (lngSerialNo == 0)
            {
                txtDeducteeSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("COR_TRN_DEDUCTEE_DETAILS", "SL_NO", "TRN_CHALLAN_ID = " + lngChallanID + "") + 1);
            }
            else
                txtDeducteeSrlNo.Text = Convert.ToString(lngSerialNo);
        }
        #endregion

        #region LoadFormComponents
        private void LoadFormComponents()
        {
            if (cmnService.J_ReturnInt32Value(txtFAYearID.Text) <= T_FinancialYearID.F2012_13ID)
            {
                lblMinor.Visible = false;
                cmbMinorHead.Visible = false;

                lblCheque.Visible = true;
                txtChequeNo.Visible = true;

                lblCDSection.Visible = true;
                cmbSection.Visible = true;
                lblSectionDisplay.Visible = false;

                cmbSection.Select();
                //--DD
                lblSectionChallanDetails.Visible = true;
                txtViewChallanDetailsSection.Visible = true;

                lblDDSectionDisplay.Visible = false;
                lblSection.Visible = false;
                cmbDDSection.Visible = false;

                lblCertificateNo.Visible = false;
                txtCertificateNo.Visible = false;
                //
                grp27Q.Visible = false;
            }
            else
            {
                if (chkBookEntry.Checked == false)
                {
                    lblMinor.Visible = true;
                    cmbMinorHead.Visible = true;
                }

                lblCheque.Visible = false;
                txtChequeNo.Visible = false;

                lblCDSection.Visible = false;
                cmbSection.Visible = false;
                lblSectionDisplay.Visible = false;

                mskDateOfPayment.Select();

                //--DD
                lblSectionChallanDetails.Visible = false;
                txtViewChallanDetailsSection.Visible = false;

                lblDDSectionDisplay.Visible = true;
                lblSection.Visible = true;
                cmbDDSection.Visible = true;

                lblCertificateNo.Visible = true;
                txtCertificateNo.Visible = true;
                //
                if (txtFormNo.Text == T_FormNo.F27Q)
                    grp27Q.Visible = true;
                else
                    grp27Q.Visible = false;
            }
        }
        #endregion

        #region ImportTextToTables

        private void ImportTextToTables(string tbl, string txtfile, bool hdr)
        {
            //Check 'n Create SCHEMA file for Temp Tables
            string strFolderPath = cmnService.J_GetDirectoryName(strTemporaryfileDeducteePath);

            if (File.Exists(strFolderPath + "\\schema.ini") == true)
            {
                File.Delete(strFolderPath + "\\schema.ini");
            }
            StreamWriter StreamWriter = new StreamWriter(strFolderPath + "\\schema.ini");

            StreamWriter.WriteLine("[" + txtfile + ".txt]");
            StreamWriter.WriteLine("ColNameHeader=" + (hdr == true ? "True" : "False") + "");
            StreamWriter.WriteLine("Format=Delimited(^)");
            StreamWriter.WriteLine("MaxScanRows=0");
            StreamWriter.WriteLine("CharacterSet=ANSI");

            if (txtfile == "DeducteeDetails")
            {
                #region TEMP_DEDUCTEE_DETAILS
                StreamWriter.WriteLine(@"Col1=DEDUCTEE_DETAILS_ID Integer
                                         Col2=DEDUCTEE_SERIAL_NO_ORDER Integer
                                         Col3=DEDUCTEE_SERIAL_NO Char
                                         Col4=DEDUCTEE_SERIAL_NO_CELL Char
                                         Col5=CHALLAN_SERIAL_NO Char
                                         Col6=CHALLAN_SERIAL_NO_CELL Char
                                         Col7=DEDUCTEE_CODE Char
                                         Col8=DEDUCTEE_CODE_CELL Char
                                         Col9=DEDUCTEE_PAN Char
                                         Col10=DEDUCTEE_PAN_CELL Char
                                         Col11=DEDUCTEE_NAME Char
                                         Col12=DEDUCTEE_NAME_CELL Char
                                         Col13=DATE_PAYMENT Char
                                         Col14=DATE_PAYMENT_CELL Char
                                         Col15=AMOUNT_PAID Char
                                         Col16=AMOUNT_PAID_CELL Char
                                         Col17=TDS Char
                                         Col18=TDS_CELL Char
                                         Col19=SURCHARGE Char
                                         Col20=SURCHARGE_CELL Char
                                         Col21=EDUCATION_CESS Char
                                         Col22=EDUCATION_CESS_CELL Char
                                         Col23=TOTAL_TAX_DEDUCTED Char
                                         Col24=TOTAL_TAX_DEDUCTED_CELL Char
                                         Col25=TOTAL_TAX_DEPOSITED Char
                                         Col26=TOTAL_TAX_DEPOSITED_CELL Char
                                         Col27=RATE Char
                                         Col28=RATE_CELL Char
                                         Col29=REASON Char
                                         Col30=REASON_CELL Char
                                         Col31=GROSSING_UP_INDICATOR Char
                                         Col32=GROSSING_UP_INDICATOR_CELL Char
                                         Col33=TOT_VALUE_PURCHASE Char
                                         Col34=TOT_VALUE_PURCHASE_CELL Char                                     
                                         Col35=SECTION_CODE Char
                                         Col36=SECTION_CODE_CELL Char
                                         Col37=DEDUCTEE_MASTER_ID Integer
                                         Col38=CERTIFICATE_NO Char
                                         Col39=CERTIFICATE_NO_CELL Char");

                                         //Col35=CASH_BOOK_ENTRY Char
                                         //Col36=CASH_BOOK_ENTRY_CELL Char   
//                                         Col37=TDS_APPLICABILITY Char
//                                         Col38=TDS_APPLICABILITY_CELL Char
//                                         Col39=REMITTANCE Char
//                                         Col40=REMITTANCE_CELL Char
//                                         Col41=UNIQUE_ACKN Char
//                                         Col42=UNIQUE_ACKN_CELL Char
//                                         Col43=COUNTRY Char
//                                         Col44=COUNTRY_CELL Char
                #endregion
            }

            StreamWriter.Close();

            //Check 'n Create Temp Tables
            if (dmlService.J_IsDatabaseObjectExist(tbl) == true)
            {
                strSQL = "DROP TABLE [" + tbl + "]";

                dmlService.J_ExecSql(strSQL);
            }
            strSQL = "SELECT * INTO [" + tbl + "] FROM " +
                     @"[Text; DATABASE=" + strFolderPath + "].[" + txtfile + ".txt]";

            dmlService.J_ExecSql(strSQL);
        }
        #endregion

        #endregion

    }
}

